LOCAL_CORS_ORIGIN_REGEX = r"^https?://(localhost|127\.0\.0\.1|\[::1\])(?::\d+)?$"
LAN_CORS_ORIGIN_REGEX = (
    r"^https?://("
    r"10(?:\.\d{1,3}){3}|"
    r"192\.168(?:\.\d{1,3}){2}|"
    r"172\.(?:1[6-9]|2\d|3[0-1])(?:\.\d{1,3}){2}|"
    r"[^/:]+\.local"
    r")(?::\d+)?$"
)
CORS_ORIGIN_REGEX = os.environ.get(
    "INSPECTION_CORS_ORIGIN_REGEX",
    LAN_CORS_ORIGIN_REGEX if os.environ.get("INSPECTION_ENABLE_LAN_CORS") == "1" else LOCAL_CORS_ORIGIN_REGEX,
)
CORS_ORIGINS = [
    origin.strip()
    for origin in os.environ.get("INSPECTION_CORS_ORIGINS", "").split(",")
    if origin.strip()
]
app.add_middleware(
    CORSMiddleware,
    allow_origins=CORS_ORIGINS,
    allow_origin_regex=CORS_ORIGIN_REGEX,
    allow_credentials=True,
    allow_methods=["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"],
    allow_headers=["*"],
)

def normalize_origin(value: str) -> str:
    parsed = urlsplit(value)
    if not parsed.scheme or not parsed.netloc:
        return ""
    scheme = parsed.scheme.lower()
    hostname = (parsed.hostname or "").lower()
    if not hostname:
        return ""
    port = parsed.port
    default_port = 443 if scheme == "https" else 80
    netloc = hostname if port in (None, default_port) else f"{hostname}:{port}"
    return f"{scheme}://{netloc}"


def same_origin(origin: str, host: str) -> bool:
    parsed_origin = urlsplit(origin)
    if not parsed_origin.scheme or not parsed_origin.netloc:
        return False
    parsed_host = urlsplit(f"{parsed_origin.scheme}://{host}")
    return (parsed_origin.hostname or "").lower() == (parsed_host.hostname or "").lower() and (
        parsed_origin.port or (443 if parsed_origin.scheme == "https" else 80)
    ) == (parsed_host.port or (443 if parsed_origin.scheme == "https" else 80))


def cors_origin_allowed(origin: str) -> bool:
    normalized = normalize_origin(origin)
    if not normalized:
        return False
    if normalized in {normalize_origin(item) for item in CORS_ORIGINS}:
        return True
    return re.match(CORS_ORIGIN_REGEX, normalized) is not None


def clean_username(value: Any) -> str:
    username = re.sub(r"[^a-zA-Z0-9_.@-]+", "_", str(value or "").strip().lower())
    return username[:64]


def clean_display_name(value: Any, fallback: str) -> str:
    name = str(value or "").strip()
    return name[:80] if name else fallback


def normalize_role(value: Any) -> str:
    role = str(value or "").strip().lower()
    return "admin" if role == "admin" else "user"


def normalize_permissions(values: Any) -> list[str]:
    if not isinstance(values, list):
        return []
    seen: set[str] = set()
    permissions: list[str] = []
    for raw in values:
        permission = str(raw or "").strip()
        if permission in FEATURE_PERMISSIONS and permission not in ADMIN_ONLY_PERMISSIONS and permission not in seen:
            seen.add(permission)
            permissions.append(permission)
    return permissions


def password_hash(password: str) -> str:
    if len(password) < 8:
        raise HTTPException(status_code=400, detail="Password must be at least 8 characters")
    salt = secrets.token_hex(16)
    digest = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), bytes.fromhex(salt), PASSWORD_HASH_ITERATIONS)
    return f"pbkdf2_sha256${PASSWORD_HASH_ITERATIONS}${salt}${digest.hex()}"


def verify_password(password: str, stored_hash: str) -> bool:
    try:
        algorithm, iterations_raw, salt_hex, digest_hex = str(stored_hash or "").split("$", 3)
        if algorithm != "pbkdf2_sha256":
            return False
        iterations = int(iterations_raw)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), bytes.fromhex(salt_hex), iterations)
        return hmac.compare_digest(actual, expected)
    except (TypeError, ValueError, binascii.Error):
        return False


def empty_auth_store() -> dict[str, Any]:
    return {"users": [], "sessions": {}}


def load_auth_store() -> dict[str, Any]:
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        return auth_store_from_rows(repository.fetch_all("users"), repository.fetch_all("auth_sessions"))
    if not AUTH_PATH.exists():
        return empty_auth_store()
    try:
        raw = json.loads(AUTH_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return empty_auth_store()
    users = raw.get("users") if isinstance(raw.get("users"), list) else []
    sessions = raw.get("sessions") if isinstance(raw.get("sessions"), dict) else {}
    return {"users": users, "sessions": sessions}


_auth_store_write_lock = threading.RLock()


def save_auth_store(store: dict[str, Any]) -> None:
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        with _auth_store_write_lock:
            repository.replace_tables({"users": auth_user_rows(store), "auth_sessions": auth_session_rows(store)})
        return
    payload = json.dumps(store, indent=2, ensure_ascii=False)
    # Serialize writes and use a unique temp file so concurrent request threads
    # cannot clobber a shared temp path mid-write (which corrupted the store and
    # surfaced as random FileNotFound/decode failures under load).
    with _auth_store_write_lock:
        tmp_path = AUTH_PATH.with_suffix(f".json.tmp.{uuid.uuid4().hex}")
        try:
            tmp_path.write_text(payload, encoding="utf-8")
            tmp_path.replace(AUTH_PATH)
        finally:
            tmp_path.unlink(missing_ok=True)


def auth_user_row_for_user(user: dict[str, Any]) -> dict[str, Any] | None:
    rows = auth_user_rows({"users": [user]})
    return rows[0] if rows else None


def save_auth_user(user: dict[str, Any]) -> bool:
    row = auth_user_row_for_user(user)
    if not row:
        return False
    repository = runtime_postgres_repository_or_none()
    if repository is None:
        return False
    with _auth_store_write_lock:
        repository.upsert_row("users", row)
    return True


TASK_NAVIGATION_PREFERENCES_KEY = "task_navigation_preferences"
MAX_TASK_NAVIGATION_IDS = 200
MAX_TASK_NAVIGATION_ID_LENGTH = 200


def normalize_task_navigation_ids(raw_ids: Any) -> list[str]:
    if not isinstance(raw_ids, list):
        return []
    clean_ids: list[str] = []
    seen: set[str] = set()
    for raw_id in raw_ids:
        task_id = str(raw_id or "").strip()
        if not task_id or len(task_id) > MAX_TASK_NAVIGATION_ID_LENGTH or task_id in seen:
            continue
        seen.add(task_id)
        clean_ids.append(task_id)
        if len(clean_ids) >= MAX_TASK_NAVIGATION_IDS:
            break
    return clean_ids


def task_navigation_preferences_payload(user: dict[str, Any]) -> dict[str, Any]:
    raw_preferences = user.get(TASK_NAVIGATION_PREFERENCES_KEY)
    preferences = raw_preferences if isinstance(raw_preferences, dict) else {}
    return {
        "pinned_task_ids": normalize_task_navigation_ids(preferences.get("pinned_task_ids")),
        "archived_task_ids": normalize_task_navigation_ids(preferences.get("archived_task_ids")),
        "updated_at": int(preferences.get("updated_at") or 0),
        "exists": isinstance(raw_preferences, dict),
    }


def delete_auth_user(user_id: str) -> bool:
    clean_user_id = str(user_id or "").strip()
    if not clean_user_id:
        return False
    repository = runtime_postgres_repository_or_none()
    if repository is None:
        return False
    with _auth_store_write_lock:
        if repository.fetch_by_primary_key("users", {"id": clean_user_id}) is None:
            return False
        repository.delete_by_primary_key("users", {"id": clean_user_id})
    return True


def auth_session_key_candidates(session_id: str) -> tuple[str, ...]:
    clean_id = str(session_id or "").strip()
    if not clean_id:
        return ()
    return tuple(dict.fromkeys([clean_id, session_key_hash(clean_id)]))


def auth_session_from_store(store: dict[str, Any], session_id: str) -> dict[str, Any] | None:
    sessions = store.get("sessions") if isinstance(store.get("sessions"), dict) else {}
    for candidate in auth_session_key_candidates(session_id):
        session = sessions.get(candidate)
        if isinstance(session, dict):
            return session
    return None


def auth_session_row_for_session(session_id: str, session: dict[str, Any]) -> dict[str, Any] | None:
    rows = auth_session_rows({"sessions": {session_id: session}})
    return rows[0] if rows else None


def save_auth_session(session_id: str, session: dict[str, Any]) -> None:
    row = auth_session_row_for_session(session_id, session)
    if not row:
        return
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        with _auth_store_write_lock:
            repository.upsert_row("auth_sessions", row)
        return
    store = load_auth_store()
    store.setdefault("sessions", {})[session_id] = dict(session)
    save_auth_store(store)


def delete_auth_session(session_id: str) -> bool:
    candidates = auth_session_key_candidates(session_id)
    if not candidates:
        return False
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        deleted = False
        with _auth_store_write_lock:
            for candidate in candidates:
                if repository.fetch_by_primary_key("auth_sessions", {"id_hash": candidate}) is not None:
                    repository.delete_by_primary_key("auth_sessions", {"id_hash": candidate})
                    deleted = True
        return deleted
    store = load_auth_store()
    sessions = store.get("sessions") if isinstance(store.get("sessions"), dict) else {}
    deleted = False
    for candidate in candidates:
        deleted = sessions.pop(candidate, None) is not None or deleted
    if deleted:
        save_auth_store(store)
    return deleted


def delete_expired_auth_sessions(now: int | None = None) -> int:
    repository = runtime_postgres_repository_or_none()
    if repository is None:
        return 0
    cutoff = int(now or time.time())
    deleted = 0
    with _auth_store_write_lock:
        for row in repository.fetch_all("auth_sessions"):
            try:
                expires_at = int(row.get("expires_at") or 0)
            except (TypeError, ValueError):
                expires_at = 0
            id_hash = str(row.get("id_hash") or "")
            if id_hash and expires_at <= cutoff:
                repository.delete_by_primary_key("auth_sessions", {"id_hash": id_hash})
                deleted += 1
    return deleted


def delete_auth_sessions_for_user(user_id: str, *, keep_session_id: str = "") -> int:
    repository = runtime_postgres_repository_or_none()
    if repository is None:
        return 0
    clean_user_id = str(user_id or "").strip()
    if not clean_user_id:
        return 0
    keep_hashes = set(auth_session_key_candidates(keep_session_id))
    deleted = 0
    with _auth_store_write_lock:
        for row in repository.fetch_all("auth_sessions"):
            raw_sessions = row_raw_json_list([row])
            session = raw_sessions[0] if raw_sessions else {}
            id_hash = str(row.get("id_hash") or session.get("id_hash") or "")
            if (
                id_hash
                and id_hash not in keep_hashes
                and str(session.get("user_id") or row.get("user_id") or "") == clean_user_id
            ):
                repository.delete_by_primary_key("auth_sessions", {"id_hash": id_hash})
                deleted += 1
    return deleted


def save_login_session(store: dict[str, Any], session_id: str, user: dict[str, Any], revoked_sessions: int = 0) -> int:
    repository = runtime_postgres_repository_or_none()
    if repository is None:
        save_auth_store(store)
        return revoked_sessions
    session = auth_session_from_store(store, session_id)
    if not session:
        return revoked_sessions
    with _auth_store_write_lock:
        actual_revoked = delete_auth_sessions_for_user(str(user.get("id") or ""), keep_session_id=session_id)
        save_auth_session(session_id, session)
    return actual_revoked


def save_auth_session_touch_or_prune(store: dict[str, Any], session_id: str, session: dict[str, Any] | None, *, prune_expired: bool) -> None:
    repository = runtime_postgres_repository_or_none()
    if repository is None:
        save_auth_store(store)
        return
    if prune_expired:
        delete_expired_auth_sessions()
    if session:
        save_auth_session(session_id, session)


def public_user(user: dict[str, Any]) -> dict[str, Any]:
    role = normalize_role(user.get("role"))
    permissions = sorted(FEATURE_PERMISSIONS) if role == "admin" else normalize_permissions(user.get("permissions"))
    return {
        "id": str(user.get("id") or ""),
        "username": str(user.get("username") or ""),
        "display_name": str(user.get("display_name") or user.get("username") or ""),
        "role": role,
        "permissions": permissions,
        "active": bool(user.get("active", True)),
        "created_at": int(user.get("created_at") or 0),
        "updated_at": int(user.get("updated_at") or 0),
    }


def users_exist(store: dict[str, Any] | None = None) -> bool:
    store = store or load_auth_store()
    return any(isinstance(user, dict) for user in store.get("users", []))


def create_auth_user(
    store: dict[str, Any],
    *,
    username: str,
    password: str,
    display_name: str | None = None,
    role: str = "user",
    permissions: list[str] | None = None,
    active: bool = True,
) -> dict[str, Any]:
    clean = clean_username(username)
    if not clean:
        raise HTTPException(status_code=400, detail="Username is required")
    if any(clean_username(user.get("username")) == clean for user in store.get("users", []) if isinstance(user, dict)):
        raise HTTPException(status_code=409, detail="Username already exists")
    now = int(time.time())
    normalized_role = normalize_role(role)
    user = {
        "id": f"user_{uuid.uuid4().hex[:12]}",
        "username": clean,
        "display_name": clean_display_name(display_name, clean),
        "role": normalized_role,
        "permissions": sorted(FEATURE_PERMISSIONS) if normalized_role == "admin" else normalize_permissions(permissions or []),
        "password_hash": password_hash(password),
        "active": bool(active),
        "created_at": now,
        "updated_at": now,
    }
    store.setdefault("users", []).append(user)
    return user


def bootstrap_admin_from_env(store: dict[str, Any]) -> bool:
    if users_exist(store):
        return False
    username = os.environ.get("VANTALINE_BOOTSTRAP_ADMIN_USERNAME", "").strip()
    password = os.environ.get("VANTALINE_BOOTSTRAP_ADMIN_PASSWORD", "")
    if not username or not password:
        return False
    create_auth_user(store, username=username, password=password, display_name=username, role="admin", permissions=sorted(FEATURE_PERMISSIONS))
    save_auth_store(store)
    return True


def find_user(store: dict[str, Any], user_id: str) -> dict[str, Any] | None:
    for user in store.get("users", []):
        if isinstance(user, dict) and str(user.get("id") or "") == str(user_id or ""):
            return user
    return None


def find_user_by_username(store: dict[str, Any], username: str) -> dict[str, Any] | None:
    clean = clean_username(username)
    for user in store.get("users", []):
        if isinstance(user, dict) and clean_username(user.get("username")) == clean:
            return user
    return None


def user_is_admin(user: dict[str, Any] | None) -> bool:
    return normalize_role((user or {}).get("role")) == "admin"


def user_has_permission(user: dict[str, Any] | None, permission: str | None) -> bool:
    if not permission:
        return True
    if user_is_admin(user):
        return True
    return permission in normalize_permissions((user or {}).get("permissions"))


def prune_expired_sessions(store: dict[str, Any]) -> bool:
    now = int(time.time())
    sessions = store.get("sessions") if isinstance(store.get("sessions"), dict) else {}
    active = {
        session_id: session
        for session_id, session in sessions.items()
        if isinstance(session, dict) and int(session.get("expires_at") or 0) > now
    }
    changed = len(active) != len(sessions)
    store["sessions"] = active
    return changed


def request_is_https(request: Request) -> bool:
    forwarded_proto = request.headers.get("x-forwarded-proto", "").split(",", 1)[0].strip().lower()
    return request.url.scheme == "https" or forwarded_proto == "https"


def set_session_cookie(response: Response, request: Request, session_id: str) -> None:
    response.set_cookie(
        AUTH_SESSION_COOKIE,
        session_id,
        max_age=AUTH_SESSION_TTL_SECONDS,
        httponly=True,
        secure=request_is_https(request),
        samesite="lax",
        path="/",
    )


def clear_session_cookie(response: Response, request: Request) -> None:
    response.delete_cookie(AUTH_SESSION_COOKIE, path="/", secure=request_is_https(request), samesite="lax")


def create_session(store: dict[str, Any], user: dict[str, Any]) -> str:
    session_id = secrets.token_urlsafe(32)
    now = int(time.time())
    store.setdefault("sessions", {})[session_id] = {
        "user_id": user["id"],
        "created_at": now,
        "last_seen_at": now,
        "expires_at": now + AUTH_SESSION_TTL_SECONDS,
    }
    return session_id


def create_login_session(store: dict[str, Any], user: dict[str, Any]) -> tuple[str, int]:
    session_id = create_session(store, user)
    revoked_sessions = revoke_user_sessions(store, str(user.get("id") or ""), keep_session_id=session_id)
    return session_id, revoked_sessions


TEMP_PASSWORD_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%^*-_"


def generate_temporary_password(length: int = 18) -> str:
    length = max(12, min(48, int(length or 18)))
    return "".join(secrets.choice(TEMP_PASSWORD_ALPHABET) for _ in range(length))


def revoke_user_sessions(store: dict[str, Any], user_id: str, *, keep_session_id: str = "") -> int:
    sessions = store.get("sessions") if isinstance(store.get("sessions"), dict) else {}
    keep_session_ids = {keep_session_id, session_key_hash(keep_session_id)} if keep_session_id else set()
    revoked = 0
    kept: dict[str, Any] = {}
    for session_id, session in sessions.items():
        if (
            isinstance(session, dict)
            and str(session.get("user_id") or "") == str(user_id or "")
            and session_id not in keep_session_ids
        ):
            revoked += 1
            continue
        kept[session_id] = session
    store["sessions"] = kept
    return revoked


def set_user_password(user: dict[str, Any], password: str) -> None:
    user["password_hash"] = password_hash(password)
    user["updated_at"] = int(time.time())


def authenticate_request(request: Request) -> tuple[dict[str, Any] | None, dict[str, Any], bool]:
    store = load_auth_store()
    changed = prune_expired_sessions(store)
    expired_sessions_pruned = changed
    if bootstrap_admin_from_env(store):
        store = load_auth_store()
    session_id = request.cookies.get(AUTH_SESSION_COOKIE, "")
    sessions = store.get("sessions", {}) if isinstance(store.get("sessions"), dict) else {}
    session = sessions.get(session_id) if session_id else None
    if session is None and session_id:
        session = sessions.get(session_key_hash(session_id))
    user = find_user(store, str((session or {}).get("user_id") or "")) if isinstance(session, dict) else None
    if not user or not bool(user.get("active", True)):
        if expired_sessions_pruned:
            save_auth_session_touch_or_prune(store, "", None, prune_expired=True)
        return None, store, changed
    now = int(time.time())
    prev_seen = int(session.get("last_seen_at") or 0)
    session["last_seen_at"] = now
    session["expires_at"] = now + AUTH_SESSION_TTL_SECONDS
    # Throttle disk writes: only persist the slid expiry when something else
    # changed (pruned sessions) or enough time has elapsed since the last write.
    if expired_sessions_pruned or (now - prev_seen) >= AUTH_SESSION_PERSIST_INTERVAL_SECONDS:
        changed = True
        save_auth_session_touch_or_prune(store, session_id, session, prune_expired=expired_sessions_pruned)
    return public_user(user), store, changed


def current_auth_user() -> dict[str, Any]:
    user = _request_user.get()
    if not user:
        raise HTTPException(status_code=401, detail="Authentication required")
    return user


def require_admin_role(detail: str = "Admin role required") -> dict[str, Any]:
    user = current_auth_user()
    if not user_is_admin(user):
        raise HTTPException(status_code=403, detail=detail)
    return user


RUNTIME_REPOSITORY_CONNECTOR_FOR_TESTS: Callable[[str], Any] | None = None
_runtime_repository_lock = threading.RLock()
_runtime_repository_generation = 0
_runtime_repository_thread_local = threading.local()


def runtime_repository_cache_key() -> tuple[str, str, int | None]:
    return (
        os.environ.get("VANTALINE_DATA_STORE", "").strip().lower() or "json",
        os.environ.get("DATABASE_URL", "").strip(),
        id(RUNTIME_REPOSITORY_CONNECTOR_FOR_TESTS) if RUNTIME_REPOSITORY_CONNECTOR_FOR_TESTS is not None else None,
    )


def reset_runtime_repository_cache() -> None:
    global _runtime_repository_generation
    with _runtime_repository_lock:
        _runtime_repository_generation += 1
    clear_thread_runtime_repository_selection()


def close_runtime_repository_selection(selection: Any) -> None:
    repository = getattr(selection, "repository", None)
    connection = getattr(repository, "connection", None)
    close = getattr(connection, "close", None)
    if callable(close):
        try:
            close()
        except Exception:
            pass


def runtime_repository_selection_is_usable(selection: Any) -> bool:
    repository = getattr(selection, "repository", None)
    connection = getattr(repository, "connection", None)
    closed = getattr(connection, "closed", None)
    if closed is None:
        return True
    try:
        return not bool(closed)
    except Exception:
        return True


def clear_thread_runtime_repository_selection() -> None:
    selection = getattr(_runtime_repository_thread_local, "selection", None)
    if selection is not None:
        close_runtime_repository_selection(selection)
    for attr in ("key", "selection", "generation"):
        try:
            delattr(_runtime_repository_thread_local, attr)
        except AttributeError:
            pass


def current_runtime_repository_generation() -> int:
    with _runtime_repository_lock:
        return _runtime_repository_generation


def runtime_repository_selection() -> Any:
    """Build the explicit runtime repository selection with HTTP-safe errors."""

    cache_key = runtime_repository_cache_key()
    generation = current_runtime_repository_generation()
    cached_selection = getattr(_runtime_repository_thread_local, "selection", None)
    if (
        cached_selection is not None
        and getattr(_runtime_repository_thread_local, "key", None) == cache_key
        and getattr(_runtime_repository_thread_local, "generation", None) == generation
        and runtime_repository_selection_is_usable(cached_selection)
    ):
        return cached_selection

    if cached_selection is not None:
        clear_thread_runtime_repository_selection()

    try:
        selection = build_runtime_repository(postgres_connector=RUNTIME_REPOSITORY_CONNECTOR_FOR_TESTS)
    except RuntimeStoreConfigError as exc:
        raise HTTPException(
            status_code=503,
            detail={
                "code": "runtime_store_config_error",
                "message": str(exc),
                "json_fallback_used": False,
            },
        ) from None
    except RuntimeStoreConnectionError as exc:
        raise HTTPException(
            status_code=503,
            detail={
                "code": "runtime_store_connection_error",
                "message": str(exc),
                "json_fallback_used": False,
            },
        ) from None

    # Avoid sharing a DB-API connection across worker threads while still
    # reusing it within one thread/request path.
    current_generation = current_runtime_repository_generation()
    if current_generation != generation or runtime_repository_cache_key() != cache_key:
        close_runtime_repository_selection(selection)
        return runtime_repository_selection()
    _runtime_repository_thread_local.key = cache_key
    _runtime_repository_thread_local.selection = selection
    _runtime_repository_thread_local.generation = generation
    return selection


def runtime_postgres_repository_or_none() -> Any | None:
    """Return the explicit PostgreSQL repository, or None for JSON runtime."""

    selection = runtime_repository_selection()
    if selection.store == POSTGRES_STORE:
        return selection.repository
    return None


def runtime_repository_connection_probe_id(repository: Any) -> str:
    """Return a non-secret process-local fingerprint for the repository connection."""

    connection = getattr(repository, "connection", None)
    if connection is None:
        return ""
    material = f"{os.getpid()}:{threading.get_ident()}:{id(connection)}"
    return hashlib.sha256(material.encode("utf-8")).hexdigest()[:16]


def runtime_store_probe_payload() -> dict[str, Any]:
    """Return a non-secret runtime-store probe for an admin HTTP endpoint."""

    selection = runtime_repository_selection()
    payload: dict[str, Any] = {
        "store": selection.store,
        "repository_kind": selection.repository.kind,
        "json_fallback_used": False,
        "repository_connection_id": None,
        "repository_connection_scope": None,
    }
    if selection.store == POSTGRES_STORE:
        try:
            counts = selection.repository.count_rows(("schema_migrations",))
        except Exception as exc:
            raise HTTPException(
                status_code=503,
                detail={
                    "code": "runtime_store_probe_error",
                    "message": type(exc).__name__,
                    "json_fallback_used": False,
                },
            ) from None
        payload["postgres_count_probe"] = {"schema_migrations": counts.get("schema_migrations", 0)}
        payload["repository_connection_id"] = runtime_repository_connection_probe_id(selection.repository)
        payload["repository_connection_scope"] = "thread-local"
    else:
        payload["postgres_count_probe"] = None
    return payload


