API_COST_CATEGORY_LABELS = {
    "image_generation": "生图 API",
    "structured_output": "任务结构性输出 API",
    "agent": "Agent API",
    "training": "RunPod 训练 API",
}

# RunPod serverless bills per GPU-second from worker start to stop. The YOLO
# training endpoint currently runs RTX A5000 flex workers ($0.00026/s per
# RunPod published pricing); override via env if the endpoint GPU tier changes.
RUNPOD_GPU_USD_PER_SECOND_DEFAULT = 0.00026
RUNPOD_GPU_USD_PER_SECOND_ENV = "VANTALINE_RUNPOD_GPU_USD_PER_SECOND"


def runpod_gpu_usd_per_second() -> float:
    raw = str(os.environ.get(RUNPOD_GPU_USD_PER_SECOND_ENV, "") or "").strip()
    try:
        value = float(raw)
    except ValueError:
        return RUNPOD_GPU_USD_PER_SECOND_DEFAULT
    return value if value > 0 else RUNPOD_GPU_USD_PER_SECOND_DEFAULT


def api_cost_pricing_for_model(model: str) -> dict[str, float] | None:
    clean_model = str(model or "").strip()
    if not clean_model:
        return None
    if clean_model in API_COST_PRICING_USD_PER_MILLION:
        return API_COST_PRICING_USD_PER_MILLION[clean_model]
    for key, pricing in API_COST_PRICING_USD_PER_MILLION.items():
        if key in clean_model:
            return pricing
    return None


def api_cost_usage_token_count(usage: dict[str, Any], key: str) -> int:
    aliases = {
        "promptTokenCount": ("promptTokenCount", "prompt_tokens", "input_tokens"),
        "cachedContentTokenCount": ("cachedContentTokenCount", "cached_tokens", "cached_prompt_tokens"),
        "candidatesTokenCount": ("candidatesTokenCount", "completion_tokens", "output_tokens"),
        "thoughtsTokenCount": ("thoughtsTokenCount", "reasoning_tokens"),
        "totalTokenCount": ("totalTokenCount", "total_tokens"),
        "tokenCount": ("tokenCount", "token_count"),
    }
    for candidate in aliases.get(key, (key,)):
        value = usage.get(candidate)
        if value is None:
            continue
        try:
            return max(0, int(float(value or 0)))
        except (TypeError, ValueError):
            continue
    return 0


def api_cost_detail_tokens(usage: dict[str, Any], key: str, modality: str) -> int:
    details = usage.get(key)
    if not isinstance(details, list):
        return 0
    total = 0
    for item in details:
        if not isinstance(item, dict):
            continue
        if str(item.get("modality") or "").upper() != modality.upper():
            continue
        total += api_cost_usage_token_count(item, "tokenCount")
    return total


def api_cost_from_usage(model: str, usage: dict[str, Any]) -> tuple[float, dict[str, int], bool]:
    pricing = api_cost_pricing_for_model(model)
    prompt_tokens = api_cost_usage_token_count(usage, "promptTokenCount")
    cached_tokens = api_cost_usage_token_count(usage, "cachedContentTokenCount")
    output_tokens = (
        api_cost_usage_token_count(usage, "candidatesTokenCount")
        + api_cost_usage_token_count(usage, "thoughtsTokenCount")
    )
    image_output_tokens = api_cost_detail_tokens(usage, "candidatesTokensDetails", "IMAGE")
    if image_output_tokens <= 0:
        image_output_tokens = api_cost_detail_tokens(usage, "outputTokensDetails", "IMAGE")
    if output_tokens <= 0 and image_output_tokens > 0:
        output_tokens = image_output_tokens
    text_output_tokens = max(0, output_tokens - image_output_tokens)
    if prompt_tokens <= 0:
        total_tokens = api_cost_usage_token_count(usage, "totalTokenCount")
        prompt_tokens = max(0, total_tokens - output_tokens)
    non_cached_tokens = max(0, prompt_tokens - cached_tokens)
    tokens = {
        "input": int(non_cached_tokens),
        "cached_input": int(cached_tokens),
        "output_text": int(text_output_tokens),
        "output_image": int(image_output_tokens),
        "total": api_cost_usage_token_count(usage, "totalTokenCount") or int(prompt_tokens + output_tokens),
    }
    if not pricing:
        return 0.0, tokens, False
    cost = (
        tokens["input"] * float(pricing.get("input") or 0.0)
        + tokens["cached_input"] * float(pricing.get("cached_input") or pricing.get("input") or 0.0)
        + tokens["output_text"] * float(pricing.get("output_text") or 0.0)
        + tokens["output_image"] * float(pricing.get("output_image") or 0.0)
    ) / 1_000_000
    return cost, tokens, True


def api_cost_day(timestamp: Any) -> str:
    try:
        ts = int(float(timestamp or 0))
    except (TypeError, ValueError):
        ts = 0
    if ts <= 0:
        ts = int(time.time())
    return time.strftime("%Y-%m-%d", time.localtime(ts))


def api_cost_classify(path: Path, payload: dict[str, Any]) -> tuple[str, str]:
    path_text = str(path).replace("\\", "/").lower()
    provider = str(payload.get("provider") or payload.get("provider_label") or "").lower()
    model = str(payload.get("model") or payload.get("provider_model") or "").lower()
    if "agent_mcp_pose_images" in path_text or "auto_optimize" in path_text or "image_generation" in provider or "image" in model:
        return "image_generation", "生图 / AI mask"
    if "agent" in path_text or provider == "cursor" or "agent" in provider:
        return "agent", "Agent 调用"
    if "ai_profile_cache" in path_text:
        return "structured_output", "AI Profile cache"
    if "data_analysis_records" in path_text:
        return "structured_output", "检测结构化输出"
    return "structured_output", "结构化输出"


def api_cost_walk_usage(payload: Any, path: Path, pointer: str = "") -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    if isinstance(payload, dict):
        usage = payload.get("usage_metadata")
        if isinstance(usage, dict) and usage:
            model = str(
                payload.get("model")
                or payload.get("provider_model")
                or payload.get("image_model")
                or payload.get("fallback_model")
                or ""
            )
            if not model:
                parent = payload.get("ai") if isinstance(payload.get("ai"), dict) else {}
                model = str(parent.get("provider_model") or "")
            category, subcategory = api_cost_classify(path, payload)
            created_at = payload.get("created_at") or payload.get("completed_at") or payload.get("updated_at") or payload.get("timestamp")
            cost, tokens, priced = api_cost_from_usage(model, usage)
            records.append(
                {
                    "id": hashlib.sha1(f"{path}:{pointer}".encode("utf-8")).hexdigest()[:16],
                    "path": str(path),
                    "pointer": pointer,
                    "category": category,
                    "subcategory": subcategory,
                    "model": model or "unknown",
                    "created_at": coerce_record_timestamp(created_at) or 0,
                    "day": api_cost_day(created_at),
                    "usage_metadata": usage,
                    "tokens": tokens,
                    "cost_usd": cost,
                    "priced": priced,
                    "estimated": False,
                }
            )
        for key, value in payload.items():
            if key in {"bytes", "image_bytes", "api_key", "image_api_key"}:
                continue
            next_pointer = f"{pointer}/{key}" if pointer else str(key)
            records.extend(api_cost_walk_usage(value, path, next_pointer))
    elif isinstance(payload, list):
        for index, value in enumerate(payload):
            records.extend(api_cost_walk_usage(value, path, f"{pointer}/{index}" if pointer else str(index)))
    return records


def api_cost_store_payloads() -> list[tuple[Path, Any]]:
    """Usage-bearing payloads read through the runtime store loaders (Postgres
    when active, legacy JSON otherwise). The paired paths are the legacy JSON
    locations so category classification and record ids stay stable across the
    Postgres cutover."""
    pipeline_path = PIPELINE_TASKS_PATH if "PIPELINE_TASKS_PATH" in globals() else DATA_DIR / "pipeline_tasks.json"
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        # Raw rows, not the normalized loader output: normalization whitelists
        # fields and could drop usage metadata recorded outside the known spots.
        analysis_records: Any = row_raw_json_list(repository.fetch_all("data_analysis_records"))
    else:
        try:
            raw = json.loads(DATA_ANALYSIS_RECORDS_PATH.read_text(encoding="utf-8")) if DATA_ANALYSIS_RECORDS_PATH.exists() else {}
        except (OSError, json.JSONDecodeError):
            raw = {}
        analysis_records = raw.get("records") if isinstance(raw, dict) else raw
        if not isinstance(analysis_records, list):
            analysis_records = []
    payloads: list[tuple[Path, Any]] = [
        (DATA_ANALYSIS_RECORDS_PATH, {"records": analysis_records}),
        (AI_DETECTION_TASKS_PATH, {"tasks": load_ai_detection_tasks()}),
        (pipeline_path, load_pipeline_tasks()),
    ]
    for state in list_auto_optimize_states():
        task_id = sanitize_ai_detection_task_id(state.get("task_id") or "") or "state"
        payloads.append((AUTO_OPTIMIZE_DIR / f"{task_id}.json", state))
    return payloads


def api_cost_training_records() -> list[dict[str, Any]]:
    """RunPod training runs billed per GPU-second of worker execution time.

    RunPod's status responses expose `executionTime` in milliseconds; runs
    without it (failed before start, legacy Windows-worker records) are listed
    as unpriced calls instead of being silently dropped."""
    records: list[dict[str, Any]] = []
    rate = runpod_gpu_usd_per_second()
    for task in load_training_task_records():
        if str(task.get("training_executor") or "").strip().lower() != "runpod":
            continue
        response = task.get("remote_training_response") if isinstance(task.get("remote_training_response"), dict) else {}
        job_id = str(task.get("job_id") or task.get("task_id") or "").strip() or "unknown"
        created_at = coerce_record_timestamp(
            task.get("completed_at") or task.get("updated_at") or task.get("created_at")
        )
        try:
            execution_seconds = max(0.0, float(response.get("executionTime") or 0) / 1000.0)
        except (TypeError, ValueError):
            execution_seconds = 0.0
        priced = execution_seconds > 0
        records.append(
            {
                "id": hashlib.sha1(f"runpod_training:{job_id}".encode("utf-8")).hexdigest()[:16],
                "path": f"training_tasks/{job_id}",
                "pointer": "remote_training_response/executionTime",
                "category": "training",
                "subcategory": "RunPod YOLO 训练",
                "model": "runpod-a5000-flex",
                "created_at": created_at,
                "day": api_cost_day(created_at),
                "usage_metadata": {
                    "execution_seconds": round(execution_seconds, 3),
                    "delay_ms": response.get("delayTime") or 0,
                    "status": str(task.get("status") or ""),
                },
                "tokens": {},
                "cost_usd": round(execution_seconds * rate, 6),
                "priced": priced,
                "estimated": False,
            }
        )
    return records


def api_cost_collect_records() -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    # Store-backed sources first: since the Postgres cutover these tables are
    # the live data; their legacy JSON files are stale snapshots and are no
    # longer read directly (that also avoids double counting).
    for path, payload in api_cost_store_payloads():
        for record in api_cost_walk_usage(payload, path):
            if record["id"] in seen_ids:
                continue
            seen_ids.add(record["id"])
            records.append(record)
    # File-based sources that never moved into the store.
    json_paths: list[Path] = []
    if AI_PROFILE_CACHE_PATH.exists():
        json_paths.append(AI_PROFILE_CACHE_PATH)
    for pattern in (
        "outputs/users/*/agent_mcp_pose_images/**/*.metadata.json",
        "outputs/users/*/auto_optimize_masks/**/*.metadata.json",
        "outputs/agent_mcp_pose_images/**/*.metadata.json",
        "outputs/auto_optimize_masks/**/*.metadata.json",
        "image_worker_logs/**/*.json",
    ):
        json_paths.extend(DATA_DIR.glob(pattern))
    seen_paths: set[Path] = set()
    for path in json_paths:
        try:
            resolved = path.resolve()
        except OSError:
            resolved = path
        if resolved in seen_paths or not path.exists() or not path.is_file():
            continue
        seen_paths.add(resolved)
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        for record in api_cost_walk_usage(payload, path):
            if record["id"] in seen_ids:
                continue
            seen_ids.add(record["id"])
            records.append(record)
    for record in api_cost_training_records():
        if record["id"] in seen_ids:
            continue
        seen_ids.add(record["id"])
        records.append(record)
    records.sort(key=lambda item: int(item.get("created_at") or 0), reverse=True)
    return records


def api_cost_summary(records: list[dict[str, Any]]) -> dict[str, Any]:
    records = [record for record in records if not record.get("estimated")]
    categories: dict[str, dict[str, Any]] = {}
    daily: dict[str, dict[str, Any]] = {}
    for key, label in API_COST_CATEGORY_LABELS.items():
        categories[key] = {
            "key": key,
            "label": label,
            "call_count": 0,
            "priced_call_count": 0,
            "estimated_call_count": 0,
            "unpriced_call_count": 0,
            "cost_usd": 0.0,
            "subcategories": {},
        }
    for record in records:
        category_key = str(record.get("category") or "structured_output")
        category = categories.setdefault(
            category_key,
            {
                "key": category_key,
                "label": API_COST_CATEGORY_LABELS.get(category_key, category_key),
                "call_count": 0,
                "priced_call_count": 0,
                "estimated_call_count": 0,
                "unpriced_call_count": 0,
                "cost_usd": 0.0,
                "subcategories": {},
            },
        )
        cost = float(record.get("cost_usd") or 0.0)
        category["call_count"] += 1
        category["cost_usd"] += cost
        if record.get("estimated"):
            category["estimated_call_count"] += 1
        if record.get("priced"):
            category["priced_call_count"] += 1
        else:
            category["unpriced_call_count"] += 1
        sub_key = str(record.get("subcategory") or "其他")
        sub = category["subcategories"].setdefault(sub_key, {"label": sub_key, "call_count": 0, "cost_usd": 0.0})
        sub["call_count"] += 1
        sub["cost_usd"] += cost
        day = str(record.get("day") or api_cost_day(record.get("created_at")))
        day_row = daily.setdefault(day, {"date": day, "total_cost_usd": 0.0, "call_count": 0})
        day_row["total_cost_usd"] += cost
        day_row["call_count"] += 1
        day_row[category_key] = float(day_row.get(category_key) or 0.0) + cost
    category_rows = []
    for category in categories.values():
        call_count = max(1, int(category["call_count"]))
        sub_rows = list(category["subcategories"].values())
        sub_rows.sort(key=lambda item: float(item.get("cost_usd") or 0.0), reverse=True)
        category_rows.append(
            {
                **{key: value for key, value in category.items() if key != "subcategories"},
                "cost_usd": round(float(category["cost_usd"]), 6),
                "avg_cost_usd": round(float(category["cost_usd"]) / call_count, 6) if category["call_count"] else 0.0,
                "subcategories": [
                    {**sub, "cost_usd": round(float(sub.get("cost_usd") or 0.0), 6)}
                    for sub in sub_rows
                ],
            }
        )
    category_rows.sort(key=lambda item: float(item.get("cost_usd") or 0.0), reverse=True)
    total_cost = sum(float(record.get("cost_usd") or 0.0) for record in records)
    known_records = [record for record in records if not record.get("estimated")]
    estimated_records = [record for record in records if record.get("estimated")]
    image_records = [record for record in records if record.get("category") == "image_generation"]
    training_sample_count = 0
    for payload in list_auto_optimize_states():
        samples = payload.get("samples") if isinstance(payload.get("samples"), list) else []
        training_sample_count += len([sample for sample in samples if isinstance(sample, dict) and sample.get("label_status") in {"trainable", "negative"}])
    return {
        "currency": "USD",
        "updated_at": int(time.time()),
        "pricing_source": "Configured from Gemini API public pricing, Alibaba Cloud Model Studio Qwen international first-tier token pricing, and RunPod serverless per-GPU-second pricing (A5000 flex); calls without provider-returned usage metadata are not estimated.",
        "summary": {
            "total_cost_usd": round(total_cost, 6),
            "known_cost_usd": round(sum(float(record.get("cost_usd") or 0.0) for record in known_records), 6),
            "estimated_cost_usd": round(sum(float(record.get("cost_usd") or 0.0) for record in estimated_records), 6),
            "call_count": len(records),
            "priced_call_count": len([record for record in records if record.get("priced")]),
            "estimated_call_count": len(estimated_records),
            "unpriced_call_count": len([record for record in records if not record.get("priced")]),
            "avg_cost_per_call_usd": round(total_cost / len(records), 6) if records else 0.0,
            "avg_image_generation_cost_usd": round(
                sum(float(record.get("cost_usd") or 0.0) for record in image_records) / len(image_records),
                6,
            )
            if image_records
            else 0.0,
            "training_sample_count": training_sample_count,
            "avg_cost_per_training_sample_usd": round(total_cost / training_sample_count, 6) if training_sample_count else 0.0,
        },
        "categories": category_rows,
        "daily": [
            {
                **row,
                "total_cost_usd": round(float(row.get("total_cost_usd") or 0.0), 6),
                "image_generation": round(float(row.get("image_generation") or 0.0), 6),
                "structured_output": round(float(row.get("structured_output") or 0.0), 6),
                "agent": round(float(row.get("agent") or 0.0), 6),
                "training": round(float(row.get("training") or 0.0), 6),
            }
            for row in sorted(daily.values(), key=lambda item: item["date"])[-30:]
        ],
        "recent_calls": [
            {
                "id": record.get("id"),
                "day": record.get("day"),
                "category": record.get("category"),
                "subcategory": record.get("subcategory"),
                "model": record.get("model"),
                "cost_usd": round(float(record.get("cost_usd") or 0.0), 6),
                "priced": bool(record.get("priced")),
                "estimated": bool(record.get("estimated")),
            }
            for record in records[:80]
        ],
    }


def record_owner_id(record: dict[str, Any] | None) -> str:
    if not isinstance(record, dict):
        return LEGACY_OWNER_ID
    owner = str(record.get("owner_user_id") or record.get("created_by_user_id") or "").strip()
    return owner or LEGACY_OWNER_ID


def current_owner_fields() -> dict[str, Any]:
    user = _request_user.get()
    if not user:
        return {}
    return {"owner_user_id": user["id"], "owner_username": user.get("username") or ""}


def owner_fields_for_new_record(user: dict[str, Any], target_user_id: str | None = None) -> dict[str, Any]:
    target = str(target_user_id or "").strip()
    if user_is_admin(user) and target:
        if target == LEGACY_OWNER_ID:
            return {"owner_user_id": LEGACY_OWNER_ID, "owner_username": LEGACY_OWNER_ID}
        if target == SYSTEM_OWNER_ID:
            return {"owner_user_id": SYSTEM_OWNER_ID, "owner_username": "system"}
        target_user = find_user(load_auth_store(), target)
        if not target_user:
            raise HTTPException(status_code=404, detail="目标用户不存在")
        return {"owner_user_id": target_user["id"], "owner_username": target_user.get("username") or ""}
    return {"owner_user_id": user["id"], "owner_username": user.get("username") or ""}


def coerce_record_timestamp(value: Any) -> int:
    try:
        return int(float(value or 0))
    except (TypeError, ValueError):
        return 0


def path_mtime_timestamp(path: Path | None) -> int:
    if not path:
        return 0
    try:
        return int(path.stat().st_mtime)
    except OSError:
        return 0


def record_created_at(record: dict[str, Any] | None, fallback_path: Path | None = None) -> int:
    if isinstance(record, dict):
        for key in ("created_at", "created", "started_at", "queued_at", "requested_at", "completed_at", "updated_at"):
            timestamp = coerce_record_timestamp(record.get(key))
            if timestamp:
                return timestamp
    return path_mtime_timestamp(fallback_path)


def record_updated_at(record: dict[str, Any] | None, fallback_path: Path | None = None) -> int:
    if isinstance(record, dict):
        for key in ("updated_at", "completed_at", "failed_at", "confirmed_at", "started_at", "created_at"):
            timestamp = coerce_record_timestamp(record.get(key))
            if timestamp:
                return timestamp
    return path_mtime_timestamp(fallback_path)


def record_owner_username(record: dict[str, Any] | None) -> str:
    if not isinstance(record, dict):
        return LEGACY_OWNER_ID
    username = str(record.get("owner_username") or record.get("created_by_username") or "").strip()
    if username:
        return username
    owner = record_owner_id(record)
    if owner == LEGACY_OWNER_ID:
        return LEGACY_OWNER_ID
    if owner == SYSTEM_OWNER_ID:
        return "system"
    return owner


def record_audit_fields(record: dict[str, Any] | None, fallback_path: Path | None = None) -> dict[str, Any]:
    return {
        "created_at": record_created_at(record, fallback_path),
        "updated_at": record_updated_at(record, fallback_path),
        "owner_user_id": record_owner_id(record),
        "owner_username": record_owner_username(record),
    }


def enrich_record_audit_fields(record: dict[str, Any], fallback_path: Path | None = None) -> dict[str, Any]:
    copy = dict(record)
    copy.update(record_audit_fields(copy, fallback_path))
    return copy


def record_matches_owner_filter(record: dict[str, Any], target_user_id: str | None) -> bool:
    if not target_user_id:
        return True
    target = str(target_user_id).strip()
    owner = record_owner_id(record)
    if target in {LEGACY_OWNER_ID, "legacy"}:
        return owner == LEGACY_OWNER_ID
    if target in {SYSTEM_OWNER_ID, "system"}:
        return owner == SYSTEM_OWNER_ID
    return owner == target


def record_visible_to_user(record: dict[str, Any], user: dict[str, Any], target_user_id: str | None = None) -> bool:
    if user_is_admin(user):
        return record_matches_owner_filter(record, target_user_id)
    owner = record_owner_id(record)
    shared = record.get("shared_with_user_ids") if isinstance(record.get("shared_with_user_ids"), list) else []
    return owner == user["id"] or user["id"] in {str(item) for item in shared} or "*" in shared


def record_mutable_by_user(record: dict[str, Any], user: dict[str, Any]) -> bool:
    return user_is_admin(user) or record_owner_id(record) == user["id"]


def resource_name_key(value: Any) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip()).casefold()


def resource_owner_id_for_new_record(user: dict[str, Any]) -> str:
    return str(user.get("id") or LEGACY_OWNER_ID)


def duplicate_name_error(resource_label: str) -> None:
    raise HTTPException(status_code=409, detail=f"{resource_label}名称已存在，请换一个名称")


def assert_unique_accessory_name(config: dict[str, Any], name: Any, owner_user_id: str, *, exclude_id: str = "") -> None:
    key = resource_name_key(name)
    if not key:
        return
    for item in config.get("accessories", []):
        if exclude_id and accessory_uid(item) == exclude_id:
            continue
        if record_owner_id(item) == owner_user_id and resource_name_key(item.get("name") or item.get("label")) == key:
            duplicate_name_error("配件")


def task_record_name(record: dict[str, Any]) -> str:
    return str(record.get("name") or record.get("label") or record.get("candidate_name") or record.get("id") or "")


def task_matches_excluded_identity(
    task: dict[str, Any],
    *,
    excluded_pipeline_task_ids: set[str],
    excluded_ai_task_ids: set[str],
) -> bool:
    task_id = str(task.get("id") or "")
    if task_id in excluded_pipeline_task_ids:
        return True
    ai_task_id = str(task.get("ai_task_id") or "")
    if ai_task_id and ai_task_id in excluded_ai_task_ids:
        return True
    return False


def assert_unique_task_name(
    name: Any,
    owner_user_id: str,
    *,
    exclude_pipeline_task_id: str = "",
    exclude_ai_task_id: str = "",
) -> None:
    key = resource_name_key(name)
    if not key:
        return
    pipeline_tasks = load_pipeline_tasks()
    excluded_pipeline_task_ids = {exclude_pipeline_task_id} if exclude_pipeline_task_id else set()
    excluded_ai_task_ids = {exclude_ai_task_id} if exclude_ai_task_id else set()
    for task in pipeline_tasks:
        if exclude_pipeline_task_id and str(task.get("id") or "") == exclude_pipeline_task_id:
            linked_ai_task_id = str(task.get("ai_task_id") or "")
            if linked_ai_task_id:
                excluded_ai_task_ids.add(linked_ai_task_id)
            break
    for task in pipeline_tasks:
        if task_matches_excluded_identity(
            task,
            excluded_pipeline_task_ids=excluded_pipeline_task_ids,
            excluded_ai_task_ids=excluded_ai_task_ids,
        ):
            continue
        if record_owner_id(task) == owner_user_id and resource_name_key(task_record_name(task)) == key:
            duplicate_name_error("任务")
    for task in load_ai_detection_tasks():
        if str(task.get("id") or "") in excluded_ai_task_ids:
            continue
        if record_owner_id(task) == owner_user_id and resource_name_key(task_record_name(task)) == key:
            duplicate_name_error("任务")


def assert_unique_dataset_name(name: Any, owner_user_id: str, user: dict[str, Any], *, exclude_dataset_id: str = "") -> None:
    key = resource_name_key(name)
    if not key:
        return
    for dataset in training_resources_payload(user=user).get("datasets", []):
        if exclude_dataset_id and str(dataset.get("id") or "") == exclude_dataset_id:
            continue
        if record_owner_id(dataset) == owner_user_id and resource_name_key(dataset.get("display_name") or dataset.get("id")) == key:
            duplicate_name_error("样本集")


def assert_unique_model_name(name: Any, owner_user_id: str, *, exclude_run_id: str = "") -> None:
    key = resource_name_key(name)
    if not key:
        return
    seen_run_ids: set[str] = set()
    for spec in list_trained_model_specs():
        run_id = str(spec.get("run_id") or "")
        if not run_id or run_id in seen_run_ids:
            continue
        seen_run_ids.add(run_id)
        if exclude_run_id and run_id == exclude_run_id:
            continue
        if record_owner_id(spec) == owner_user_id and resource_name_key(spec.get("label") or run_id) == key:
            duplicate_name_error("模型")


def default_training_state() -> dict[str, Any]:
    return json.loads(json.dumps(DEFAULT_CONFIG["training"]))


def clear_training_private_state(training: dict[str, Any], reason: str) -> dict[str, Any]:
    training["preview_urls"] = []
    training["previews"] = []
    training["preview_cache_key"] = None
    training["preview_sprite_versions"] = {}
    training["last_preview_id"] = ""
    training["approved_preview_id"] = ""
    training["active_training_task_id"] = ""
    training["preview_stale_reason"] = reason
    return training


def normalize_training_owner_key(owner_user_id: Any) -> str:
    owner = str(owner_user_id or "").strip()
    return owner or LEGACY_OWNER_ID


def training_state_store(config: dict[str, Any]) -> dict[str, dict[str, Any]]:
    raw_store = config.get("training_by_user_id") if isinstance(config.get("training_by_user_id"), dict) else {}
    store: dict[str, dict[str, Any]] = {
        normalize_training_owner_key(owner): state
        for owner, state in raw_store.items()
        if isinstance(state, dict)
    }
    legacy_training = config.get("training") if isinstance(config.get("training"), dict) else None
    if legacy_training:
        owner = normalize_training_owner_key(record_owner_id(legacy_training))
        store.setdefault(owner, legacy_training)
    config["training_by_user_id"] = store
    return store


def sanitize_training_state_for_user(
    training: dict[str, Any] | None,
    user: dict[str, Any],
    selected_ids: set[str],
    target_user_id: str | None = None,
) -> dict[str, Any]:
    if not isinstance(training, dict):
        return default_training_state()
    if not record_visible_to_user(training, user, target_user_id):
        return default_training_state()
    scoped_training = training
    raw_selected = [str(item) for item in scoped_training.get("selected_accessory_ids", []) if str(item)]
    if raw_selected:
        visible_selected = [item_id for item_id in raw_selected if item_id in selected_ids]
        if len(visible_selected) != len(raw_selected):
            scoped_training["selected_accessory_ids"] = visible_selected
            clear_training_private_state(scoped_training, "training_selection_not_visible")
    return scoped_training


def training_state_for_user(
    config: dict[str, Any],
    user: dict[str, Any],
    selected_ids: set[str],
    target_user_id: str | None = None,
) -> dict[str, Any]:
    store = training_state_store(config)
    if user_is_admin(user) and target_user_id:
        owner_key = normalize_training_owner_key(target_user_id)
    elif user_is_admin(user):
        states = [
            sanitize_training_state_for_user(dict(state), user, selected_ids, None)
            for state in store.values()
            if isinstance(state, dict) and record_visible_to_user(state, user)
        ]
        aggregate = default_training_state()
        aggregate["training_states"] = states
        return aggregate
    else:
        owner_key = normalize_training_owner_key(user["id"])
    state = store.get(owner_key)
    return sanitize_training_state_for_user(dict(state) if isinstance(state, dict) else None, user, selected_ids, target_user_id)


def set_training_state_for_user(config: dict[str, Any], user: dict[str, Any], training_state: dict[str, Any]) -> None:
    state = {**default_training_state(), **training_state, **current_owner_fields()}
    owner_key = normalize_training_owner_key(state.get("owner_user_id") or user["id"])
    store = training_state_store(config)
    store[owner_key] = state
    config["training_by_user_id"] = store
    if user_is_admin(user):
        config["training"] = state


def sync_training_state_from_task(job_id: str) -> None:
    task = find_training_task(job_id)
    if not task:
        return
    owner_user_id = str(task.get("owner_user_id") or task.get("user_id") or task.get("created_by_user_id") or LEGACY_OWNER_ID)
    owner_username = str(task.get("owner_username") or task.get("username") or task.get("created_by_username") or "")
    full_config = load_config()
    store = training_state_store(full_config)
    owner_key = normalize_training_owner_key(owner_user_id)
    existing = store.get(owner_key) if isinstance(store.get(owner_key), dict) else {}
    state = {**default_training_state(), **dict(existing)}
    for key in (
        "status",
        "progress",
        "note",
        "error",
        "current_epoch",
        "total_epochs",
        "completed_at",
        "stopped_at",
        "cancelled_at",
        "return_code",
        "training_executor",
        "remote_training_status",
        "remote_training_poll_error",
        "training_run_dir",
        "imported_model_path",
        "runpod_job_id",
        "runpod_best_pt_sha256",
    ):
        if key in task:
            state[key] = task.get(key)
    state.update(
        {
            "active_training_task_id": str(task.get("job_id") or task.get("task_id") or job_id),
            "active_training_action": task.get("action") or state.get("active_training_action") or "",
            "selected_accessory_ids": task.get("selected_accessory_ids") or state.get("selected_accessory_ids") or [],
            "sample_count": task.get("sample_count") or state.get("sample_count") or 0,
            "mode": task.get("train_mode") or task.get("mode") or task.get("model_variant") or state.get("mode") or "yolo",
            "epochs": task.get("epochs") or state.get("epochs") or 0,
            "image_size": task.get("image_size") or state.get("image_size") or 0,
            "dataset_id": task.get("dataset_id") or task.get("source_dataset_id") or state.get("dataset_id") or "",
            "owner_user_id": owner_user_id,
            "owner_username": owner_username,
            "updated_at": int(time.time()),
        }
    )
    store[owner_key] = state
    full_config["training_by_user_id"] = store
    current_training = full_config.get("training") if isinstance(full_config.get("training"), dict) else {}
    current_owner_key = normalize_training_owner_key(record_owner_id(current_training)) if current_training else ""
    if current_owner_key == owner_key or str(current_training.get("active_training_task_id") or "") == job_id:
        full_config["training"] = state
    save_config(full_config)
    sync_pipeline_training_state_from_task(task)


def training_task_model_variant(task: dict[str, Any]) -> str:
    variant = str(task.get("model_variant") or task.get("mode") or task.get("train_mode") or "yolo").strip()
    return variant if variant in {"yolo", "yolo_ocr"} else "yolo"


def training_task_model_id(task: dict[str, Any], job_id: str) -> str:
    spec = next((item for item in list_trained_model_specs() if str(item.get("run_id") or "") == job_id), None)
    if spec and str(spec.get("id") or "").strip():
        return str(spec.get("id") or "").strip()
    return f"trained_{job_id}__{training_task_model_variant(task)}"


def auto_optimize_task_id_from_pipeline_task(pipeline_task_id: str, pipeline_task: dict[str, Any] | None = None) -> str:
    if pipeline_task:
        direct = sanitize_ai_detection_task_id(pipeline_task.get("ai_task_id") or "")
        if direct:
            return direct
    clean_pipeline_id = str(pipeline_task_id or "").strip()
    prefix = "pipe_ai_"
    if clean_pipeline_id.startswith(prefix):
        return sanitize_ai_detection_task_id(clean_pipeline_id[len(prefix):])
    return ""


def sync_auto_optimize_training_candidate_from_task(
    task: dict[str, Any],
    *,
    ai_task_id: str,
    model_id: str,
) -> None:
    clean_task_id = sanitize_ai_detection_task_id(ai_task_id)
    if not clean_task_id:
        return
    job_id = str(task.get("job_id") or task.get("task_id") or "").strip()
    if not job_id:
        return
    status = str(task.get("status") or "").strip()
    if status not in {"completed", "failed", "stopped", "cancelled", "canceled"}:
        return
    with _auto_optimize_lock:
        state = load_auto_optimize_state(clean_task_id)
        candidates = [item for item in state.get("candidate_models") or [] if isinstance(item, dict)]
        existing = next((item for item in candidates if str(item.get("job_id") or "") == job_id), None)
        candidate = existing or {}
        candidate.update(
            {
                "job_id": job_id,
                "status": "completed" if status == "completed" else status,
                "progress": int(task.get("progress") or 100),
                "dataset_id": str(task.get("source_dataset_id") or task.get("dataset_id") or ""),
                "model_id": model_id,
                "note": str(task.get("note") or task.get("error") or "")[:240],
                "updated_at": int(time.time()),
                "training_parameters": {
                    "training_epochs": int(task.get("epochs") or task.get("total_epochs") or 0),
                    "training_image_size": int(task.get("image_size") or 0),
                },
            }
        )
        if not existing:
            candidate["created_at"] = int(task.get("created_at") or time.time())
            candidates.insert(0, candidate)
        else:
            candidates = [candidate, *[item for item in candidates if item is not candidate]]
        state["candidate_models"] = candidates
        if task.get("pipeline_task_name") and not state.get("task_name"):
            state["task_name"] = str(task.get("pipeline_task_name") or "")
        if task.get("selected_accessory_ids") and not state.get("selected_accessory_ids"):
            state["selected_accessory_ids"] = task.get("selected_accessory_ids") or []
        if status == "completed":
            auto_optimize_stop_capture_for_model_locked(state, model_id, reason="completed_model_ready")
        save_auto_optimize_state(state)


def sync_pipeline_training_state_from_task(task: dict[str, Any]) -> None:
    job_id = str(task.get("job_id") or task.get("task_id") or "").strip()
    pipeline_task_id = str(task.get("pipeline_task_id") or "").strip()
    if not job_id or not pipeline_task_id:
        return
    status = str(task.get("status") or "").strip()
    if status not in {"completed", "failed", "stopped", "cancelled", "canceled"}:
        return
    model_id = training_task_model_id(task, job_id)
    with _pipeline_tasks_lock:
        pipeline_task = load_pipeline_task(pipeline_task_id)
        ai_task_id = auto_optimize_task_id_from_pipeline_task(pipeline_task_id, pipeline_task)
        if pipeline_task:
            method = normalize_pipeline_detection_method(
                str(
                    pipeline_task.get("detection_method")
                    or (pipeline_task.get("params") or {}).get("train_mode")
                    or (pipeline_task.get("params") or {}).get("route")
                    or ""
                )
            )
            if method in {"yolo", "yolo_ocr"}:
                if status == "completed":
                    pipeline_task.update(
                        {
                            "stage": "library",
                            "status": "completed",
                            "progress": 100,
                            "training_task_id": job_id,
                            "model_run_id": job_id,
                            "ai_model_id": model_id,
                            "model_status": "available",
                            "model_exists": True,
                            "linked_view": "inspect",
                            "last_error": "",
                            "job_note": str(task.get("note") or "模型训练已完成。")[:200],
                        }
                    )
                    link_pipeline_trained_model(pipeline_task)
                else:
                    pipeline_task.update(
                        {
                            "stage": "training",
                            "status": "failed" if status == "failed" else "stopped",
                            "progress": 100,
                            "training_task_id": job_id,
                            "last_error": str(task.get("error") or task.get("note") or "")[:240],
                            "job_note": str(task.get("note") or "")[:200],
                        }
                    )
                pipeline_task["updated_at"] = int(time.time())
                save_pipeline_task(pipeline_task)
            elif method == "ai" and status == "completed":
                pipeline_task.update(
                    {
                        "stage": "library",
                        "status": "completed",
                        "progress": 100,
                        "last_error": "",
                        "job_note": "YOLO 接管模型已训练完成，自动优化采集已停止。",
                        "updated_at": int(time.time()),
                    }
                )
                save_pipeline_task(pipeline_task)
    if ai_task_id:
        sync_auto_optimize_training_candidate_from_task(task, ai_task_id=ai_task_id, model_id=model_id)


def merge_scoped_accessory_updates(full_config: dict[str, Any], scoped_config: dict[str, Any], user: dict[str, Any]) -> None:
    scoped_by_id = {
        accessory_uid(item): item
        for item in scoped_config.get("accessories", [])
        if isinstance(item, dict)
    }
    merged = []
    for item in full_config.get("accessories", []):
        if not isinstance(item, dict):
            merged.append(item)
            continue
        uid = accessory_uid(item)
        if uid in scoped_by_id and record_mutable_by_user(item, user):
            merged.append(scoped_by_id[uid])
        else:
            merged.append(item)
    full_config["accessories"] = merged


def scope_config_for_user(config: dict[str, Any], user: dict[str, Any] | None = None, target_user_id: str | None = None) -> dict[str, Any]:
    user = user or current_auth_user()
    scoped = json.loads(json.dumps(config))
    scoped.pop("plc_runtime_coordination", None)
    scoped.pop(PLC_CAPTURE_RESULTS_KEY, None)
    scoped["accessories"] = [
        item
        for item in scoped.get("accessories", [])
        if isinstance(item, dict) and record_visible_to_user(item, user, target_user_id)
    ]
    selected_ids = {accessory_uid(item) for item in scoped.get("accessories", [])}
    training = training_state_for_user(scoped, user, selected_ids, target_user_id)
    if isinstance(training.get("selected_accessory_ids"), list):
        training["selected_accessory_ids"] = [item_id for item_id in training["selected_accessory_ids"] if str(item_id) in selected_ids]
    scoped["training"] = training
    return scoped


def require_record_access(record: dict[str, Any], user: dict[str, Any] | None = None, *, write: bool = False) -> None:
    user = user or current_auth_user()
    allowed = record_mutable_by_user(record, user) if write else record_visible_to_user(record, user)
    if not allowed:
        raise HTTPException(status_code=404, detail="Resource not found")


def route_required_permission(path: str, method: str) -> str | None:
    clean_path = path.rstrip("/") or "/"
    plc_admin_routes = {
        ("/api/plc/config", "GET"),
        ("/api/plc/config", "POST"),
        ("/api/plc/workstations/pair", "POST"),
        ("/api/plc/workstations", "GET"),
        ("/api/plc/workstation/config", "POST"),
        ("/api/plc/workstation/profile-verification", "POST"),
    }
    plc_runtime_routes = {
        ("/api/plc/workstation/connect", "POST"),
        ("/api/plc/workstation/connect/activate", "POST"),
        ("/api/plc/workstation/lease/heartbeat", "POST"),
        ("/api/plc/workstation/lease/disconnect", "POST"),
    }
    if (clean_path, method) in plc_admin_routes:
        return "system_settings"
    if clean_path == "/api/plc/workstation" and method == "GET":
        return "inspection"
    if (clean_path, method) in plc_runtime_routes:
        return "inspection"
    if clean_path.startswith("/api/plc/workstation/dispatches/") and method == "POST":
        suffix = clean_path.rsplit("/", 1)[-1]
        if suffix in {"attempt", "receipt"}:
            return "inspection"
    if clean_path.startswith("/api/auth/users"):
        return "user_management"
    if clean_path.startswith("/api/windows-worker"):
        return "worker_settings"
    if clean_path.startswith("/api/agent"):
        return "agent_config"
    if clean_path.startswith("/api/admin"):
        return "ai_config"
    if clean_path.startswith("/api/ai/config"):
        return "ai_config"
    if clean_path.startswith("/api/stream/config"):
        return "system_settings"
    if clean_path.startswith("/api/plc/capture-"):
        return "inspection"
    if clean_path.startswith("/api/plc"):
        return "system_settings"
    if clean_path.startswith("/api/data-analysis"):
        return "ai_detection"
    if clean_path.startswith("/api/incoming-text/tasks") and (clean_path.endswith("/references") or method in {"PUT", "PATCH", "DELETE"}):
        return "incoming_material_config"
    if clean_path.startswith("/api/incoming-text/references"):
        return "incoming_material_config"
    if clean_path.startswith("/api/incoming-text"):
        return "inspection"
    if clean_path.startswith("/api/locateanything") or clean_path.startswith("/api/label-sheets") or clean_path.startswith("/api/experimental/label-inspector"):
        return "system_settings"
    if clean_path.startswith("/api/ai/tasks"):
        return "ai_detection"
    if clean_path == "/api/config" or clean_path.startswith("/api/config/"):
        return "system_settings" if method != "GET" or clean_path == "/api/config" else None
    if clean_path.startswith("/api/accessories"):
        return "accessory_library"
    if clean_path.startswith("/api/training/resources"):
        return "model_library"
    if clean_path.startswith("/api/training") or clean_path.startswith("/api/pipeline") or clean_path.startswith("/api/image-jobs") or clean_path.startswith("/api/image-job-candidates"):
        return "training_pipeline"
    if clean_path.startswith("/api/backgrounds"):
        return "training_pipeline"
    if clean_path.startswith("/api/models"):
        return "inspection"
    if clean_path.startswith("/api/analyze"):
        return "inspection"
    return None


def route_allowed_permissions(path: str, method: str) -> tuple[str, ...]:
    clean_path = path.rstrip("/") or "/"
    permission = route_required_permission(path, method)
    if clean_path.startswith("/api/training/resources"):
        return ("model_library", "training_pipeline")
    if clean_path.startswith("/api/analyze"):
        return ("inspection", "ai_detection")
    if clean_path.startswith("/api/plc/capture-"):
        return ("inspection", "ai_detection")
    if clean_path == "/api/pipeline/tasks" and method == "GET":
        return ("training_pipeline", "incoming_material_config", "inspection")
    if clean_path == "/api/pipeline/tasks" and method == "POST":
        return ("training_pipeline", "incoming_material_config")
    if clean_path.startswith("/api/pipeline/tasks/") and method == "PATCH":
        return ("training_pipeline", "incoming_material_config")
    if clean_path.startswith("/api/pipeline/tasks/") and method == "DELETE":
        return ("training_pipeline", "incoming_material_config")
    if clean_path.startswith("/api/incoming-text/tasks") and method == "GET":
        return ("inspection", "incoming_material_config")
    if clean_path == "/api/plc/workstation" and method == "GET":
        return ("inspection", "ai_detection", "system_settings")
    plc_runtime_routes = {
        ("/api/plc/workstation/connect", "POST"),
        ("/api/plc/workstation/connect/activate", "POST"),
        ("/api/plc/workstation/lease/heartbeat", "POST"),
        ("/api/plc/workstation/lease/disconnect", "POST"),
    }
    if (clean_path, method) in plc_runtime_routes:
        return ("inspection", "ai_detection")
    if clean_path.startswith("/api/plc/workstation/dispatches/") and method == "POST" and clean_path.rsplit("/", 1)[-1] in {"attempt", "receipt"}:
        return ("inspection", "ai_detection")
    return (permission,) if permission else ()


def require_permission(permission: str, *, detail: str = "Permission denied") -> None:
    if not user_has_permission(current_auth_user(), permission):
        raise HTTPException(status_code=403, detail=detail)


def require_analyze_model_permission(model_id: str | None) -> None:
    user = current_auth_user()
    if user_has_permission(user, "inspection"):
        return
    if user_has_permission(user, "ai_detection"):
        spec = selected_model_spec(model_id, scope_config_for_user(load_config(), user))
        if spec.get("is_ai_detection"):
            return
    raise HTTPException(status_code=403, detail="Inspection permission required for non-AI detection models")




def output_path_visible_to_user(request_path: str, user: dict[str, Any]) -> bool:
    if user_is_admin(user):
        return True
    relative = request_path.removeprefix("/outputs/").lstrip("/")
    candidate = (OUTPUT_DIR / PurePosixPath(relative)).resolve()
    try:
        rel_parts = candidate.relative_to(OUTPUT_DIR.resolve()).parts
    except ValueError:
        return False
    # Per-user subtree (outputs/users/<id>/...) is private to its owner.
    if len(rel_parts) >= 2 and rel_parts[0] == "users":
        return rel_parts[1] == str(user["id"])
    # Shared/legacy outputs written to the OUTPUT_DIR root are visible to any
    # authenticated user (the /api permission gate already protects who can
    # create pipeline artifacts); this keeps pose/sample images loadable when a
    # task was owned by a legacy/empty owner instead of a per-user subtree.
    return True


_login_rate_limit_lock = threading.RLock()
_login_failures: dict[str, list[float]] = {}
_login_blocked_until: dict[str, float] = {}


def request_client_ip(request: Request) -> str:
    forwarded = str(request.headers.get("x-forwarded-for") or "").split(",", 1)[0].strip()
    if forwarded:
        return forwarded
    return str((request.client.host if request.client else "") or "unknown")


def login_rate_limit_keys(request: Request, username: str) -> list[str]:
    normalized_username = str(username or "").strip().casefold() or "<empty>"
    return [f"user:{normalized_username}", f"ip:{request_client_ip(request)}"]


def prune_login_rate_limit_state(now: float) -> None:
    window_start = now - LOGIN_RATE_LIMIT_WINDOW_SECONDS
    for key, attempts in list(_login_failures.items()):
        kept = [stamp for stamp in attempts if stamp >= window_start]
        if kept:
            _login_failures[key] = kept
        else:
            _login_failures.pop(key, None)
    for key, blocked_until in list(_login_blocked_until.items()):
        if blocked_until <= now:
            _login_blocked_until.pop(key, None)


def enforce_login_rate_limit(request: Request, username: str) -> None:
    now = time.time()
    with _login_rate_limit_lock:
        prune_login_rate_limit_state(now)
        retry_after = 0
        for key in login_rate_limit_keys(request, username):
            blocked_until = float(_login_blocked_until.get(key) or 0.0)
            if blocked_until > now:
                retry_after = max(retry_after, int(math.ceil(blocked_until - now)))
        if retry_after > 0:
            raise HTTPException(
                status_code=429,
                detail="Too many login attempts. Please try again later.",
                headers={"Retry-After": str(retry_after)},
            )


def record_failed_login_attempt(request: Request, username: str) -> None:
    now = time.time()
    with _login_rate_limit_lock:
        prune_login_rate_limit_state(now)
        for key in login_rate_limit_keys(request, username):
            attempts = _login_failures.setdefault(key, [])
            attempts.append(now)
            attempts[:] = [stamp for stamp in attempts if stamp >= now - LOGIN_RATE_LIMIT_WINDOW_SECONDS]
            if len(attempts) >= LOGIN_RATE_LIMIT_MAX_ATTEMPTS:
                _login_blocked_until[key] = max(float(_login_blocked_until.get(key) or 0.0), now + LOGIN_RATE_LIMIT_LOCKOUT_SECONDS)


def clear_failed_login_attempts(request: Request, username: str) -> None:
    with _login_rate_limit_lock:
        for key in login_rate_limit_keys(request, username):
            _login_failures.pop(key, None)
            _login_blocked_until.pop(key, None)


def require_docs_admin(request: Request) -> dict[str, Any]:
    user, store, _ = authenticate_request(request)
    if not users_exist(store) or not user or not user_is_admin(user):
        raise HTTPException(status_code=404, detail="Not found")
    return user


def is_private_or_local_host(hostname: str) -> bool:
    host = str(hostname or "").strip().lower()
    if not host:
        return False
    if host in {"localhost", "127.0.0.1", "::1"}:
        return True
    try:
        ip_value = ipaddress.ip_address(host)
    except ValueError:
        return host.endswith(".local")
    return any(
        (
            ip_value.is_private,
            ip_value.is_loopback,
            ip_value.is_link_local,
            ip_value.is_reserved,
        )
    )


def sanitize_url_for_public_user(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    parsed = urlsplit(raw)
    if not parsed.scheme or not parsed.netloc:
        return ""
    if is_private_or_local_host(parsed.hostname or ""):
        return ""
    return masked_url_for_status(raw)


def sanitize_path_for_public_user(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    if raw.startswith("/"):
        return ""
    normalized = raw.replace("\\", "/")
    if re.match(r"^[A-Za-z]:/", normalized):
        return ""
    return raw


def include_internal_runtime_details(user: dict[str, Any] | None) -> bool:
    viewer = user or {}
    return user_is_admin(viewer) or user_has_permission(viewer, "system_settings")


@app.middleware("http")
async def reject_untrusted_cross_origin_writes(request: Request, call_next):
    if request.method not in {"GET", "HEAD", "OPTIONS"}:
        origin = request.headers.get("origin")
        host = request.headers.get("host", "")
        if origin and not same_origin(origin, host) and not cors_origin_allowed(origin):
            return PlainTextResponse("Untrusted cross-origin write request", status_code=403)
    path = request.url.path
    auth_user: dict[str, Any] | None = None
    token = None
    public_auth_paths = {"/api/auth/status", "/api/auth/login", "/api/auth/bootstrap", "/api/auth/logout", "/api/version"}
    public_runpod_training_transfer = (
        request.method in {"GET", "HEAD"}
        and re.match(r"^/api/training/runpod/datasets/[^/]+/[^/]+/dataset\.zip$", path) is not None
    ) or (
        request.method == "PUT"
        and re.match(r"^/api/training/runpod/artifacts/[^/]+/[^/]+/run\.zip$", path) is not None
    )
    if path.startswith("/api/") and path not in public_auth_paths and not public_runpod_training_transfer:
        auth_user, auth_store, _ = authenticate_request(request)
        if not users_exist(auth_store):
            return JSONResponse({"detail": "First admin setup required", "setup_required": True}, status_code=503)
        if not auth_user:
            return JSONResponse({"detail": "Authentication required"}, status_code=401)
        required_permissions = route_allowed_permissions(path, request.method.upper())
        if required_permissions and not any(user_has_permission(auth_user, permission) for permission in required_permissions):
            return JSONResponse(
                {"detail": "Permission denied", "permission": " / ".join(required_permissions)},
                status_code=403,
            )
        request.state.user = auth_user
        token = _request_user.set(auth_user)
    elif path.startswith("/outputs/"):
        auth_user, auth_store, _ = authenticate_request(request)
        if not users_exist(auth_store):
            return PlainTextResponse("First admin setup required", status_code=503)
        if not auth_user:
            return PlainTextResponse("Authentication required", status_code=401)
        if not output_path_visible_to_user(path, auth_user):
            return PlainTextResponse("Not found", status_code=404)
        request.state.user = auth_user
        token = _request_user.set(auth_user)
    try:
        response = await call_next(request)
    finally:
        if token is not None:
            _request_user.reset(token)
    response.headers.setdefault("X-Frame-Options", "DENY")
    response.headers.setdefault("X-Content-Type-Options", "nosniff")
    response.headers.setdefault("Referrer-Policy", "no-referrer")
    response.headers.setdefault("Permissions-Policy", "camera=(self), serial=(self), microphone=(), geolocation=()")
    response.headers.setdefault(
        "Content-Security-Policy",
        "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; "
        "img-src 'self' data: blob:; media-src 'self' blob:; connect-src 'self' https: wss:; "
        "object-src 'none'; base-uri 'self'; frame-ancestors 'none'",
    )
    if str(request.headers.get("x-forwarded-proto") or request.url.scheme).lower() == "https":
        response.headers.setdefault("Strict-Transport-Security", "max-age=31536000; includeSubDomains")
    if request.method in {"GET", "HEAD"}:
        cacheable_ok = getattr(response, "status_code", 200) < 400
        if path.startswith("/static/") and cacheable_ok:
            response.headers.setdefault("Cache-Control", "public, max-age=604800, immutable")
        elif path.startswith("/react-preview/assets/") and cacheable_ok:
            response.headers.setdefault("Cache-Control", "public, max-age=604800, immutable")
        elif path == "/react-preview" or path.startswith("/react-preview/"):
            response.headers.setdefault("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
        elif path.startswith("/outputs/"):
            # Output artifacts are effectively write-once; let the browser show the
            # cached copy instantly on reopen and revalidate in the background
            # (StaticFiles still answers conditional requests with a cheap 304).
            response.headers.setdefault("Cache-Control", "private, max-age=600, stale-while-revalidate=86400")
        elif path.startswith("/api/"):
            response.headers.setdefault("Cache-Control", "no-store")
    return response

