STANDARD_PAPER_SIZES_MM = {
    "A4": (210.0, 297.0),
    "A5": (148.0, 210.0),
    "A6": (105.0, 148.0),
}

# Physical-to-pixel scale models a top-down inspection camera mounted ~70cm
# above the belt. At that height a moderate industrial lens frames roughly a
# 600mm-wide field of view, so a 1280px-wide canvas yields ~2.13 px/mm. This
# makes parts read at a realistic, prominent size while keeping every
# accessory's relative size physically consistent.
INSPECTION_CAMERA_HEIGHT_MM = 700.0
INSPECTION_CAMERA_FRAME_WIDTH_MM = 600.0
MM_TO_PREVIEW_PX = 1280.0 / INSPECTION_CAMERA_FRAME_WIDTH_MM
# Default object size is calibrated to the real reference photo ratio:
# bottle long side ~= 0.55-0.60 of an A4 manual long side in the 1280x900 preview.
DEFAULT_OBJECT_SIZE_MM = {"length_mm": 170.0, "width_mm": 38.0, "height_mm": 38.0}
# Object accessories no longer carry hand-entered dimensions. Instead the user
# picks a known-size reference object (and includes one photo of the part next to
# it); the size-inference agent calibrates the part's real dimensions from that
# reference. The catalog below provides the ground-truth scale for each option.
SIZE_REFERENCE_OBJECTS: dict[str, dict[str, Any]] = {
    "a4": {"id": "a4", "label": "A4 纸", "kind": "paper", "long_mm": 297.0, "short_mm": 210.0,
           "note": "A4 打印纸，长边 297mm、短边 210mm。"},
    "a5": {"id": "a5", "label": "A5 纸", "kind": "paper", "long_mm": 210.0, "short_mm": 148.0,
           "note": "A5 打印纸，长边 210mm、短边 148mm。"},
    "b5": {"id": "b5", "label": "B5 纸", "kind": "paper", "long_mm": 250.0, "short_mm": 176.0,
           "note": "B5 打印纸，长边 250mm、短边 176mm。"},
    "ruler": {"id": "ruler", "label": "直尺/卷尺", "kind": "ruler",
              "note": "直尺或卷尺：直接读取其厘米/毫米刻度作为比例尺（1 大格=10mm）。"},
}
DEFAULT_SIZE_REFERENCE = "a4"


def normalize_size_reference(value: Any) -> str:
    key = str(value or "").strip().lower()
    if key in {"", "none", "no", "无", "null"}:
        return ""
    if key in SIZE_REFERENCE_OBJECTS:
        return key
    aliases = {"尺子": "ruler", "直尺": "ruler", "卷尺": "ruler", "rule": "ruler",
               "a4纸": "a4", "a5纸": "a5", "b5纸": "b5"}
    return aliases.get(key, "")


def size_reference_payload(reference_key: str) -> dict[str, Any] | None:
    key = normalize_size_reference(reference_key)
    if not key:
        return None
    spec = SIZE_REFERENCE_OBJECTS.get(key)
    return dict(spec) if spec else None
# Legacy anchor/grid "pose collection" generation (the source of the old
# black-stick/anchor sprites) is disabled. Object standard images are now
# generated inside the training pipeline as single-object top-down photos and
# segmented into clean sprites.
POSE_COLLECTION_GRID_ENABLED = False
# Bump when the agent-MCP sprite build pipeline changes (segmentation method,
# render scale, metadata) so cached sprites on existing accessories are rebuilt
# on the next task instead of being reused stale.
AGENT_MCP_SPRITE_BUILD_VERSION = 4
PHOTO_HIGHLIGHT_SPRITE_BUILD_VERSION = 2
PHOTO_HIGHLIGHT_MIN_REFERENCE_IMAGES = 3
PHOTO_HIGHLIGHT_MAX_REFERENCE_IMAGES = 3
PHOTO_HIGHLIGHT_MASK_MAX_SIDE = 1024
PHOTO_HIGHLIGHT_MASK_RGB = (0, 255, 0)
PHOTO_HIGHLIGHT_MASK_MAX_ATTEMPTS = 3
CHROMA_SCREEN_REFERENCE_FRACTION_THRESHOLD = 0.05
CHROMA_SCREEN_OPTIONS: dict[str, dict[str, Any]] = {
    "green": {"name": "green", "rgb": (0, 255, 0), "hex": "#00FF00", "label": "pure green"},
    "blue": {"name": "blue", "rgb": (0, 0, 255), "hex": "#0000FF", "label": "pure blue"},
    "red": {"name": "red", "rgb": (255, 0, 0), "hex": "#FF0000", "label": "pure red"},
}
# Pose Planner Agent: a multimodal agent analyses each accessory's material and
# decides the structured pose set (count + per-pose generation instructions) as
# strict JSON. Rules only act as guardrail/validation (schema, bounds, physics,
# dedup) and as a fallback when the provider is unavailable. The plan is cached
# once per accessory so AI pose images are generated a single time and reused.
AGENT_MCP_POSE_PLAN_VERSION = 1
AGENT_MCP_POSE_PLAN_MIN_POSES = 1
AGENT_MCP_POSE_PLAN_MAX_POSES = 6
AGENT_MCP_POSE_PLAN_MIN_CONFIDENCE = 0.35
SOURCE_ASPECT_ELONGATED_MIN_RATIO = 1.35
UPRIGHT_SCALE_CORRECTION_MIN_RATIO = 1.01
UPRIGHT_SCALE_CORRECTION_MAX_RATIO = 3.25
UPRIGHT_SCALE_VISUAL_ADJUSTMENT = 0.8
PREVIEW_CANVAS_SIZE_PX = (1280, 900)
# Detection (bbox) label policy. Each object/document keeps its FULL (amodal)
# bounding box even when another part is pasted on top of it, so an occluded part
# is never truncated to a half-box. A part is only dropped from the labels when it
# is almost entirely hidden (and therefore not learnably visible).
DETECTION_MAX_OCCLUSION_FRACTION = 0.85
DETECTION_MIN_VISIBLE_AREA_PX = 220
# Background-plate derivation guards. A raw capture can be 4096x3072+, which makes
# cv2.inpaint(TELEA) on a large mask pathologically slow (the original incident
# pegged a core for 50+ min). We therefore downscale to a bounded working size,
# cap the inpaint radius, skip inpaint entirely when the hole is too large (cheap
# median+noise fill instead), and enforce a wall-clock budget. The plate is only
# an auxiliary background, so mild blur from up/downscaling is acceptable.
PIPELINE_BG_PLATE_MAX_SIDE = 1280
PIPELINE_BG_PLATE_MAX_INPAINT_RADIUS = 10
PIPELINE_BG_PLATE_INPAINT_MAX_MASK_FRAC = 0.35
PIPELINE_BG_PLATE_TIME_BUDGET_S = 20.0
PIPELINE_BG_MATCH_MAX_SOURCE_PATCHES = 12
PIPELINE_BG_MATCH_MAX_LIBRARY_IMAGES = 48
PIPELINE_BG_MATCH_DISTANCE_THRESHOLD = 0.22
BACKGROUND_ROI_PX = (70, 100, 1210, 800)
# Background sets are mutable runtime data.  Keep them below DATA_DIR so an
# immutable release never needs write access to its own source tree.
BACKGROUND_DIR = DATA_DIR / "backgrounds"
BACKGROUND_SETS_DIR = BACKGROUND_DIR / "sets"
BACKGROUND_SETS_MANIFEST = BACKGROUND_DIR / "background_sets.json"
DEFAULT_BACKGROUND_IMAGE = BACKGROUND_DIR / "conveyor_surface_topdown_ai_reference5.png"
STANDARDIZED_MANUALS_DIR = ROOT / "standardized_manuals"
PRECISE_MANUALS_DIR = ROOT / "manuals_from_individual_sources_precise"
BACKGROUND_SIZE_MM = {
    "width_mm": round((BACKGROUND_ROI_PX[2] - BACKGROUND_ROI_PX[0]) / MM_TO_PREVIEW_PX, 2),
    "height_mm": round((BACKGROUND_ROI_PX[3] - BACKGROUND_ROI_PX[1]) / MM_TO_PREVIEW_PX, 2),
    "mm_per_px": round(1 / MM_TO_PREVIEW_PX, 4),
    "px_per_mm": MM_TO_PREVIEW_PX,
}


def optional_float(value: Any) -> float | None:
    try:
        if value in (None, ""):
            return None
        parsed = float(value)
        return parsed if parsed > 0 else None
    except (TypeError, ValueError):
        return None


def physical_size_payload(
    material_type: str,
    paper_preset: str = "A4",
    paper_width_mm: Any = None,
    paper_height_mm: Any = None,
    object_length_mm: Any = None,
    object_width_mm: Any = None,
    object_height_mm: Any = None,
) -> dict[str, Any]:
    if material_type == "text":
        preset = paper_preset if paper_preset in STANDARD_PAPER_SIZES_MM else "custom"
        default_w, default_h = STANDARD_PAPER_SIZES_MM.get(preset, STANDARD_PAPER_SIZES_MM["A4"])
        if preset in STANDARD_PAPER_SIZES_MM:
            width_mm, height_mm = default_w, default_h
        else:
            width_mm = optional_float(paper_width_mm) or default_w
            height_mm = optional_float(paper_height_mm) or default_h
        return {
            "kind": "paper",
            "preset": preset,
            "width_mm": width_mm,
            "height_mm": height_mm,
        }
    return {
        "kind": "object",
        "length_mm": optional_float(object_length_mm) or DEFAULT_OBJECT_SIZE_MM["length_mm"],
        "width_mm": optional_float(object_width_mm) or DEFAULT_OBJECT_SIZE_MM["width_mm"],
        "height_mm": optional_float(object_height_mm) or DEFAULT_OBJECT_SIZE_MM["height_mm"],
    }


def ai_profile_dimensions_from_physical_size(physical_size: dict[str, Any] | None) -> dict[str, Any]:
    size = physical_size if isinstance(physical_size, dict) else {}
    if size.get("kind") == "paper":
        width = optional_float(size.get("width_mm")) or 210.0
        height = optional_float(size.get("height_mm")) or 297.0
        return {"length_mm": round(max(width, height), 2), "width_mm": round(min(width, height), 2), "height_mm": 0.3}
    length = optional_float(size.get("length_mm")) or DEFAULT_OBJECT_SIZE_MM["length_mm"]
    width = optional_float(size.get("width_mm")) or DEFAULT_OBJECT_SIZE_MM["width_mm"]
    height = optional_float(size.get("height_mm")) or DEFAULT_OBJECT_SIZE_MM["height_mm"]
    return {"length_mm": round(length, 2), "width_mm": round(width, 2), "height_mm": round(height, 2)}


def ai_profile_top_view_aspect_ratio(dimensions: dict[str, Any] | None) -> float:
    dims = dimensions if isinstance(dimensions, dict) else {}
    length = optional_float(dims.get("length_mm")) or 0.0
    width = optional_float(dims.get("width_mm")) or 0.0
    if length <= 0 or width <= 0:
        return 1.0
    return round(max(length, width) / max(1e-6, min(length, width)), 3)


def normalize_ai_profile_dimensions(raw: Any, fallback: dict[str, Any]) -> dict[str, Any]:
    raw_dict = raw if isinstance(raw, dict) else {}
    fallback_dict = fallback if isinstance(fallback, dict) else {}
    result: dict[str, Any] = {}
    for key in ("length_mm", "width_mm", "height_mm"):
        value = optional_float(raw_dict.get(key))
        result[key] = round(value, 2) if value else float(fallback_dict.get(key) or 0.0)
    return result


def apply_ai_profile_dimensions_to_physical_size(item: dict[str, Any], dimensions: dict[str, Any] | None) -> bool:
    """When the AI Profile judges real-world dimensions, feed them into the
    accessory physical_size so the compositor renders a consistent footprint for
    this accessory across every training set."""
    if accessory_material_type(item) != "object":
        return False
    dims = dimensions if isinstance(dimensions, dict) else {}
    length = optional_float(dims.get("length_mm"))
    width = optional_float(dims.get("width_mm"))
    height = optional_float(dims.get("height_mm"))
    if not (length and width and height):
        return False
    new_size = physical_size_payload(
        "object",
        object_length_mm=length,
        object_width_mm=width,
        object_height_mm=height,
    )
    if isinstance(item.get("physical_size"), dict) and item.get("physical_size") == new_size:
        return False
    item["physical_size"] = new_size
    return True


def ensure_dirs() -> None:
    for path in (
        UPLOAD_DIR,
        OUTPUT_DIR,
        DATA_DIR,
        NORMALIZED_DIR,
        TRAINING_JOBS_DIR,
        TRAINING_TASKS_DIR,
        ACCESSORY_CANDIDATES_DIR,
        AUTO_OPTIMIZE_DIR,
        IMAGE_WORKER_LOG_DIR,
        BACKGROUND_DIR,
        BACKGROUND_SETS_DIR,
    ):
        path.mkdir(parents=True, exist_ok=True)
    if not CONFIG_PATH.exists():
        save_config(DEFAULT_CONFIG)
    migrate_persisted_local_paths_once()


_config_io_lock = threading.RLock()
PLC_CONTROL_GENERATION_KEY = "plc_control_generation"
PLC_RUNTIME_COORDINATION_KEY = "plc_runtime_coordination"
PLC_CAPTURE_RESULTS_KEY = "plc_capture_results"
PLC_PROTECTED_CONFIG_KEYS = (
    "plc",
    PLC_CONTROL_GENERATION_KEY,
    "plc_dispatches",
    PLC_RUNTIME_COORDINATION_KEY,
    PLC_CAPTURE_RESULTS_KEY,
)
PLC_IO_CONFIG_FIELDS = frozenset(DEFAULT_PLC_CONFIG)
PLC_LEGACY_IO_CONFIG_FIELDS = frozenset(
    {
        "enabled", "protocol", "checksum_mode", "serial_port", "baudrate", "parity",
        "data_bits", "stop_bits", "d206_address", "y04_address", "write_y04", "timeout", "retries",
    }
)
_plc_namespace_write_authorized: contextvars.ContextVar[bool] = contextvars.ContextVar(
    "plc_namespace_write_authorized", default=False
)


def _plc_web_serial_empty_state() -> dict[str, dict[str, Any]]:
    return {"workstations": {}, "leases": {}, "dispatches": {}}


def _plc_web_serial_load_local() -> dict[str, dict[str, Any]]:
    try:
        raw = json.loads(PLC_WEB_SERIAL_STATE_PATH.read_text(encoding="utf-8"))
    except (FileNotFoundError, OSError, json.JSONDecodeError):
        return _plc_web_serial_empty_state()
    state = _plc_web_serial_empty_state()
    if isinstance(raw, dict):
        for key in state:
            value = raw.get(key)
            if isinstance(value, dict):
                state[key] = {str(item_id): dict(item) for item_id, item in value.items() if isinstance(item, dict)}
    return state


def _plc_web_serial_save_local(state: dict[str, dict[str, Any]]) -> None:
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    temporary = PLC_WEB_SERIAL_STATE_PATH.with_suffix(".tmp")
    temporary.write_text(json.dumps(state, ensure_ascii=False, indent=2, sort_keys=True), encoding="utf-8")
    os.replace(temporary, PLC_WEB_SERIAL_STATE_PATH)


def _plc_web_serial_record(row: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(row, dict):
        return None
    raw = row.get("raw_json")
    return dict(raw) if isinstance(raw, dict) else dict(row)


def _plc_workstation_row(record: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": record["id"],
        "token_hash": record["token_hash"],
        "name": record["name"],
        "status": record.get("status") or "commissioning",
        "config_generation": int(record.get("config_generation") or 0),
        "profile_verified": bool(record.get("profile_verified")),
        "created_by_user_id": record.get("created_by_user_id") or SYSTEM_OWNER_ID,
        "created_at": int(record.get("created_at") or 0),
        "updated_at": int(record.get("updated_at") or 0),
        "raw_json": record,
    }


def _plc_workstation_lease_row(record: dict[str, Any]) -> dict[str, Any]:
    return {
        "station_id": record["station_id"],
        "session_id": record["session_id"],
        "state": record["state"],
        "lease_epoch": int(record["lease_epoch"]),
        "owner_user_id": record["owner_user_id"],
        "model_id": record.get("model_id") or "",
        "client_instance_id": record["client_instance_id"],
        "bundle_version": record["bundle_version"],
        "config_generation": int(record["config_generation"]),
        "heartbeat_at": int(record["heartbeat_at"]),
        "expires_at": int(record["expires_at"]),
        "raw_json": record,
    }


def _plc_web_serial_dispatch_row(record: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": record["dispatch_id"],
        "station_id": record["station_id"],
        "detection_request_id": record["detection_request_id"],
        "session_id": record["session_id"],
        "lease_epoch": int(record["lease_epoch"]),
        "config_generation": int(record["config_generation"]),
        "status": record["status"],
        "passed": bool(record.get("passed")),
        "deadline_at": int(record.get("deadline_at") or 0),
        "created_at": int(record["created_at"]),
        "updated_at": int(record["updated_at"]),
        "raw_json": record,
    }


def _plc_web_serial_upsert_row(table_name: str, row: dict[str, Any], local_key: str, row_id: str) -> None:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        repository.upsert_row(table_name, row)
        return
    if str(os.environ.get(PLC_WEB_SERIAL_JSON_TEST_ENV, "")).strip().lower() not in {"1", "true", "yes"}:
        raise PlcConfigError("plc_web_serial_postgres_coordination_unavailable")
    with _config_io_lock:
        state = _plc_web_serial_load_local()
        state[local_key][row_id] = row
        _plc_web_serial_save_local(state)


def _plc_web_serial_mutate(
    station_id: str,
    dispatch_id: str | None,
    mutator: Callable[[dict[str, dict[str, Any] | None]], None],
) -> dict[str, dict[str, Any] | None]:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        return repository.mutate_plc_web_serial_rows(station_id, dispatch_id, mutator)
    if str(os.environ.get(PLC_WEB_SERIAL_JSON_TEST_ENV, "")).strip().lower() not in {"1", "true", "yes"}:
        raise PlcConfigError("plc_web_serial_postgres_coordination_unavailable")
    with _config_io_lock:
        local = _plc_web_serial_load_local()
        state: dict[str, dict[str, Any] | None] = {
            "station": copy.deepcopy(local["workstations"].get(station_id)),
            "lease": copy.deepcopy(local["leases"].get(station_id)),
            "clock": {"now": int(time.time())},
        }
        if dispatch_id:
            state["dispatch"] = copy.deepcopy(local["dispatches"].get(dispatch_id))
        mutator(state)
        if state.get("station") is not None:
            local["workstations"][station_id] = dict(state["station"] or {})
        if state.get("lease") is not None:
            local["leases"][station_id] = dict(state["lease"] or {})
        if dispatch_id and state.get("dispatch") is not None:
            local["dispatches"][dispatch_id] = dict(state["dispatch"] or {})
        _plc_web_serial_save_local(local)
        return state


def _plc_web_serial_token_hash(token: str) -> str:
    return hashlib.sha256(str(token or "").encode("utf-8")).hexdigest()


def plc_web_serial_station_from_request(request: Request) -> dict[str, Any] | None:
    token = str(request.cookies.get(PLC_WORKSTATION_COOKIE) or "").strip()
    if not token:
        return None
    token_hash = _plc_web_serial_token_hash(token)
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        return _plc_web_serial_record(
            repository.fetch_one_by_columns("plc_workstations", {"token_hash": token_hash})
        )
    with _config_io_lock:
        for row in _plc_web_serial_load_local()["workstations"].values():
            record = _plc_web_serial_record(row)
            if record and hmac.compare_digest(str(record.get("token_hash") or ""), token_hash):
                return record
    return None


def require_plc_web_serial_station(request: Request) -> dict[str, Any]:
    station = plc_web_serial_station_from_request(request)
    if not station:
        raise HTTPException(status_code=409, detail="plc_workstation_not_paired")
    return station


def plc_web_serial_current_lease(station_id: str) -> dict[str, Any] | None:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        return _plc_web_serial_record(
            repository.fetch_by_primary_key("plc_workstation_leases", {"station_id": station_id})
        )
    with _config_io_lock:
        return _plc_web_serial_record(_plc_web_serial_load_local()["leases"].get(station_id))


def plc_web_serial_recent_dispatches(station_id: str, limit: int = 20) -> list[dict[str, Any]]:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        rows = repository.fetch_all("plc_web_serial_dispatches")
    else:
        with _config_io_lock:
            rows = list(_plc_web_serial_load_local()["dispatches"].values())
    records = [record for record in (_plc_web_serial_record(row) for row in rows) if record and record.get("station_id") == station_id]
    now = int(time.time())
    for record in records:
        if record.get("status") != "browser_attempt_declared" or int(record.get("deadline_at") or 0) > now:
            continue

        def expire_attempt(state: dict[str, dict[str, Any] | None]) -> None:
            current = _plc_web_serial_record(state.get("dispatch"))
            database_now = int((state.get("clock") or {}).get("now") or time.time())
            if current and current.get("status") == "browser_attempt_declared" and int(current.get("deadline_at") or 0) <= database_now:
                current["status"] = "uncertain"
                current["outcome"] = "uncertain"
                current["error_code"] = "browser_receipt_missing_after_deadline"
                current["updated_at"] = database_now
                state["dispatch"] = _plc_web_serial_dispatch_row(current)
                lease = _plc_web_serial_record(state.get("lease"))
                if lease and lease.get("in_flight_dispatch_id") == current.get("dispatch_id"):
                    lease.pop("in_flight_dispatch_id", None)
                    lease.pop("in_flight_deadline_at", None)
                    if lease.get("state") == "draining":
                        lease["state"] = "released"
                        lease["expires_at"] = database_now
                    state["lease"] = _plc_workstation_lease_row(lease)

        reconciled = _plc_web_serial_mutate(station_id, str(record["dispatch_id"]), expire_attempt)
        updated = _plc_web_serial_record(reconciled.get("dispatch"))
        if updated:
            record.clear()
            record.update(updated)
    return sorted(records, key=lambda item: int(item.get("updated_at") or 0), reverse=True)[:limit]


def plc_web_serial_ensure_current_station_contract(station: dict[str, Any]) -> dict[str, Any]:
    raw_config = station.get("config") if isinstance(station.get("config"), dict) else {}
    try:
        normalize_web_serial_config(raw_config)
        return station
    except PlcConfigError:
        migrated = migrate_web_serial_config(raw_config)

    station_id = str(station.get("id") or "")
    if not station_id:
        raise PlcConfigError("plc_workstation_not_found")

    def upgrade(state: dict[str, dict[str, Any] | None]) -> None:
        current = _plc_web_serial_record(state.get("station"))
        if not current:
            raise PlcConfigError("plc_workstation_not_found")
        current_raw = current.get("config") if isinstance(current.get("config"), dict) else {}
        try:
            normalize_web_serial_config(current_raw)
            return
        except PlcConfigError:
            current_migrated = migrate_web_serial_config(current_raw)
        now = int((state.get("clock") or {}).get("now") or time.time())
        current["config"] = current_migrated
        current["config_generation"] = int(current.get("config_generation") or 0) + 1
        current["profile_verified"] = False
        current["profile_verified_fingerprint"] = ""
        current["status"] = "commissioning"
        current["updated_at"] = now
        state["station"] = _plc_workstation_row(current)
        lease = _plc_web_serial_record(state.get("lease"))
        if lease and lease.get("state") in {"connecting", "active", "draining"}:
            in_flight_deadline = int(lease.get("in_flight_deadline_at") or 0)
            lease["state"] = "draining" if in_flight_deadline > now else "revoked_protocol_upgraded"
            lease["expires_at"] = max(now, in_flight_deadline)
            lease["heartbeat_at"] = now
            state["lease"] = _plc_workstation_lease_row(lease)

    upgraded = _plc_web_serial_mutate(station_id, None, upgrade)
    return _plc_web_serial_record(upgraded.get("station")) or {**station, "config": migrated}


def plc_web_serial_station_payload(station: dict[str, Any]) -> dict[str, Any]:
    station = plc_web_serial_ensure_current_station_contract(station)
    config = normalize_web_serial_config(station.get("config") if isinstance(station.get("config"), dict) else {})
    profile_verified = bool(
        station.get("profile_verified")
        and hmac.compare_digest(
            str(station.get("profile_verified_fingerprint") or ""),
            web_serial_profile_fingerprint(config),
        )
    )
    lease = plc_web_serial_current_lease(str(station["id"]))
    now = int(time.time())
    lease_active = bool(
        lease
        and lease.get("state") == "active"
        and int(lease.get("expires_at") or 0) > now
        and int(lease.get("config_generation") or -1) == int(station.get("config_generation") or 0)
        and lease.get("bundle_version") == WEB_SERIAL_PROTOCOL_VERSION
    )
    release_consistent = bool(current_release_version()["consistent"])
    return {
        "paired": True,
        "protocol_version": WEB_SERIAL_PROTOCOL_VERSION,
        "station": {
            "id": station["id"],
            "name": station["name"],
            "status": station.get("status") or "commissioning",
            "profile_verified": profile_verified,
        },
        "config": config,
        "config_generation": int(station.get("config_generation") or 0),
        "resolved_addresses": web_serial_resolved_addresses(config),
        "lease": lease if lease_active else None,
        "effective_enabled": bool(config["enabled"] and lease_active and release_consistent),
        "production_ready": bool(config["enabled"] and lease_active and profile_verified and release_consistent),
        "release_consistent": release_consistent,
        "heartbeat_seconds": WEB_SERIAL_HEARTBEAT_SECONDS,
        "lease_ttl_seconds": WEB_SERIAL_ACTIVE_LEASE_SECONDS,
        "recent_dispatches": plc_web_serial_recent_dispatches(str(station["id"])),
    }


def plc_web_serial_unpaired_payload() -> dict[str, Any]:
    return {
        "paired": False,
        "protocol_version": WEB_SERIAL_PROTOCOL_VERSION,
        "station": None,
        "config": None,
        "config_generation": 0,
        "resolved_addresses": {"result_register": "", "output_control_point": ""},
        "lease": None,
        "effective_enabled": False,
        "production_ready": False,
        "release_consistent": bool(current_release_version()["consistent"]),
        "heartbeat_seconds": WEB_SERIAL_HEARTBEAT_SECONDS,
        "lease_ttl_seconds": WEB_SERIAL_ACTIVE_LEASE_SECONDS,
        "recent_dispatches": [],
    }


def plc_web_serial_list_workstations() -> list[dict[str, Any]]:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        rows = repository.fetch_all("plc_workstations")
    else:
        with _config_io_lock:
            rows = list(_plc_web_serial_load_local()["workstations"].values())
    records = [
        plc_web_serial_ensure_current_station_contract(record)
        for record in (_plc_web_serial_record(row) for row in rows)
        if record
    ]
    return [
        {
            "id": record["id"],
            "name": record["name"],
            "status": record.get("status") or "commissioning",
            "profile_verified": bool(record.get("profile_verified")),
            "updated_at": int(record.get("updated_at") or 0),
        }
        for record in sorted(records, key=lambda item: str(item.get("name") or "").casefold())
    ]


def plc_web_serial_pair(request: Request, response: Response, name: str, station_id: str | None = None) -> dict[str, Any]:
    clean_name = " ".join(str(name or "").split())
    if not 1 <= len(clean_name) <= 80:
        raise PlcConfigError("workstation name must contain 1 through 80 characters")
    user = current_auth_user()
    now = int(time.time())
    current = plc_web_serial_station_from_request(request)
    requested_station_id = str(station_id or "").strip()
    if requested_station_id and (not current or current.get("id") != requested_station_id):
        repository = runtime_postgres_repository_or_none()
        if repository is not None:
            current = _plc_web_serial_record(
                repository.fetch_by_primary_key("plc_workstations", {"id": requested_station_id})
            )
        else:
            with _config_io_lock:
                current = _plc_web_serial_record(
                    _plc_web_serial_load_local()["workstations"].get(requested_station_id)
                )
        if not current:
            raise PlcConfigError("plc_workstation_not_found")
    token = secrets.token_urlsafe(32)
    if current:
        record = {**current, "token_hash": _plc_web_serial_token_hash(token), "name": clean_name, "updated_at": now}
    else:
        station_id = f"plcws_{uuid.uuid4().hex}"
        record = {
            "id": station_id,
            "token_hash": _plc_web_serial_token_hash(token),
            "name": clean_name,
            "status": "commissioning",
            "config_generation": 0,
            "profile_verified": False,
            "config": dict(DEFAULT_WEB_SERIAL_CONFIG),
            "created_by_user_id": str(user.get("id") or SYSTEM_OWNER_ID),
            "created_at": now,
            "updated_at": now,
        }
    if current:
        def rebind(state: dict[str, dict[str, Any] | None]) -> None:
            existing = _plc_web_serial_record(state.get("station"))
            if not existing:
                raise PlcConfigError("plc_workstation_not_found")
            existing.update({"token_hash": record["token_hash"], "name": clean_name, "updated_at": now})
            state["station"] = _plc_workstation_row(existing)
            lease = _plc_web_serial_record(state.get("lease"))
            if lease and lease.get("state") in {"connecting", "active", "draining"}:
                in_flight_deadline = int(lease.get("in_flight_deadline_at") or 0)
                lease.update({
                    "state": "draining" if in_flight_deadline > now else "revoked_browser_rebound",
                    "expires_at": max(now, in_flight_deadline),
                    "heartbeat_at": now,
                })
                state["lease"] = _plc_workstation_lease_row(lease)

        rebound = _plc_web_serial_mutate(str(record["id"]), None, rebind)
        record = _plc_web_serial_record(rebound.get("station")) or record
    else:
        _plc_web_serial_upsert_row("plc_workstations", _plc_workstation_row(record), "workstations", record["id"])
    response.set_cookie(
        PLC_WORKSTATION_COOKIE,
        token,
        max_age=PLC_WORKSTATION_COOKIE_TTL_SECONDS,
        httponly=True,
        secure=request_is_https(request),
        samesite="lax",
        path="/",
    )
    return plc_web_serial_station_payload(record)


def plc_web_serial_update_config(station_id: str, candidate: dict[str, Any]) -> dict[str, Any]:
    normalized = normalize_web_serial_config(candidate)

    def mutate(state: dict[str, dict[str, Any] | None]) -> None:
        station = _plc_web_serial_record(state.get("station"))
        if not station:
            raise PlcConfigError("plc_workstation_not_found")
        current_raw = station.get("config") if isinstance(station.get("config"), dict) else {}
        try:
            current = normalize_web_serial_config(current_raw)
            protocol_upgraded = False
        except PlcConfigError:
            current = migrate_web_serial_config(current_raw)
            protocol_upgraded = True
        now = int((state.get("clock") or {}).get("now") or time.time())
        if protocol_upgraded or current != normalized:
            station["config_generation"] = int(station.get("config_generation") or 0) + 1
            if protocol_upgraded or web_serial_profile_fingerprint(current) != web_serial_profile_fingerprint(normalized):
                station["profile_verified"] = False
                station["profile_verified_fingerprint"] = ""
                station["status"] = "commissioning"
        station["config"] = normalized
        station["updated_at"] = now
        state["station"] = _plc_workstation_row(station)
        lease = _plc_web_serial_record(state.get("lease"))
        if lease and lease.get("state") in {"connecting", "active", "draining"}:
            in_flight_deadline = int(lease.get("in_flight_deadline_at") or 0)
            lease["state"] = "draining" if in_flight_deadline > now else "revoked_config_changed"
            lease["expires_at"] = max(now, in_flight_deadline)
            lease["heartbeat_at"] = now
            state["lease"] = _plc_workstation_lease_row(lease)

    state = _plc_web_serial_mutate(station_id, None, mutate)
    record = _plc_web_serial_record(state.get("station"))
    if not record:
        raise PlcConfigError("plc_workstation_not_found")
    return plc_web_serial_station_payload(record)


def plc_web_serial_set_verified(station_id: str, verified: bool) -> dict[str, Any]:
    def mutate(state: dict[str, dict[str, Any] | None]) -> None:
        station = _plc_web_serial_record(state.get("station"))
        if not station:
            raise PlcConfigError("plc_workstation_not_found")
        now = int((state.get("clock") or {}).get("now") or time.time())
        station["profile_verified"] = bool(verified)
        station["profile_verified_fingerprint"] = web_serial_profile_fingerprint(
            migrate_web_serial_config(station.get("config") or {})
        ) if verified else ""
        station["status"] = "production" if verified else "commissioning"
        station["verified_at"] = now if verified else 0
        station["verified_by_user_id"] = str((current_auth_user() or {}).get("id") or "") if verified else ""
        station["updated_at"] = now
        state["station"] = _plc_workstation_row(station)

    state = _plc_web_serial_mutate(station_id, None, mutate)
    record = _plc_web_serial_record(state.get("station"))
    if not record:
        raise PlcConfigError("plc_workstation_not_found")
    return plc_web_serial_station_payload(record)


def plc_web_serial_claim_connecting_lease(station_id: str, request: PlcWorkstationLeaseRequest) -> dict[str, Any]:
    user = current_auth_user()
    client_instance_id = str(request.client_instance_id or "").strip()
    model_id = str(request.model_id or "").strip()
    bundle_version = str(request.bundle_version or "").strip()
    if not current_release_version()["consistent"]:
        raise PlcConfigError("plc_release_version_mismatch")
    if not re.fullmatch(r"[A-Za-z0-9._:-]{8,160}", client_instance_id):
        raise PlcConfigError("invalid_client_instance_id")
    if bundle_version != WEB_SERIAL_PROTOCOL_VERSION:
        raise PlcConfigError("plc_browser_protocol_version_mismatch")
    require_analyze_model_permission(model_id or None)

    def mutate(state: dict[str, dict[str, Any] | None]) -> None:
        station = _plc_web_serial_record(state.get("station"))
        if not station:
            raise PlcConfigError("plc_workstation_not_found")
        config = migrate_web_serial_config(station.get("config") if isinstance(station.get("config"), dict) else {})
        if not config["enabled"]:
            raise PlcConfigError("plc_workstation_disabled")
        now = int((state.get("clock") or {}).get("now") or time.time())
        current = _plc_web_serial_record(state.get("lease"))
        if current and current.get("state") in {"connecting", "active", "draining"} and int(current.get("expires_at") or 0) > now:
            raise PlcConfigError("plc_workstation_in_use")
        epoch = int((current or {}).get("lease_epoch") or 0) + 1
        lease = {
            "station_id": station_id,
            "session_id": f"plcwsess_{uuid.uuid4().hex}",
            "state": "connecting",
            "lease_epoch": epoch,
            "owner_user_id": str(user.get("id") or ""),
            "model_id": model_id,
            "client_instance_id": client_instance_id,
            "bundle_version": bundle_version,
            "config_generation": int(station.get("config_generation") or 0),
            "heartbeat_at": now,
            "expires_at": now + WEB_SERIAL_CONNECTING_LEASE_SECONDS,
            "serial_info": {},
        }
        state["lease"] = _plc_workstation_lease_row(lease)

    state = _plc_web_serial_mutate(station_id, None, mutate)
    lease = _plc_web_serial_record(state.get("lease"))
    if not lease:
        raise PlcConfigError("plc_lease_persist_failed")
    return lease


def plc_web_serial_activate_lease(station_id: str, request: PlcWorkstationLeaseActivateRequest) -> dict[str, Any]:
    user_id = str((current_auth_user() or {}).get("id") or "")

    def mutate(state: dict[str, dict[str, Any] | None]) -> None:
        lease = _plc_web_serial_record(state.get("lease"))
        station = _plc_web_serial_record(state.get("station"))
        now = int((state.get("clock") or {}).get("now") or time.time())
        if not lease or not station:
            raise PlcConfigError("plc_workstation_lease_missing")
        if lease.get("session_id") != request.session_id or int(lease.get("lease_epoch") or -1) != int(request.lease_epoch):
            raise PlcConfigError("plc_workstation_lease_fenced")
        if lease.get("owner_user_id") != user_id or lease.get("state") != "connecting" or int(lease.get("expires_at") or 0) <= now:
            raise PlcConfigError("plc_workstation_lease_expired")
        if int(lease.get("config_generation") or -1) != int(station.get("config_generation") or 0):
            raise PlcConfigError("plc_workstation_generation_changed")
        lease["state"] = "active"
        lease["heartbeat_at"] = now
        lease["expires_at"] = now + WEB_SERIAL_ACTIVE_LEASE_SECONDS
        lease["serial_info"] = {
            "usb_vendor_id": request.usb_vendor_id,
            "usb_product_id": request.usb_product_id,
        }
        state["lease"] = _plc_workstation_lease_row(lease)

    state = _plc_web_serial_mutate(station_id, None, mutate)
    return _plc_web_serial_record(state.get("lease")) or {}


def plc_web_serial_heartbeat(station_id: str, request: PlcWorkstationLeaseHeartbeatRequest) -> dict[str, Any]:
    user_id = str((current_auth_user() or {}).get("id") or "")

    def mutate(state: dict[str, dict[str, Any] | None]) -> None:
        lease = _plc_web_serial_record(state.get("lease"))
        station = _plc_web_serial_record(state.get("station"))
        now = int((state.get("clock") or {}).get("now") or time.time())
        if not lease or not station:
            raise PlcConfigError("plc_workstation_lease_missing")
        valid = (
            lease.get("session_id") == request.session_id
            and int(lease.get("lease_epoch") or -1) == int(request.lease_epoch)
            and lease.get("owner_user_id") == user_id
            and lease.get("state") == "active"
            and int(lease.get("expires_at") or 0) > now
            and int(lease.get("config_generation") or -1) == int(station.get("config_generation") or 0)
        )
        if not valid:
            raise PlcConfigError("plc_workstation_lease_fenced")
        lease["heartbeat_at"] = now
        lease["expires_at"] = now + WEB_SERIAL_ACTIVE_LEASE_SECONDS
        if str(lease.get("in_flight_dispatch_id") or "").startswith("plcweb_"):
            lease["in_flight_deadline_at"] = lease["expires_at"]
        state["lease"] = _plc_workstation_lease_row(lease)

    state = _plc_web_serial_mutate(station_id, None, mutate)
    return _plc_web_serial_record(state.get("lease")) or {}


def plc_web_serial_release_lease(station_id: str, request: PlcWorkstationLeaseHeartbeatRequest) -> dict[str, Any]:
    user_id = str((current_auth_user() or {}).get("id") or "")

    def mutate(state: dict[str, dict[str, Any] | None]) -> None:
        lease = _plc_web_serial_record(state.get("lease"))
        now = int((state.get("clock") or {}).get("now") or time.time())
        if not lease:
            return
        if lease.get("session_id") == request.session_id and int(lease.get("lease_epoch") or -1) == int(request.lease_epoch) and lease.get("owner_user_id") == user_id:
            in_flight_deadline = int(lease.get("in_flight_deadline_at") or 0)
            lease["state"] = "draining" if in_flight_deadline > now else "released"
            lease["heartbeat_at"] = now
            lease["expires_at"] = max(now, in_flight_deadline)
            state["lease"] = _plc_workstation_lease_row(lease)

    state = _plc_web_serial_mutate(station_id, None, mutate)
    return _plc_web_serial_record(state.get("lease")) or {"state": "released"}


def _plc_web_serial_require_active_lease(
    state: dict[str, dict[str, Any] | None],
    session_id: str,
    lease_epoch: int | None = None,
) -> tuple[dict[str, Any], dict[str, Any], int]:
    station = _plc_web_serial_record(state.get("station"))
    lease = _plc_web_serial_record(state.get("lease"))
    now = int((state.get("clock") or {}).get("now") or time.time())
    user_id = str((current_auth_user() or {}).get("id") or "")
    if not station or not lease:
        raise PlcConfigError("plc_workstation_lease_missing")
    valid = (
        lease.get("session_id") == session_id
        and lease.get("owner_user_id") == user_id
        and lease.get("state") == "active"
        and int(lease.get("expires_at") or 0) > now
        and int(lease.get("config_generation") or -1) == int(station.get("config_generation") or 0)
        and lease.get("bundle_version") == WEB_SERIAL_PROTOCOL_VERSION
    )
    if lease_epoch is not None:
        valid = valid and int(lease.get("lease_epoch") or -1) == int(lease_epoch)
    if not valid:
        raise PlcConfigError("plc_workstation_lease_fenced")
    config = migrate_web_serial_config(station.get("config") if isinstance(station.get("config"), dict) else {})
    if not config["enabled"]:
        raise PlcConfigError("plc_workstation_disabled")
    return station, lease, now


def plc_web_serial_diagnostic_plan(
    station_id: str,
    request: PlcWebSerialAttemptRequest,
) -> dict[str, Any]:
    plan: dict[str, Any] = {}
    diagnostic_id = "plcdiag_" + secrets.token_hex(16)
    attempt_token = secrets.token_urlsafe(32)

    def validate(state: dict[str, dict[str, Any] | None]) -> None:
        nonlocal plan
        station, lease, now = _plc_web_serial_require_active_lease(
            state, request.session_id, request.lease_epoch
        )
        if int(station.get("config_generation") or 0) != int(request.config_generation):
            raise PlcConfigError("plc_workstation_generation_changed")
        in_flight_id = str(lease.get("in_flight_dispatch_id") or "")
        in_flight_deadline = int(lease.get("in_flight_deadline_at") or 0)
        if in_flight_id and in_flight_deadline > now:
            raise PlcConfigError("plc_workstation_dispatch_in_flight")
        issued_at_ms = int(time.time() * 1000)
        deadline_at_ms = issued_at_ms + 2000
        deadline_at = int(math.ceil(deadline_at_ms / 1000))
        lease["in_flight_dispatch_id"] = diagnostic_id
        lease["in_flight_deadline_at"] = deadline_at
        lease["diagnostic_token_hash"] = _plc_web_serial_token_hash(attempt_token)
        state["lease"] = _plc_workstation_lease_row(lease)
        plan = {
            "diagnostic_id": diagnostic_id,
            "attempt_token": attempt_token,
            "protocol_version": WEB_SERIAL_PROTOCOL_VERSION,
            "register": "D206",
            "write_value": 6,
            "issued_at": now,
            "deadline_at_ms": deadline_at_ms,
            "execution_window_ms": 2000,
            "ack_timeout_ms": 500,
            "read_timeout_ms": 500,
            "frames": build_web_serial_diagnostic_plan(),
        }

    _plc_web_serial_mutate(station_id, None, validate)
    return plan


def plc_web_serial_confirm_diagnostic(
    station_id: str,
    request: PlcWebSerialDiagnosticConfirmRequest,
) -> dict[str, Any]:
    def validate(state: dict[str, dict[str, Any] | None]) -> None:
        _, lease, now = _plc_web_serial_require_active_lease(
            state, request.session_id, request.lease_epoch
        )
        if lease.get("in_flight_dispatch_id") != request.diagnostic_id:
            raise PlcConfigError("plc_diagnostic_not_in_flight")
        if int(lease.get("in_flight_deadline_at") or 0) <= now:
            raise PlcConfigError("plc_diagnostic_deadline_expired")
        expected_hash = str(lease.get("diagnostic_token_hash") or "")
        if not expected_hash or not hmac.compare_digest(
            expected_hash, _plc_web_serial_token_hash(request.attempt_token)
        ):
            raise PlcConfigError("plc_diagnostic_token_invalid")

    _plc_web_serial_mutate(station_id, None, validate)
    return {"confirmed": True, "diagnostic_id": request.diagnostic_id}


def plc_web_serial_finish_diagnostic(
    station_id: str,
    request: PlcWebSerialDiagnosticReceiptRequest,
) -> dict[str, Any]:
    def mutate(state: dict[str, dict[str, Any] | None]) -> None:
        lease = _plc_web_serial_record(state.get("lease"))
        user_id = str((current_auth_user() or {}).get("id") or "")
        if not lease or not (
            lease.get("session_id") == request.session_id
            and int(lease.get("lease_epoch") or -1) == int(request.lease_epoch)
            and lease.get("owner_user_id") == user_id
            and lease.get("state") in {"active", "draining"}
        ):
            raise PlcConfigError("plc_workstation_lease_fenced")
        if lease.get("in_flight_dispatch_id") != request.diagnostic_id:
            raise PlcConfigError("plc_diagnostic_not_in_flight")
        expected_hash = str(lease.get("diagnostic_token_hash") or "")
        if not expected_hash or not hmac.compare_digest(
            expected_hash, _plc_web_serial_token_hash(request.attempt_token)
        ):
            raise PlcConfigError("plc_diagnostic_token_invalid")
        if request.outcome not in {"success", "failed", "uncertain"}:
            raise PlcConfigError("plc_diagnostic_outcome_invalid")
        lease.pop("in_flight_dispatch_id", None)
        lease.pop("in_flight_deadline_at", None)
        lease.pop("diagnostic_token_hash", None)
        state["lease"] = _plc_workstation_lease_row(lease)

    _plc_web_serial_mutate(station_id, None, mutate)
    return {"released": True, "diagnostic_id": request.diagnostic_id}


def plc_web_serial_begin_camera_detection(
    station_id: str,
    session_id: str,
    camera_request_id: str,
    model_id: str,
    fingerprint: str,
) -> tuple[dict[str, Any], bool]:
    clean_request_id = str(camera_request_id or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9._:-]{8,160}", clean_request_id):
        raise PlcConfigError("invalid_camera_request_id")
    dispatch_id = "plcweb_" + hashlib.sha256(f"{station_id}:{clean_request_id}".encode("utf-8")).hexdigest()[:32]
    created = False

    def mutate(state: dict[str, dict[str, Any] | None]) -> None:
        nonlocal created
        station, lease, now = _plc_web_serial_require_active_lease(state, session_id)
        in_flight_id = str(lease.get("in_flight_dispatch_id") or "")
        in_flight_deadline = int(lease.get("in_flight_deadline_at") or 0)
        if in_flight_id and in_flight_id != dispatch_id and in_flight_deadline > now:
            raise PlcConfigError("plc_workstation_attempt_in_flight")
        if str(lease.get("model_id") or "") != str(model_id or ""):
            raise PlcConfigError("plc_workstation_model_changed")
        existing = _plc_web_serial_record(state.get("dispatch"))
        if existing:
            verify_plc_web_serial_dispatch(
                existing,
                station,
                require_frames=existing.get("status") != "detecting",
                require_current_config=False,
            )
            if existing.get("fingerprint") != fingerprint or existing.get("model_id") != model_id:
                raise PlcConfigError("plc_camera_request_payload_conflict")
            return
        config_snapshot = migrate_web_serial_config(station.get("config") or {})
        record = {
            "dispatch_id": dispatch_id,
            "protocol_version": WEB_SERIAL_PROTOCOL_VERSION,
            "station_id": station_id,
            "detection_request_id": clean_request_id,
            "session_id": session_id,
            "lease_epoch": int(lease["lease_epoch"]),
            "config_generation": int(station.get("config_generation") or 0),
            "config_snapshot": config_snapshot,
            "config_fingerprint": web_serial_config_fingerprint(config_snapshot),
            "model_id": model_id,
            "fingerprint": fingerprint,
            "source": "camera",
            "status": "detecting",
            "passed": False,
            "frames": [],
            "deadline_at": 0,
            "created_at": now,
            "updated_at": now,
            "result": None,
            "evidence_source": "browser_workstation",
        }
        state["dispatch"] = _plc_web_serial_dispatch_row(record)
        lease["in_flight_dispatch_id"] = dispatch_id
        lease["in_flight_deadline_at"] = int(lease.get("expires_at") or now)
        state["lease"] = _plc_workstation_lease_row(lease)
        created = True

    state = _plc_web_serial_mutate(station_id, dispatch_id, mutate)
    record = _plc_web_serial_record(state.get("dispatch"))
    if not record:
        raise PlcConfigError("plc_dispatch_persist_failed")
    return record, created


def plc_web_serial_finish_camera_detection(
    station_id: str,
    dispatch_id: str,
    session_id: str,
    result: dict[str, Any] | None,
    error: str = "",
) -> dict[str, Any]:
    def mutate(state: dict[str, dict[str, Any] | None]) -> None:
        station, _, now = _plc_web_serial_require_active_lease(state, session_id)
        record = _plc_web_serial_record(state.get("dispatch"))
        if not record or record.get("session_id") != session_id:
            raise PlcConfigError("plc_dispatch_not_owned")
        verify_plc_web_serial_dispatch(record, station, require_frames=False)
        if record.get("status") != "detecting":
            return
        if error or not isinstance(result, dict):
            record["status"] = "detection_failed"
            record["error_code"] = str(error or "detection_failed")[:120]
            if lease := _plc_web_serial_record(state.get("lease")):
                if lease.get("in_flight_dispatch_id") == dispatch_id:
                    lease.pop("in_flight_dispatch_id", None)
                    lease.pop("in_flight_deadline_at", None)
                    state["lease"] = _plc_workstation_lease_row(lease)
        else:
            passed = bool(result.get("passed"))
            frames = build_web_serial_plan(record.get("config_snapshot") or {}, passed)
            record.update(
                {
                    "status": "planned",
                    "passed": passed,
                    "frames": frames,
                    "targets": [item["target"] for item in frames],
                    "result": copy.deepcopy(result),
                }
            )
        record["updated_at"] = now
        state["dispatch"] = _plc_web_serial_dispatch_row(record)

    state = _plc_web_serial_mutate(station_id, dispatch_id, mutate)
    record = _plc_web_serial_record(state.get("dispatch"))
    if not record:
        raise PlcConfigError("plc_dispatch_not_found")
    return record


def plc_web_serial_dispatch_public(record: dict[str, Any]) -> dict[str, Any]:
    return {
        "dispatch_id": record["dispatch_id"],
        "source": "camera",
        "passed": bool(record.get("passed")),
        "enabled": True,
        "attempted": record.get("status") not in {"detecting", "planned"},
        "protocol": PLC_PROTOCOL_ID,
        "transport_mode": "web_serial",
        "protocol_version": str(record.get("protocol_version") or LEGACY_WEB_SERIAL_PROTOCOL_VERSION),
        "status": record.get("status") or "planned",
        "outcome": record.get("outcome") or "",
        "targets": list(record.get("targets") or []),
        "operations": copy.deepcopy(record.get("operations") or []),
        "evidence_source": "browser_workstation",
        "config_generation": int(record.get("config_generation") or 0),
        "lease_epoch": int(record.get("lease_epoch") or 0),
        "updated_at": int(record.get("updated_at") or 0),
    }


def verify_plc_web_serial_dispatch(
    record: dict[str, Any],
    station: dict[str, Any],
    *,
    require_frames: bool = True,
    require_current_config: bool = True,
) -> None:
    station_id = str(station.get("id") or "")
    request_id = str(record.get("detection_request_id") or "")
    expected_id = "plcweb_" + hashlib.sha256(f"{station_id}:{request_id}".encode("utf-8")).hexdigest()[:32]
    if record.get("dispatch_id") != expected_id or record.get("station_id") != station_id:
        raise PlcConfigError("plc_dispatch_identity_invalid")
    if record.get("source") != "camera" or record.get("evidence_source") != "browser_workstation":
        raise PlcConfigError("plc_dispatch_source_invalid")
    if not re.fullmatch(r"[A-Za-z0-9._:-]{8,160}", request_id):
        raise PlcConfigError("plc_dispatch_request_id_invalid")
    if require_current_config and int(record.get("config_generation") or -1) != int(station.get("config_generation") or 0):
        raise PlcConfigError("plc_dispatch_generation_invalid")
    snapshot = record.get("config_snapshot")
    if not isinstance(snapshot, dict):
        raise PlcConfigError("plc_dispatch_config_snapshot_missing")
    protocol_version = str(record.get("protocol_version") or LEGACY_WEB_SERIAL_PROTOCOL_VERSION)
    if protocol_version == WEB_SERIAL_PROTOCOL_VERSION:
        config = normalize_web_serial_config(snapshot)
        config_fingerprint = web_serial_config_fingerprint(config)
        expected_frames_builder = build_web_serial_plan
    elif protocol_version == LEGACY_WEB_SERIAL_PROTOCOL_VERSION:
        config = normalize_legacy_web_serial_config(snapshot)
        config_fingerprint = legacy_web_serial_config_fingerprint(config)
        expected_frames_builder = build_legacy_web_serial_plan
    else:
        raise PlcConfigError("plc_dispatch_protocol_version_invalid")
    if not hmac.compare_digest(str(record.get("config_fingerprint") or ""), config_fingerprint):
        raise PlcConfigError("plc_dispatch_config_fingerprint_invalid")
    if require_current_config:
        if protocol_version != WEB_SERIAL_PROTOCOL_VERSION:
            raise PlcConfigError("plc_dispatch_protocol_obsolete")
        current = migrate_web_serial_config(station.get("config") if isinstance(station.get("config"), dict) else {})
        if not hmac.compare_digest(web_serial_config_fingerprint(current), web_serial_config_fingerprint(config)):
            raise PlcConfigError("plc_dispatch_config_changed")
    if require_frames:
        if type(record.get("passed")) is not bool:
            raise PlcConfigError("plc_dispatch_passed_invalid")
        result = record.get("result")
        if not isinstance(result, dict) or type(result.get("passed")) is not bool or result.get("passed") is not record.get("passed"):
            raise PlcConfigError("plc_dispatch_result_mismatch")
        expected_frames = expected_frames_builder(config, bool(record.get("passed")))
        actual_frames = record.get("frames")
        if not isinstance(actual_frames, list) or json.dumps(actual_frames, sort_keys=True, separators=(",", ":")) != json.dumps(expected_frames, sort_keys=True, separators=(",", ":")):
            raise PlcConfigError("plc_dispatch_frames_invalid")
        if record.get("targets") != [item["target"] for item in expected_frames]:
            raise PlcConfigError("plc_dispatch_targets_invalid")


def plc_web_serial_declare_attempt(
    station_id: str,
    dispatch_id: str,
    request: PlcWebSerialAttemptRequest,
) -> dict[str, Any]:
    attempt_token = secrets.token_urlsafe(32)

    def mutate(state: dict[str, dict[str, Any] | None]) -> None:
        station, lease, now = _plc_web_serial_require_active_lease(state, request.session_id, request.lease_epoch)
        record = _plc_web_serial_record(state.get("dispatch"))
        if not record or record.get("station_id") != station_id:
            raise PlcConfigError("plc_dispatch_not_found")
        verify_plc_web_serial_dispatch(record, station)
        if record.get("status") != "planned":
            raise PlcConfigError("plc_dispatch_already_declared")
        in_flight_id = str(lease.get("in_flight_dispatch_id") or "")
        in_flight_deadline = int(lease.get("in_flight_deadline_at") or 0)
        if in_flight_id and in_flight_id != dispatch_id and in_flight_deadline > now:
            raise PlcConfigError("plc_workstation_attempt_in_flight")
        if int(request.config_generation) != int(station.get("config_generation") or 0) or int(record.get("config_generation") or -1) != int(request.config_generation):
            raise PlcConfigError("plc_workstation_generation_changed")
        if record.get("session_id") != request.session_id or int(record.get("lease_epoch") or -1) != int(lease.get("lease_epoch") or -2):
            raise PlcConfigError("plc_dispatch_not_owned")
        record["status"] = "browser_attempt_declared"
        record["attempt_token_hash"] = _plc_web_serial_token_hash(attempt_token)
        record["deadline_at"] = now + max(1, int(math.ceil(WEB_SERIAL_PLAN_DEADLINE_SECONDS)))
        record["updated_at"] = now
        state["dispatch"] = _plc_web_serial_dispatch_row(record)
        lease["in_flight_dispatch_id"] = dispatch_id
        lease["in_flight_deadline_at"] = record["deadline_at"]
        state["lease"] = _plc_workstation_lease_row(lease)

    state = _plc_web_serial_mutate(station_id, dispatch_id, mutate)
    record = _plc_web_serial_record(state.get("dispatch"))
    if not record:
        raise PlcConfigError("plc_dispatch_not_found")
    return {
        **plc_web_serial_dispatch_public(record),
        "attempt_token": attempt_token,
        "deadline_at": int(record["deadline_at"]),
        "execution_window_ms": int(WEB_SERIAL_PLAN_DEADLINE_SECONDS * 1000),
        "ack_timeout_ms": int((station_config := migrate_web_serial_config((_plc_web_serial_record(state.get("station")) or {}).get("config") or {}))["ack_timeout_ms"]),
        "frames": copy.deepcopy(record.get("frames") or []),
        "serial_options": {
            "baudRate": station_config["baudrate"],
            "dataBits": station_config["data_bits"],
            "stopBits": station_config["stop_bits"],
            "parity": "even",
            "flowControl": "none",
        },
    }


def _plc_web_serial_receipt_outcome(frames: list[dict[str, Any]], operations: list[dict[str, Any]]) -> str:
    allowed_statuses = {"acknowledged", "nak", "timeout", "serial_error", "unexpected_response"}
    if not operations:
        return "uncertain"
    if len(operations) > len(frames):
        raise PlcConfigError("plc_receipt_has_extra_operations")
    normalized: list[dict[str, Any]] = []
    for index, operation in enumerate(operations):
        if not isinstance(operation, dict):
            raise PlcConfigError("plc_receipt_operation_invalid")
        expected = frames[index]
        status = str(operation.get("status") or "")
        response_hex = str(operation.get("response_hex") or "").upper()
        if status not in allowed_statuses:
            raise PlcConfigError("plc_receipt_status_invalid")
        if operation.get("target") != expected.get("target") or operation.get("frame_sha256") != expected.get("frame_sha256"):
            raise PlcConfigError("plc_receipt_frame_mismatch")
        if status == "acknowledged" and response_hex != "06":
            raise PlcConfigError("plc_receipt_ack_evidence_invalid")
        if status == "nak" and response_hex != "15":
            raise PlcConfigError("plc_receipt_nak_evidence_invalid")
        if status in {"timeout", "serial_error"} and response_hex:
            raise PlcConfigError("plc_receipt_empty_response_required")
        normalized.append({**operation, "response_hex": response_hex})
    operations[:] = normalized
    first = operations[0]["status"]
    if len(operations) > 1 and first != "acknowledged":
        raise PlcConfigError("plc_receipt_y_without_d_ack")
    if first == "nak":
        return "rejected"
    if first != "acknowledged":
        return "uncertain"
    if len(frames) == 1:
        return "acknowledged"
    if len(operations) < len(frames):
        return "uncertain"
    second = operations[1]["status"]
    if second == "acknowledged":
        return "acknowledged"
    if second == "nak":
        return "partial_success"
    return "uncertain"


def plc_web_serial_record_receipt(
    station_id: str,
    dispatch_id: str,
    request: PlcWebSerialReceiptRequest,
) -> dict[str, Any]:
    def mutate(state: dict[str, dict[str, Any] | None]) -> None:
        record = _plc_web_serial_record(state.get("dispatch"))
        if not record:
            raise PlcConfigError("plc_dispatch_not_receivable")
        station = _plc_web_serial_record(state.get("station"))
        if not station:
            raise PlcConfigError("plc_workstation_not_found")
        verify_plc_web_serial_dispatch(record, station, require_current_config=False)
        if not hmac.compare_digest(str(record.get("attempt_token_hash") or ""), _plc_web_serial_token_hash(request.attempt_token)):
            raise PlcConfigError("plc_attempt_token_invalid")
        if record.get("session_id") != request.session_id or int(record.get("lease_epoch") or -1) != int(request.lease_epoch):
            raise PlcConfigError("plc_dispatch_not_owned")
        operations = [item.model_dump() for item in request.operations]
        outcome = _plc_web_serial_receipt_outcome(list(record.get("frames") or []), operations)
        declared_outcome = str(request.outcome or "")
        if declared_outcome and declared_outcome != outcome:
            raise PlcConfigError("plc_receipt_outcome_mismatch")
        receipt_fingerprint = hashlib.sha256(
            json.dumps(
                {"outcome": outcome, "operations": operations},
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        if record.get("status") in {"acknowledged", "rejected", "partial_success", "uncertain"}:
            if hmac.compare_digest(str(record.get("receipt_fingerprint") or ""), receipt_fingerprint):
                return
            raise PlcConfigError("plc_receipt_conflict")
        if record.get("status") != "browser_attempt_declared":
            raise PlcConfigError("plc_dispatch_not_receivable")
        now = int((state.get("clock") or {}).get("now") or time.time())
        record["operations"] = operations
        record["outcome"] = outcome
        record["status"] = outcome
        record["receipt_fingerprint"] = receipt_fingerprint
        record["evidence_source"] = "browser_workstation"
        record["updated_at"] = now
        state["dispatch"] = _plc_web_serial_dispatch_row(record)
        lease = _plc_web_serial_record(state.get("lease"))
        if lease and lease.get("in_flight_dispatch_id") == dispatch_id:
            lease.pop("in_flight_dispatch_id", None)
            lease.pop("in_flight_deadline_at", None)
            if lease.get("state") == "draining":
                lease["state"] = "released"
                lease["expires_at"] = now
            state["lease"] = _plc_workstation_lease_row(lease)

    state = _plc_web_serial_mutate(station_id, dispatch_id, mutate)
    record = _plc_web_serial_record(state.get("dispatch"))
    if not record:
        raise PlcConfigError("plc_dispatch_not_found")
    return plc_web_serial_dispatch_public(record)


def _read_config_file() -> dict[str, Any] | None:
    """Read config.json, retrying briefly on transient partial/empty reads.

    Returns the parsed dict, an empty dict when the file legitimately does not
    exist, or ``None`` when the file is present but could not be parsed cleanly
    (e.g. mid-write). Callers must NOT treat ``None`` as "no accessories" — doing
    so would silently drop every persisted record whenever a concurrent writer
    is in the middle of replacing the file.
    """
    for attempt in range(6):
        try:
            text = CONFIG_PATH.read_text(encoding="utf-8")
        except FileNotFoundError:
            return {}
        except OSError:
            time.sleep(0.05)
            continue
        if not text.strip():
            # Empty/zero-byte read can happen during a non-atomic legacy write;
            # give the writer a moment and retry rather than wiping state.
            time.sleep(0.05)
            continue
        try:
            return json.loads(text)
        except json.JSONDecodeError:
            time.sleep(0.05)
    return None


def load_config() -> dict[str, Any]:
    ensure_dirs()
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        current = config_from_rows(repository.fetch_all("app_config"), repository.fetch_all("accessories"))
    else:
        current = _read_config_file()
        if current is None:
            # The primary file exists but is unreadable right now. Fall back to the
            # last-good snapshot instead of DEFAULT_CONFIG so we never report that
            # user accessories/models suddenly vanished due to a write race.
            try:
                backup_text = CONFIG_BACKUP_PATH.read_text(encoding="utf-8")
                current = json.loads(backup_text)
            except (FileNotFoundError, OSError, json.JSONDecodeError):
                current = {}
    merged = json.loads(json.dumps(DEFAULT_CONFIG))
    for key, value in current.items():
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key].update(value)
        else:
            merged[key] = value
    return public_path_sanitized(merged)


def save_config(config: dict[str, Any]) -> None:
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        now = int(time.time())
        with _config_io_lock:
            repository.replace_app_config_preserving_keys(
                app_config_rows(config, updated_at=now),
                PLC_PROTECTED_CONFIG_KEYS,
                additional_tables={"accessories": accessory_rows(config)},
            )
        return
    with _config_io_lock:
        saved = copy.deepcopy(config)
        if not _plc_namespace_write_authorized.get():
            current = _read_config_file()
            current = current if isinstance(current, dict) else {}
            for key in PLC_PROTECTED_CONFIG_KEYS:
                if key in current:
                    saved[key] = copy.deepcopy(current[key])
                else:
                    saved.pop(key, None)
        payload = json.dumps(saved, indent=2)
        tmp_path = CONFIG_PATH.with_name(f"{CONFIG_PATH.name}.tmp.{uuid.uuid4().hex}")
        try:
            tmp_path.write_text(payload, encoding="utf-8")
            os.replace(tmp_path, CONFIG_PATH)
        finally:
            try:
                tmp_path.unlink()
            except OSError:
                pass
        # Best-effort last-good snapshot for disaster recovery.
        try:
            backup_tmp = CONFIG_BACKUP_PATH.with_name(f"{CONFIG_BACKUP_PATH.name}.tmp.{uuid.uuid4().hex}")
            backup_tmp.write_text(payload, encoding="utf-8")
            os.replace(backup_tmp, CONFIG_BACKUP_PATH)
        except OSError:
            pass


def save_app_config(config: dict[str, Any]) -> None:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        with _config_io_lock:
            repository.replace_app_config_preserving_keys(
                app_config_rows(config, updated_at=int(time.time())),
                PLC_PROTECTED_CONFIG_KEYS,
            )
        return
    save_config(config)


# Presentation-only window. Durable idempotency/state authority is never trimmed by this value.
PLC_DISPATCH_AUDIT_LIMIT = 100
PLC_QUEUE_WAIT_SECONDS = 2.0
PLC_WORKER_TOTAL_TIMEOUT_SECONDS = MAX_DISPATCH_WALL_SECONDS + 2.0
_plc_transport_factory: Callable[[dict[str, Any]], Any] | None = None
_plc_io_executor = ThreadPoolExecutor(max_workers=2, thread_name_prefix="plc-io")
_plc_dispatch_slots = threading.BoundedSemaphore(1)
_plc_write_pending = threading.Event()
_plc_active_attempts: dict[str, dict[str, Any]] = {}
_plc_dispatch_runtime: dict[str, dict[str, Any]] = {}
_PLC_RUNTIME_LIMIT = 200
PLC_IO_OWNER_HEARTBEAT_SECONDS = 1.0
PLC_IO_OWNER_LEASE_SECONDS = 5.0
PLC_IO_OWNER_TAKEOVER_QUARANTINE_SECONDS = PLC_WORKER_TOTAL_TIMEOUT_SECONDS + 2.0
PLC_CAPTURE_POLL_SECONDS = 0.2
PLC_CAPTURE_EVENT_TTL_SECONDS = 1.0
PLC_CAPTURE_PROCESSING_TTL_SECONDS = max(180.0, PLC_WORKER_TOTAL_TIMEOUT_SECONDS + 60.0)
_plc_process_owner_id = f"{socket.gethostname()}:{os.getpid()}:{uuid.uuid4().hex}"
_plc_owner_heartbeat_lock = threading.Lock()
_plc_owner_heartbeat_thread: threading.Thread | None = None


def plc_pg_coordination_available() -> bool:
    repository = runtime_postgres_repository_or_none()
    # Generic namespace CAS is not enough to fence physical I/O across hosts.
    # Production stays closed until the repository supplies a DB-clock, atomic
    # owner+attempt transition primitive reviewed against the real deployment.
    return repository is not None and callable(
        getattr(repository, "mutate_plc_fenced_attempt_with_db_time", None)
    )


def plc_profile_fingerprint(settings: dict[str, Any], *, include_read: bool) -> str:
    fields = [
        "protocol", "checksum_mode", "serial_port", "baudrate", "parity",
        "data_bits", "stop_bits", "result_register", "output_control_point",
    ]
    if include_read:
        fields.extend(["capture_input_register", "capture_trigger_value"])
    material = {field: settings.get(field) for field in fields}
    return hashlib.sha256(_plc_canonical(material).encode("ascii")).hexdigest()


def plc_device_profile_verified(settings: dict[str, Any] | None = None) -> bool:
    if _plc_transport_factory is not None:
        return True
    expected = str(os.getenv("VANTALINE_PLC_DEVICE_PROFILE_FINGERPRINT") or "").strip().lower()
    return bool(settings is not None and expected and hmac.compare_digest(expected, plc_profile_fingerprint(settings, include_read=False)))


def plc_read_profile_verified(settings: dict[str, Any] | None = None) -> bool:
    if _plc_transport_factory is not None:
        return True
    expected = str(os.getenv("VANTALINE_PLC_READ_PROFILE_FINGERPRINT") or "").strip().lower()
    return bool(settings is not None and expected and hmac.compare_digest(expected, plc_profile_fingerprint(settings, include_read=True)))


def plc_serial_dependency_available() -> bool:
    if _plc_transport_factory is not None and _request_user.get() is not None:
        return True
    try:
        import serial  # type: ignore[import-not-found]  # noqa: F401
    except ImportError:
        return False
    return True


def plc_activation_errors(settings: dict[str, Any]) -> list[dict[str, str]]:
    if not settings.get("enabled"):
        return []
    errors: list[dict[str, str]] = []
    if not plc_pg_coordination_available():
        errors.append({"code": "plc_pg_coordination_unavailable", "message": "PostgreSQL PLC 多实例协调不可用"})
    if not plc_serial_dependency_available():
        errors.append({"code": "plc_serial_dependency_missing", "message": "生产部署未安装锁定版本的 pyserial"})
    if not plc_device_profile_verified(settings):
        errors.append({"code": "plc_device_profile_unverified", "message": "现场 PLC 型号、地址范围和写协议尚未验证"})
    if settings.get("capture_trigger_enabled") and not plc_read_profile_verified(settings):
        errors.append({"code": "plc_read_profile_unverified", "message": "现场 PLC 输入寄存器读取帧和字节序尚未验证"})
    return errors


def mutate_plc_runtime_coordination(mutator: Callable[[dict[str, Any]], None]) -> dict[str, Any]:
    """Mutate only the small PLC runtime row; never rewrite the dispatch audit list on heartbeats."""
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        values = repository.mutate_app_config_namespace(
            (PLC_RUNTIME_COORDINATION_KEY,),
            lambda rows: _mutate_plc_runtime_rows(rows, mutator),
            updated_at=int(time.time()),
        )
        value = values.get(PLC_RUNTIME_COORDINATION_KEY)
        return copy.deepcopy(value) if isinstance(value, dict) else {}

    result: dict[str, Any] = {}
    def mutate(config: dict[str, Any]) -> None:
        nonlocal result
        current = config.get(PLC_RUNTIME_COORDINATION_KEY)
        state = copy.deepcopy(current) if isinstance(current, dict) else {}
        mutator(state)
        config[PLC_RUNTIME_COORDINATION_KEY] = state
        result = copy.deepcopy(state)
    mutate_app_config_atomically(mutate)
    return result


def plc_completed_capture_receipt(trigger_id: str) -> dict[str, Any] | None:
    receipts = load_config().get(PLC_CAPTURE_RESULTS_KEY)
    receipt = receipts.get(trigger_id) if isinstance(receipts, dict) else None
    return copy.deepcopy(receipt) if isinstance(receipt, dict) else None


def _mutate_plc_runtime_rows(rows: dict[str, Any], mutator: Callable[[dict[str, Any]], None]) -> None:
    current = rows.get(PLC_RUNTIME_COORDINATION_KEY)
    state = copy.deepcopy(current) if isinstance(current, dict) else {}
    mutator(state)
    rows[PLC_RUNTIME_COORDINATION_KEY] = state


def plc_claim_or_renew_io_owner() -> dict[str, Any] | None:
    now = time.time()
    claimed: dict[str, Any] | None = None
    def mutate(state: dict[str, Any]) -> None:
        nonlocal claimed
        owner = state.get("io_owner") if isinstance(state.get("io_owner"), dict) else {}
        owner_id = str(owner.get("owner_id") or "")
        expires_at = float(owner.get("expires_at") or 0.0)
        quarantine_until = float(owner.get("quarantine_until") or 0.0)
        if owner_id == _plc_process_owner_id:
            epoch = int(owner.get("epoch") or 1)
        elif expires_at <= now and quarantine_until <= now:
            epoch = int(owner.get("epoch") or 0) + 1
        else:
            return
        claimed = {
            "owner_id": _plc_process_owner_id,
            "epoch": epoch,
            "heartbeat_at": now,
            "expires_at": now + PLC_IO_OWNER_LEASE_SECONDS,
            "quarantine_until": now + PLC_IO_OWNER_LEASE_SECONDS + PLC_IO_OWNER_TAKEOVER_QUARANTINE_SECONDS,
        }
        state["io_owner"] = copy.deepcopy(claimed)
    mutate_plc_runtime_coordination(mutate)
    if claimed is not None and runtime_postgres_repository_or_none() is not None:
        plc_start_owner_heartbeat(int(claimed["epoch"]))
    return claimed


def plc_start_owner_heartbeat(epoch: int) -> None:
    global _plc_owner_heartbeat_thread
    with _plc_owner_heartbeat_lock:
        if _plc_owner_heartbeat_thread is not None and _plc_owner_heartbeat_thread.is_alive():
            return
        def heartbeat() -> None:
            while True:
                time.sleep(PLC_IO_OWNER_HEARTBEAT_SECONDS)
                try:
                    if runtime_postgres_repository_or_none() is None:
                        return
                    current = load_config()
                    raw = raw_plc_namespace(current)
                    if not isinstance(raw, dict) or not bool(raw.get("enabled")):
                        return
                    renewed = plc_claim_or_renew_io_owner()
                    if renewed is None or int(renewed.get("epoch") or 0) != epoch:
                        return
                except Exception:
                    return
        _plc_owner_heartbeat_thread = threading.Thread(
            target=heartbeat,
            name="plc-io-owner-heartbeat",
            daemon=True,
        )
        _plc_owner_heartbeat_thread.start()


def plc_current_process_owns_io(epoch: int | None = None) -> bool:
    current = load_config().get(PLC_RUNTIME_COORDINATION_KEY)
    owner = current.get("io_owner") if isinstance(current, dict) and isinstance(current.get("io_owner"), dict) else {}
    return bool(
        owner.get("owner_id") == _plc_process_owner_id
        and float(owner.get("expires_at") or 0.0) > time.time()
        and (epoch is None or int(owner.get("epoch") or 0) == epoch)
    )


def _plc_capture_runtime(state: dict[str, Any]) -> dict[str, Any]:
    capture = state.get("capture")
    if not isinstance(capture, dict):
        capture = {"sequence": 0, "armed": False, "events": []}
        state["capture"] = capture
    if not isinstance(capture.get("events"), list):
        capture["events"] = []
    return capture


def _plc_expire_capture_state(capture: dict[str, Any], now: float) -> None:
    session = capture.get("session") if isinstance(capture.get("session"), dict) else None
    if session is not None and float(session.get("expires_at") or 0.0) <= now:
        capture.pop("session", None)
    events = [dict(item) for item in capture.get("events", []) if isinstance(item, dict)]
    for event in events:
        status = str(event.get("status") or "")
        if status == "claimed":
            deadline = float(event.get("submission_expires_at") or 0.0)
        elif status == "processing":
            deadline = float(event.get("processing_expires_at") or 0.0)
        elif status == "dispatching":
            deadline = float(event.get("dispatch_expires_at") or 0.0)
        else:
            deadline = float(event.get("expires_at") or 0.0)
        if status in {"pending", "claimed", "processing", "dispatching"} and deadline <= now:
            event["status"] = "expired"
            event["finished_at"] = now
            active_session = capture.get("session") if isinstance(capture.get("session"), dict) else None
            if active_session is not None and active_session.get("session_id") == event.get("session_id"):
                active_session["busy"] = False
    capture["events"] = events[-100:]


def plc_claim_capture_session(user_id: str, model_id: str) -> dict[str, Any]:
    now = time.time()
    claimed: dict[str, Any] = {}
    generation = int(load_config().get(PLC_CONTROL_GENERATION_KEY) or 0)
    def mutate(state: dict[str, Any]) -> None:
        nonlocal claimed
        capture = _plc_capture_runtime(state)
        _plc_expire_capture_state(capture, now)
        current = capture.get("session") if isinstance(capture.get("session"), dict) else None
        if current is not None:
            raise PlcConfigError("plc_capture_session_in_use")
        session_id = uuid.uuid4().hex
        claimed = {
            "session_id": session_id,
            "user_id": user_id,
            "model_id": model_id,
            "generation": generation,
            "busy": False,
            "heartbeat_at": now,
            "expires_at": now + 6.0,
        }
        capture["session"] = copy.deepcopy(claimed)
    mutate_plc_runtime_coordination(mutate)
    return claimed


def plc_heartbeat_capture_session(session_id: str, user_id: str) -> dict[str, Any]:
    now = time.time()
    generation = int(load_config().get(PLC_CONTROL_GENERATION_KEY) or 0)
    renewed: dict[str, Any] = {}
    def mutate(state: dict[str, Any]) -> None:
        nonlocal renewed
        capture = _plc_capture_runtime(state)
        _plc_expire_capture_state(capture, now)
        session = capture.get("session") if isinstance(capture.get("session"), dict) else None
        if session is None or session.get("session_id") != session_id or session.get("user_id") != user_id:
            raise PlcConfigError("plc_capture_session_not_owned")
        if int(session.get("generation") or -1) != generation:
            raise PlcConfigError("plc_capture_session_generation_changed")
        session["heartbeat_at"] = now
        session["expires_at"] = now + 6.0
        renewed = copy.deepcopy(session)
    mutate_plc_runtime_coordination(mutate)
    return renewed


def plc_release_capture_session(session_id: str, user_id: str) -> None:
    def mutate(state: dict[str, Any]) -> None:
        capture = _plc_capture_runtime(state)
        session = capture.get("session") if isinstance(capture.get("session"), dict) else None
        if session is not None and session.get("session_id") == session_id and session.get("user_id") == user_id:
            capture.pop("session", None)
    mutate_plc_runtime_coordination(mutate)


def plc_capture_disarm(reason: str) -> None:
    def mutate(state: dict[str, Any]) -> None:
        capture = _plc_capture_runtime(state)
        capture["armed"] = False
        capture["last_value"] = None
        capture["disarmed_reason"] = reason
        capture["updated_at"] = time.time()
    mutate_plc_runtime_coordination(mutate)


def plc_apply_capture_observation(value: int, *, generation: int, owner_epoch: int, trigger_value: int) -> dict[str, Any] | None:
    """Persist one read observation and atomically create at most one edge event."""
    now = time.time()
    created: dict[str, Any] | None = None
    def mutate(state: dict[str, Any]) -> None:
        nonlocal created
        capture = _plc_capture_runtime(state)
        _plc_expire_capture_state(capture, now)
        binding_changed = (
            int(capture.get("generation") or -1) != generation
            or int(capture.get("owner_epoch") or -1) != owner_epoch
        )
        if binding_changed:
            capture["generation"] = generation
            capture["owner_epoch"] = owner_epoch
            capture["armed"] = False
            capture["last_value"] = None
        armed = bool(capture.get("armed"))
        if value != trigger_value:
            capture["armed"] = True
        elif armed:
            sequence = int(capture.get("sequence") or 0) + 1
            capture["sequence"] = sequence
            trigger_id = hashlib.sha256(f"{generation}:{owner_epoch}:{sequence}".encode("ascii")).hexdigest()[:24]
            session = capture.get("session") if isinstance(capture.get("session"), dict) else None
            session_valid = bool(
                session
                and float(session.get("expires_at") or 0.0) > now
                and int(session.get("generation") or -1) == generation
                and not bool(session.get("busy"))
            )
            created = {
                "trigger_id": trigger_id,
                "generation": generation,
                "owner_epoch": owner_epoch,
                "sequence": sequence,
                "value": value,
                "created_at": now,
                "expires_at": now + PLC_CAPTURE_EVENT_TTL_SECONDS,
                "status": "pending" if session_valid else "missed",
                "reason": "" if session_valid else "no_ready_capture_session",
                "session_id": str(session.get("session_id") or "") if session_valid else "",
                "user_id": str(session.get("user_id") or "") if session_valid else "",
                "model_id": str(session.get("model_id") or "") if session_valid else "",
            }
            capture["events"].append(copy.deepcopy(created))
            capture["armed"] = False
        capture["last_value"] = value
        capture["last_read_at"] = now
        capture["disarmed_reason"] = ""
    mutate_plc_runtime_coordination(mutate)
    return created


def plc_claim_next_capture_event(session_id: str, user_id: str) -> dict[str, Any] | None:
    now = time.time()
    claimed: dict[str, Any] | None = None
    def mutate(state: dict[str, Any]) -> None:
        nonlocal claimed
        capture = _plc_capture_runtime(state)
        _plc_expire_capture_state(capture, now)
        session = capture.get("session") if isinstance(capture.get("session"), dict) else None
        if session is None or session.get("session_id") != session_id or session.get("user_id") != user_id:
            raise PlcConfigError("plc_capture_session_not_owned")
        if bool(session.get("busy")):
            return
        for event in capture.get("events", []):
            if not isinstance(event, dict) or event.get("status") != "pending":
                continue
            if event.get("session_id") != session_id or event.get("user_id") != user_id:
                continue
            event["status"] = "claimed"
            event["claimed_at"] = now
            event["submission_expires_at"] = now + 10.0
            session["busy"] = True
            claimed = copy.deepcopy(event)
            return
    mutate_plc_runtime_coordination(mutate)
    return claimed


def plc_begin_triggered_analysis(trigger_id: str, session_id: str, user_id: str, model_id: str, fingerprint: str) -> dict[str, Any] | None:
    now = time.time()
    durable_receipt = plc_completed_capture_receipt(trigger_id)
    if durable_receipt is not None:
        if (
            durable_receipt.get("session_id") != session_id
            or durable_receipt.get("user_id") != user_id
            or durable_receipt.get("model_id") != model_id
        ):
            raise PlcConfigError("plc_capture_event_not_owned")
        if durable_receipt.get("fingerprint") != fingerprint:
            raise PlcConfigError("plc_capture_event_payload_conflict")
        stored_result = durable_receipt.get("result")
        return copy.deepcopy(stored_result) if isinstance(stored_result, dict) else {}
    duplicate_result: dict[str, Any] | None = None
    def mutate(state: dict[str, Any]) -> None:
        nonlocal duplicate_result
        capture = _plc_capture_runtime(state)
        _plc_expire_capture_state(capture, now)
        session = capture.get("session") if isinstance(capture.get("session"), dict) else None
        if session is None or session.get("session_id") != session_id or session.get("user_id") != user_id:
            raise PlcConfigError("plc_capture_session_not_owned")
        event = next((item for item in capture.get("events", []) if isinstance(item, dict) and item.get("trigger_id") == trigger_id), None)
        if event is None or event.get("session_id") != session_id or event.get("user_id") != user_id:
            raise PlcConfigError("plc_capture_event_not_owned")
        if str(event.get("model_id") or "") != model_id:
            raise PlcConfigError("plc_capture_event_model_mismatch")
        if event.get("status") == "completed":
            if event.get("fingerprint") != fingerprint:
                raise PlcConfigError("plc_capture_event_payload_conflict")
            duplicate_result = copy.deepcopy(event.get("result")) if isinstance(event.get("result"), dict) else {}
            return
        if event.get("status") != "claimed" or float(event.get("submission_expires_at") or 0.0) <= now:
            raise PlcConfigError("plc_capture_event_not_claimable")
        event["status"] = "processing"
        event["fingerprint"] = fingerprint
        event["processing_at"] = now
        event["processing_expires_at"] = now + PLC_CAPTURE_PROCESSING_TTL_SECONDS
    mutate_plc_runtime_coordination(mutate)
    return duplicate_result


def plc_prepare_triggered_dispatch(trigger_id: str, session_id: str, user_id: str) -> None:
    """Atomically prove a fresh session/event immediately before any PLC dispatch."""
    now = time.time()
    generation = int(load_config().get(PLC_CONTROL_GENERATION_KEY) or 0)
    def mutate(state: dict[str, Any]) -> None:
        capture = _plc_capture_runtime(state)
        _plc_expire_capture_state(capture, now)
        session = capture.get("session") if isinstance(capture.get("session"), dict) else None
        event = next(
            (item for item in capture.get("events", []) if isinstance(item, dict) and item.get("trigger_id") == trigger_id),
            None,
        )
        if (
            session is None
            or session.get("session_id") != session_id
            or session.get("user_id") != user_id
            or float(session.get("expires_at") or 0.0) <= now
        ):
            raise PlcConfigError("plc_capture_session_not_owned")
        if (
            event is None
            or event.get("status") != "processing"
            or event.get("session_id") != session_id
            or event.get("user_id") != user_id
            or int(event.get("generation") or -1) != generation
        ):
            raise PlcConfigError("plc_capture_event_not_dispatchable")
        event["status"] = "dispatching"
        event["dispatching_at"] = now
        event["dispatch_expires_at"] = now + PLC_WORKER_TOTAL_TIMEOUT_SECONDS + 5.0
    mutate_plc_runtime_coordination(mutate)


def plc_finish_triggered_analysis(trigger_id: str, session_id: str, user_id: str, result: dict[str, Any] | None, error: str = "") -> None:
    now = time.time()
    def mutate(config: dict[str, Any]) -> None:
        current_state = config.get(PLC_RUNTIME_COORDINATION_KEY)
        state = copy.deepcopy(current_state) if isinstance(current_state, dict) else {}
        capture = _plc_capture_runtime(state)
        _plc_expire_capture_state(capture, now)
        config[PLC_RUNTIME_COORDINATION_KEY] = state
        session = capture.get("session") if isinstance(capture.get("session"), dict) else None
        event = next((item for item in capture.get("events", []) if isinstance(item, dict) and item.get("trigger_id") == trigger_id), None)
        if event is None or event.get("session_id") != session_id or event.get("user_id") != user_id:
            return
        allowed_statuses = {"processing", "dispatching"} if result is not None else {"claimed", "processing", "dispatching"}
        if event.get("status") not in allowed_statuses:
            return
        event["status"] = "completed" if result is not None else "failed"
        event["finished_at"] = now
        if result is not None:
            event["result"] = copy.deepcopy(result)
            receipt = {
                "trigger_id": trigger_id,
                "session_id": session_id,
                "user_id": user_id,
                "model_id": str(event.get("model_id") or ""),
                "fingerprint": str(event.get("fingerprint") or ""),
                "result": copy.deepcopy(result),
                "completed_at": now,
            }
            current_receipts = config.get(PLC_CAPTURE_RESULTS_KEY)
            receipts = copy.deepcopy(current_receipts) if isinstance(current_receipts, dict) else {}
            existing_receipt = receipts.get(trigger_id)
            if isinstance(existing_receipt, dict) and _plc_canonical(existing_receipt) != _plc_canonical(receipt):
                raise PlcConfigError("plc_capture_result_receipt_conflict")
            receipts[trigger_id] = receipt
            config[PLC_CAPTURE_RESULTS_KEY] = receipts
        else:
            event["error"] = str(error or "analysis_failed")[:240]
        if session is not None and session.get("session_id") == session_id:
            session["busy"] = False
    mutate_app_config_atomically(mutate)


_plc_capture_poller_lock = threading.Lock()
_plc_capture_poller_thread: threading.Thread | None = None
_plc_dispatch_reconciler_lock = threading.Lock()
_plc_dispatch_reconciler_thread: threading.Thread | None = None


def plc_reconcile_pending_dispatches_once() -> dict[str, Any] | None:
    """Let the fenced I/O owner adopt one durable dispatch that provably never wrote."""
    config = load_config()
    try:
        settings = normalize_plc_config(raw_plc_namespace(config))
    except PlcConfigError:
        return None
    if not settings["enabled"] or plc_activation_errors(settings):
        return None
    owner = plc_claim_or_renew_io_owner()
    if owner is None:
        return None
    for raw_record in plc_dispatch_audit_records(config):
        try:
            record = verify_persisted_plc_dispatch(raw_record)
        except PlcDispatchStateConflict:
            continue
        if not plc_dispatch_is_pristine_queue(record):
            continue
        blocker = plc_dispatch_adoption_blocker(
            record,
            settings=settings,
            generation=int(config.get(PLC_CONTROL_GENERATION_KEY) or 0),
        )
        if blocker:
            if blocker == "version_not_adoptable":
                continue
            reason = (
                "plc_dispatch_queue_timeout"
                if blocker in {"deadline_missing", "deadline_expired"}
                else "cancelled_after_config_change"
            )
            return plc_finalize_dispatch(
                str(record.get("dispatch_id") or ""),
                expected_version=int(record.get("state_version") or 0),
                reason=reason,
            )
        result = {
            "request_id": str(record.get("request_id") or ""),
            "passed": bool(record.get("passed")),
        }
        return _run_queued_plc_dispatch(
            result,
            source=str(record.get("source") or ""),
            fingerprint=str(record.get("detection_identity") or ""),
        ).get("plc_sync")
    return None


def start_plc_dispatch_reconciler() -> None:
    global _plc_dispatch_reconciler_thread
    with _plc_dispatch_reconciler_lock:
        if _plc_dispatch_reconciler_thread is not None and _plc_dispatch_reconciler_thread.is_alive():
            return
        def reconcile() -> None:
            while True:
                try:
                    plc_reconcile_pending_dispatches_once()
                except Exception:
                    pass
                time.sleep(PLC_CAPTURE_POLL_SECONDS)
        _plc_dispatch_reconciler_thread = threading.Thread(
            target=reconcile,
            name="plc-dispatch-reconciler",
            daemon=True,
        )
        _plc_dispatch_reconciler_thread.start()


def plc_capture_poll_once() -> dict[str, Any] | None:
    config = load_config()
    generation = int(config.get(PLC_CONTROL_GENERATION_KEY) or 0)
    try:
        settings = normalize_plc_config(raw_plc_namespace(config))
    except PlcConfigError:
        return None
    if not settings["enabled"] or not settings["capture_trigger_enabled"] or plc_activation_errors(settings):
        return None
    owner = plc_claim_or_renew_io_owner()
    if owner is None:
        return None
    owner_epoch = int(owner["epoch"])
    if _plc_write_pending.is_set() or not _plc_dispatch_slots.acquire(blocking=False):
        return None
    try:
        if _plc_write_pending.is_set() or not plc_current_process_owns_io(owner_epoch):
            return None
        read_settings = {**settings, "timeout": min(float(settings["timeout"]), 0.15)}
        value = read_d_register_value(
            read_settings,
            settings["capture_input_register"],
            transport_factory=_plc_transport_factory,
        )
    except Exception as exc:
        plc_capture_disarm(f"read_failed:{type(exc).__name__}")
        return None
    finally:
        _plc_dispatch_slots.release()
    current = load_config()
    if (
        int(current.get(PLC_CONTROL_GENERATION_KEY) or 0) != generation
        or not plc_current_process_owns_io(owner_epoch)
    ):
        plc_capture_disarm("stale_read_discarded")
        return None
    return plc_apply_capture_observation(
        value,
        generation=generation,
        owner_epoch=owner_epoch,
        trigger_value=int(settings["capture_trigger_value"]),
    )


def start_plc_capture_poller() -> None:
    global _plc_capture_poller_thread
    with _plc_capture_poller_lock:
        if _plc_capture_poller_thread is not None and _plc_capture_poller_thread.is_alive():
            return
        def poll() -> None:
            while True:
                try:
                    plc_capture_poll_once()
                except Exception:
                    pass
                time.sleep(PLC_CAPTURE_POLL_SECONDS)
        _plc_capture_poller_thread = threading.Thread(
            target=poll,
            name="plc-capture-input-poller",
            daemon=True,
        )
        _plc_capture_poller_thread.start()


@app.on_event("startup")
def start_plc_runtime_workers() -> None:
    # v3 physical I/O belongs exclusively to a foreground Edge/Chrome page.
    # Keep legacy v1/v2 workers defined for read-only history verification, but
    # never start a server-side pyserial dispatcher or PLC input poller.
    return None


def plc_config_request_payload(request: PlcConfigRequest) -> dict[str, Any]:
    if hasattr(request, "model_dump"):
        return request.model_dump(exclude_none=True)  # type: ignore[attr-defined,no-any-return]
    return request.dict(exclude_none=True)


def plc_dispatch_audit_records(config: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    current = config if isinstance(config, dict) else load_config()
    records = current.get("plc_dispatches") if isinstance(current.get("plc_dispatches"), list) else []
    return [dict(item) for item in records if isinstance(item, dict)]


def raw_plc_namespace(config: dict[str, Any]) -> Any:
    return config["plc"] if "plc" in config else PLC_CONFIG_ABSENT


def plc_config_audit_snapshot(config: dict[str, Any]) -> dict[str, Any]:
    raw = raw_plc_namespace(config)
    if isinstance(raw, dict):
        return public_path_sanitized(dict(raw))
    if raw is PLC_CONFIG_ABSENT:
        return {"namespace_present": False, "enabled": False}
    return {"namespace_present": True, "namespace_valid": False, "value_type": type(raw).__name__}


def plc_dispatch_existing(dispatch_id: str) -> dict[str, Any] | None:
    for record in reversed(plc_dispatch_audit_records()):
        if str(record.get("dispatch_id") or "") == dispatch_id:
            return record
    return None


def mutate_app_config_atomically(mutator: Callable[[dict[str, Any]], None]) -> dict[str, Any]:
    """Atomically mutate only the protected PLC app-config namespace.

    JSON is single-process/thread safe. PostgreSQL additionally uses a
    transaction-scoped advisory lock so independent repository instances share
    the same namespace linearization point.
    """
    with _config_io_lock:
        repository = runtime_postgres_repository_or_none()
        if repository is not None:
            def mutate_protected(values: dict[str, Any]) -> None:
                mutator(values)
                unexpected = set(values) - set(PLC_PROTECTED_CONFIG_KEYS)
                if unexpected:
                    raise ValueError(f"PLC namespace mutator wrote unprotected keys: {sorted(unexpected)}")

            repository.mutate_app_config_namespace(
                PLC_PROTECTED_CONFIG_KEYS,
                mutate_protected,
                updated_at=int(time.time()),
            )
            return load_config()
        config = load_config()
        unprotected_before = {
            key: copy.deepcopy(value) for key, value in config.items() if key not in PLC_PROTECTED_CONFIG_KEYS
        }
        mutator(config)
        unprotected_after = {key: value for key, value in config.items() if key not in PLC_PROTECTED_CONFIG_KEYS}
        if unprotected_after != unprotected_before:
            raise ValueError("PLC namespace mutator changed unprotected app-config keys")
        token = _plc_namespace_write_authorized.set(True)
        try:
            save_app_config(config)
        finally:
            _plc_namespace_write_authorized.reset(token)
        return config


class PlcDispatchStateConflict(RuntimeError):
    def __init__(self, reason: str, authoritative: dict[str, Any] | None = None) -> None:
        super().__init__(reason)
        self.reason = reason
        self.authoritative = dict(authoritative or {})


