    FINISH_ATTEMPT = "finish_attempt"
    FINALIZE = "finalize"
    AUDIT_FAILURE_FINALIZE = "audit_failure_finalize"
    DEADLINE = "deadline"
    RECOVERY_FINALIZE = "recovery_finalize"
    CONTROL_FAILURE_FINALIZE = "control_failure_finalize"
    WORKER_FINALIZE = "worker_finalize"


