@app.delete("/api/pipeline/tasks/{task_id}")
def delete_pipeline_task(task_id: str) -> dict[str, Any]:
    user = current_auth_user()
    linked_job_ids: list[str] = []
    linked_dataset_ids: list[str] = []
    linked_model_run_ids: list[str] = []
    linked_ai_task_ids: list[str] = []
    # Stop any in-flight advance worker first so it self-cleans and doesn't keep
    # burning CPU or re-create a ghost record after we delete it.
    cancel_pipeline_advance(task_id)
    with _pipeline_tasks_lock:
        task = load_pipeline_task(task_id)
        if task:
            require_record_access(task, user, write=True)
            linked_job_ids = [
                str(item_id)
                for item_id in (task.get("samples_task_id"), task.get("training_task_id"))
                if str(item_id or "").strip()
            ]
            linked_dataset_ids = list(
                dict.fromkeys(
                    str(item_id)
                    for item_id in (task.get("dataset_id"), task.get("samples_task_id"))
                    if str(item_id or "").strip()
                )
            )
            linked_model_run_ids = list(
                dict.fromkeys(
                    str(item_id)
                    for item_id in (task.get("model_run_id"), task.get("training_task_id"))
                    if str(item_id or "").strip()
                )
            )
            linked_ai_task_ids = [
                str(item_id)
                for item_id in (task.get("ai_task_id"),)
                if str(item_id or "").strip()
            ]
        if not delete_pipeline_task_row(task_id):
            raise HTTPException(status_code=404, detail="流水线任务不存在")
    deleted_datasets = []
    for dataset_id in linked_dataset_ids:
        deleted = delete_training_dataset_resource(dataset_id, user, missing_ok=True)
        if deleted:
            deleted_datasets.append(dataset_id)
    deleted_models = []
    for run_id in linked_model_run_ids:
        deleted = delete_training_model_resource(run_id, user, missing_ok=True)
        if deleted:
            deleted_models.append(run_id)
    deleted_training_jobs = []
    for job_id in linked_job_ids:
        deleted = delete_training_task_record(job_id, user, missing_ok=True)
        if deleted:
            deleted_training_jobs.append(job_id)
    deleted_ai_tasks = []
    for ai_task_id in linked_ai_task_ids:
        deleted = delete_ai_detection_task_record(ai_task_id, user, missing_ok=True)
        if deleted:
            deleted_ai_tasks.append(ai_task_id)
    return {
        "status": "deleted",
        "deleted_task_id": task_id,
        "deleted_datasets": deleted_datasets,
        "deleted_models": deleted_models,
        "deleted_ai_tasks": deleted_ai_tasks,
        "deleted_training_jobs": deleted_training_jobs,
    }


@app.post("/api/pipeline/tasks/{task_id}/agent-feedback")
def pipeline_agent_feedback(task_id: str, request: PipelineAgentFeedbackRequest) -> dict[str, Any]:
    user = current_auth_user()
    config = scope_config_for_user(load_config(), user)
    action = str(request.action or "").strip().lower()
    decision = str(request.decision or action).strip().lower()
    pending_advances: list[str] = []
    with _pipeline_tasks_lock:
        task = load_pipeline_task(task_id)
        if not task:
            raise HTTPException(status_code=404, detail="流水线任务不存在")
        require_record_access(task, user, write=True)
        detection_method = normalize_pipeline_detection_method(str(task.get("detection_method") or (task.get("params") or {}).get("train_mode") or ""))
        if not pipeline_method_uses_training(detection_method):
            raise HTTPException(status_code=409, detail="Only YOLO/YOLO+OCR tasks use Agent/MCP orchestration")
        orchestration = ensure_agent_mcp_pose_plan(task, config)
        feedback_entry = {
            "action": action,
            "decision": decision,
            "message": str(request.message or "").strip()[:500],
            "created_at": agent_mcp_now(),
        }
        orchestration.setdefault("feedback", []).append(feedback_entry)
        if action in {"cancel", "cancelled"} or decision in {"cancel", "cancelled"}:
            orchestration.update({"state": "cancelled", "active_stage": "cancelled", "pause": None, "updated_at": agent_mcp_now()})
            task.update({"status": "stopped", "progress": 100, "last_error": "", "job_note": "Agent/MCP preview flow cancelled.", "updated_at": agent_mcp_now()})
        elif action == "replan" or decision == "replan":
            if pipeline_uses_photo_highlight_sprite_flow(task, config):
                orchestration = mark_legacy_pose_flow_skipped_for_photo_highlight(task, config, orchestration)
                orchestration["pause"] = None
                task["agent_mcp"] = orchestration
                task.update({"status": "ready", "progress": 0, "last_error": "", "job_note": "", "updated_at": agent_mcp_now()})
                mark_pipeline_task_advancing(task)
                pending_advances.append(task_id)
            else:
                orchestration = ensure_agent_mcp_pose_plan(task, config, force=True)
                task["agent_mcp"] = orchestration
                orchestration = ensure_agent_mcp_pose_tool_calls(task, config)
                tool_config = agent_mcp_gemini_image_config()
                if tool_config.get("configured") and execute_agent_mcp_pose_tool_calls(task, config):
                    task.update({"status": "ready", "progress": 0, "last_error": "", "job_note": "", "updated_at": agent_mcp_now()})
                else:
                    pause_agent_mcp_task(
                        task,
                        orchestration,
                        stage="pose_image_generation",
                        reason="Pose plan regenerated; " + str(tool_config.get("message") or "Image generation is not configured."),
                        suggested_actions=["configure_image_generation", "continue_existing_assets", "replan", "cancel"],
                    )
        elif action in {"update_plan", "update"}:
            if pipeline_uses_photo_highlight_sprite_flow(task, config):
                raise HTTPException(status_code=409, detail="当前训练流程使用实拍高亮抠图，不再支持旧姿态计划编辑")
            if not isinstance(request.updated_plan, dict):
                raise HTTPException(status_code=400, detail="updated_plan is required")
            orchestration["pose_plan"] = request.updated_plan
            orchestration["state"] = "needs_user_action"
            orchestration["active_stage"] = "pose_image_generation"
            orchestration["updated_at"] = agent_mcp_now()
            pause_agent_mcp_task(
                task,
                orchestration,
                stage="pose_image_generation",
                reason="Pose plan updated by user; confirm how to proceed.",
                suggested_actions=["continue_existing_assets", "replan", "cancel"],
            )
        elif action in {"retry_pose_image_generation", "retry"} or decision == "retry_pose_image_generation":
            if pipeline_uses_photo_highlight_sprite_flow(task, config):
                orchestration = mark_legacy_pose_flow_skipped_for_photo_highlight(task, config, orchestration)
                orchestration["pause"] = None
                task["agent_mcp"] = orchestration
                task.update({"status": "ready", "progress": 0, "last_error": "", "job_note": "", "updated_at": agent_mcp_now()})
                mark_pipeline_task_advancing(task)
                pending_advances.append(task_id)
            else:
                orchestration["skip_pose_image_generation"] = False
                orchestration["pause"] = None
                if execute_agent_mcp_pose_tool_calls(task, config):
                    task.update({"status": "ready", "progress": 0, "last_error": "", "job_note": "", "updated_at": agent_mcp_now()})
                elif not orchestration.get("pause"):
                    tool_config = agent_mcp_gemini_image_config()
                    pause_agent_mcp_task(
                        task,
                        orchestration,
                        stage="pose_image_generation",
                        reason=str(tool_config.get("message") or "Image generation is not configured."),
                        suggested_actions=["configure_image_generation", "continue_existing_assets", "replan", "cancel"],
                    )
        elif action in {"resume", "continue", "continue_existing_assets"} or decision in {"continue_existing_assets", "use_existing_assets"}:
            orchestration["skip_pose_image_generation"] = True
            orchestration["pause"] = None
            orchestration["updated_at"] = agent_mcp_now()
            if task.get("stage") == "samples" or orchestration.get("active_stage") == "model_training" or decision == "continue_training":
                orchestration["training_quality_ack"] = True
                if task.get("stage") == "samples":
                    task["status"] = "completed"
                mark_pipeline_task_advancing(task)
                pending_advances.append(task_id)
            else:
                task.update({"status": "ready", "progress": 0, "last_error": "", "job_note": "", "updated_at": agent_mcp_now()})
                mark_pipeline_task_advancing(task)
                pending_advances.append(task_id)
        elif action in {"continue_training", "resume_training"} or decision == "continue_training":
            orchestration["training_quality_ack"] = True
            orchestration["pause"] = None
            if task.get("stage") != "samples":
                raise HTTPException(status_code=409, detail="Task is not waiting at model training gate")
            task["status"] = "completed"
            mark_pipeline_task_advancing(task)
            pending_advances.append(task_id)
        else:
            raise HTTPException(status_code=400, detail="Unknown Agent/MCP feedback action")
        save_pipeline_task(task)
        result = pipeline_task_public(task, config)
    for advance_id in pending_advances:
        schedule_pipeline_advance(advance_id, user)
    return result


@app.post("/api/pipeline/tasks/{task_id}/chat")
def pipeline_agent_chat(task_id: str, request: PipelineAgentChatRequest) -> dict[str, Any]:
    user = current_auth_user()
    config = scope_config_for_user(load_config(), user)
    message = bounded_text(request.message, 1000)
    if not message:
        raise HTTPException(status_code=400, detail="消息内容不能为空")
    # Validate access/method and snapshot the task without holding the lock during the Agent call.
    with _pipeline_tasks_lock:
        task = load_pipeline_task(task_id)
        if not task:
            raise HTTPException(status_code=404, detail="流水线任务不存在")
        require_record_access(task, user, write=True)
        detection_method = normalize_pipeline_detection_method(str(task.get("detection_method") or (task.get("params") or {}).get("train_mode") or ""))
        if not pipeline_method_uses_training(detection_method):
            raise HTTPException(status_code=409, detail="该任务使用 AI 检测，建档完成即可直接使用，无需 Agent 训练编排。")
        snapshot = copy.deepcopy(task)
    decision = agent_pipeline_decide(snapshot, config, user_message=message, trigger="chat")
    pending_advances: list[str] = []
    with _pipeline_tasks_lock:
        task = load_pipeline_task(task_id)
        if not task:
            raise HTTPException(status_code=404, detail="流水线任务不存在")
        require_record_access(task, user, write=True)
        commit_pipeline_agent_turn(task, config, user, message, decision, "chat", pending_advances=pending_advances)
        save_pipeline_task(task)
        result = pipeline_task_public(task, config)
    for advance_id in pending_advances:
        schedule_pipeline_advance(advance_id, user)
    return result


@app.post("/api/pipeline/tasks/{task_id}/advance")
def advance_pipeline_task_endpoint(task_id: str) -> dict[str, Any]:
    user = current_auth_user()
    config = scope_config_for_user(load_config(), user)
    # Validate + mark the task as advancing, then hand the heavy/bounded work to
    # the async per-task runner so this request returns immediately (no global
    # lock, no 504). The runner persists sub-step progress; the UI polls for it.
    with _pipeline_tasks_lock:
        task = load_pipeline_task(task_id)
        if not task:
            raise HTTPException(status_code=404, detail="流水线任务不存在")
        require_record_access(task, user, write=True)
        sync_pipeline_task(task)
        already = False
        with _pipeline_advance_registry_lock:
            already = task_id in _pipeline_advance_inflight
        if not already:
            task["advancing"] = True
            task["advance_started_at"] = int(time.time())
            task["job_note"] = "正在推进…"
            task["last_error"] = ""
            task["updated_at"] = int(time.time())
            save_pipeline_task(task)
        result = pipeline_task_public(task, config)
    if not already:
        schedule_pipeline_advance(task_id, user)
    return result


@app.post("/api/pipeline/tasks/{task_id}/cancel-advance")
def cancel_pipeline_advance_endpoint(task_id: str) -> dict[str, Any]:
    user = current_auth_user()
    config = scope_config_for_user(load_config(), user)
    with _pipeline_tasks_lock:
        task = load_pipeline_task(task_id)
        if not task:
            raise HTTPException(status_code=404, detail="流水线任务不存在")
        require_record_access(task, user, write=True)
    inflight = cancel_pipeline_advance(task_id)
    with _pipeline_tasks_lock:
        task = load_pipeline_task(task_id)
        if not task:
            raise HTTPException(status_code=404, detail="流水线任务不存在")
        task["auto_advance"] = False
        task["last_error"] = ""
        if inflight:
            task["pause_requested"] = True
            task["job_note"] = "暂停请求已记录；如果当前步骤不可中断，会在当前步骤完成后的检查点停止。"
        else:
            task.pop("advancing", None)
            task.pop("advance_started_at", None)
            task.pop("pause_requested", None)
            if task.get("stage") == "draft" and task.get("status") in {"ready", "running"}:
                task["status"] = "stopped"
            task["job_note"] = "已暂停，自动推进已关闭。"
        task["updated_at"] = int(time.time())
        save_pipeline_task(task)
        result = pipeline_task_public(task, config)
    return result


# ---------------------------------------------------------------------------
# Package-material incoming text inspection (independent from YOLO training).


def _incoming_text_json_list(path: Path) -> list[dict[str, Any]]:
    if not path.exists():
        return []
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return []
    return [dict(item) for item in value if isinstance(item, dict)] if isinstance(value, list) else []


def _save_incoming_text_json_list(path: Path, values: list[dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f"{path.name}.{uuid.uuid4().hex}.tmp")
    temporary.write_text(json.dumps(values, ensure_ascii=False, indent=2), encoding="utf-8")
    os.replace(temporary, path)


def load_incoming_text_references() -> list[dict[str, Any]]:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        return row_raw_json_list(repository.fetch_all("incoming_text_reference_versions"))
    with _incoming_text_store_lock:
        return _incoming_text_json_list(INCOMING_TEXT_REFERENCES_PATH)


def load_incoming_text_inspections() -> list[dict[str, Any]]:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        return row_raw_json_list(repository.fetch_all("incoming_text_inspections"))
    with _incoming_text_store_lock:
        return _incoming_text_json_list(INCOMING_TEXT_INSPECTIONS_PATH)


def load_incoming_text_reference(reference_id: str) -> dict[str, Any] | None:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        row = repository.fetch_by_primary_key("incoming_text_reference_versions", {"id": reference_id})
        values = row_raw_json_list([row]) if row else []
        return values[0] if values else None
    return next((item for item in load_incoming_text_references() if str(item.get("id")) == reference_id), None)


def load_incoming_text_inspection(inspection_id: str) -> dict[str, Any] | None:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        row = repository.fetch_by_primary_key("incoming_text_inspections", {"id": inspection_id})
        values = row_raw_json_list([row]) if row else []
        return values[0] if values else None
    return next((item for item in load_incoming_text_inspections() if str(item.get("id")) == inspection_id), None)


def save_incoming_text_reference(reference: dict[str, Any], *, insert_only: bool = False) -> bool:
    row = incoming_text_reference_row(reference)
    if not row:
        raise RuntimeError("invalid incoming text reference row")
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        if insert_only:
            return bool(repository.insert_row_once("incoming_text_reference_versions", row))
        repository.upsert_row("incoming_text_reference_versions", row)
        return True
    with _incoming_text_store_lock:
        values = _incoming_text_json_list(INCOMING_TEXT_REFERENCES_PATH)
        existing_index = next((index for index, item in enumerate(values) if str(item.get("id")) == str(reference["id"])), None)
        if existing_index is not None:
            if insert_only:
                return False
            values[existing_index] = dict(reference)
        else:
            if any(
                str(item.get("owner_user_id")) == str(reference.get("owner_user_id"))
                and str(item.get("task_id")) == str(reference.get("task_id"))
                and str(item.get("version_label")) == str(reference.get("version_label"))
                for item in values
            ):
                return False
            values.insert(0, dict(reference))
        _save_incoming_text_json_list(INCOMING_TEXT_REFERENCES_PATH, values)
        return True


def save_incoming_text_inspection(inspection: dict[str, Any], *, insert_only: bool = False) -> bool:
    row = incoming_text_inspection_row(inspection)
    if not row:
        raise RuntimeError("invalid incoming text inspection row")
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        if insert_only:
            return bool(repository.insert_row_once("incoming_text_inspections", row))
        repository.upsert_row("incoming_text_inspections", row)
        return True
    with _incoming_text_store_lock:
        values = _incoming_text_json_list(INCOMING_TEXT_INSPECTIONS_PATH)
        duplicate = next(
            (
                item
                for item in values
                if str(item.get("owner_user_id")) == str(inspection.get("owner_user_id"))
                and str(item.get("task_id")) == str(inspection.get("task_id"))
                and str(item.get("capture_id")) == str(inspection.get("capture_id"))
            ),
            None,
        )
        existing_index = next((index for index, item in enumerate(values) if str(item.get("id")) == str(inspection["id"])), None)
        if insert_only and (duplicate is not None or existing_index is not None):
            return False
        if existing_index is None:
            values.insert(0, dict(inspection))
        else:
            values[existing_index] = dict(inspection)
        _save_incoming_text_json_list(INCOMING_TEXT_INSPECTIONS_PATH, values)
        return True


def append_incoming_text_audit(event: dict[str, Any]) -> None:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        row = audit_event_row(event)
        if row:
            repository.insert_row_once("audit_events", row)
        return
    with _incoming_text_store_lock:
        values = _incoming_text_json_list(INCOMING_TEXT_AUDIT_PATH)
        if not any(str(item.get("id")) == str(event.get("id")) for item in values):
            values.insert(0, dict(event))
            _save_incoming_text_json_list(INCOMING_TEXT_AUDIT_PATH, values)


def incoming_text_public(record: dict[str, Any]) -> dict[str, Any]:
    value = copy.deepcopy(record)
    record_id = str(value.get("id") or "")
    for key in ("source_path", "canonical_path", "corrected_path", "annotated_path"):
        raw_path = str(value.pop(key, "") or "")
        if raw_path:
            asset_kind = key.removesuffix("_path")
            if record_id.startswith("itinsp_"):
                value[f"{asset_kind}_url"] = f"/api/incoming-text/inspections/{quote(record_id)}/evidence/{asset_kind}"
            elif record_id.startswith("itref_"):
                value[f"{asset_kind}_url"] = f"/api/incoming-text/references/{quote(record_id)}/asset/{asset_kind}"
    return public_path_sanitized(value)


def incoming_text_task_access_allowed(task: dict[str, Any], user: dict[str, Any]) -> bool:
    return user_is_admin(user) or record_owner_id(task) == str(user.get("id") or "")


def require_incoming_text_task(task_id: str, *, write: bool = False) -> dict[str, Any]:
    task = load_pipeline_task(task_id)
    if not task or str(task.get("task_kind") or "") != "incoming_material_text":
        raise HTTPException(status_code=404, detail="包材文字检验任务不存在")
    if not incoming_text_task_access_allowed(task, current_auth_user()):
        raise HTTPException(status_code=404, detail="包材文字检验任务不存在")
    return task


def decode_incoming_reference(contents: bytes, filename: str) -> tuple[np.ndarray, str]:
    if not contents or len(contents) > 20 * 1024 * 1024:
        raise HTTPException(status_code=400, detail="标准稿必须为 20MB 以内的单页 PDF/PNG/JPG")
    lower_name = filename.lower()
    if contents.startswith(b"%PDF-"):
        try:
            import fitz
        except ImportError:
            raise HTTPException(status_code=503, detail="PDF 渲染组件尚未安装") from None
        try:
            document = fitz.open(stream=contents, filetype="pdf")
            if document.page_count != 1:
                raise HTTPException(status_code=400, detail="标准稿 PDF 必须只有一页")
            pixmap = document[0].get_pixmap(matrix=fitz.Matrix(2, 2), alpha=False)
            image = cv2.imdecode(np.frombuffer(pixmap.tobytes("png"), dtype=np.uint8), cv2.IMREAD_COLOR)
        except HTTPException:
            raise
        except Exception:
            raise HTTPException(status_code=400, detail="无法解析标准稿 PDF") from None
        return image, ".pdf"
    if not (lower_name.endswith((".png", ".jpg", ".jpeg")) or contents[:8] == b"\x89PNG\r\n\x1a\n" or contents[:2] == b"\xff\xd8"):
        raise HTTPException(status_code=400, detail="标准稿仅支持单页 PDF、PNG 或 JPG")
    image = cv2.imdecode(np.frombuffer(contents, dtype=np.uint8), cv2.IMREAD_COLOR)
    if image is None:
        raise HTTPException(status_code=400, detail="标准稿图片解码失败")
    height, width = image.shape[:2]
    if width * height > 40_000_000 or min(width, height) < 200:
        raise HTTPException(status_code=400, detail="标准稿尺寸不符合要求")
    return image, ".png" if contents[:8] == b"\x89PNG\r\n\x1a\n" else ".jpg"


def incoming_text_ocr_engine() -> Any:
    global _incoming_text_ocr
    with _incoming_text_ocr_lock:
        if _incoming_text_ocr is None:
            prepare_paddle_runtime()
            from paddleocr import PaddleOCR

            _incoming_text_ocr = PaddleOCR(
                # Production is pinned to PaddleOCR/PaddleX 3.7, where the
                # PP-OCRv6 medium profile is registered and preloaded alongside
                # the legacy v6-small path. Geometry is
                # normalized exactly once by rectify_label above so OCR boxes
                # stay in the same canonical coordinate space as field ROIs.
                text_detection_model_name="PP-OCRv6_medium_det",
                text_recognition_model_name="PP-OCRv6_medium_rec",
                use_doc_orientation_classify=False,
                use_doc_unwarping=False,
                use_textline_orientation=True,
            )
        return _incoming_text_ocr


def _ocr_result_mapping(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    raw = getattr(value, "json", None)
    if callable(raw):
        raw = raw()
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except json.JSONDecodeError:
            raw = None
    if isinstance(raw, dict):
        return raw.get("res") if isinstance(raw.get("res"), dict) else raw
    return {}


def incoming_text_ocr_observations(image: np.ndarray) -> list[TextObservation]:
    result_items = incoming_text_ocr_engine().predict(cv2.cvtColor(image, cv2.COLOR_BGR2RGB))
    result = _ocr_result_mapping(result_items[0] if result_items else {})
    texts = list(result.get("rec_texts") or [])
    scores = list(result.get("rec_scores") or [])
    polygons = list(result.get("rec_polys") or result.get("dt_polys") or [])
    observations: list[TextObservation] = []
    for index, text_value in enumerate(texts):
        text_value = str(text_value)
        if not text_value:
            continue
        polygon_value = polygons[index] if index < len(polygons) else []
        try:
            polygon = tuple((float(point[0]), float(point[1])) for point in polygon_value)
        except (TypeError, ValueError, IndexError):
            polygon = ()
        confidence = float(scores[index]) if index < len(scores) else 0.0
        observations.append(TextObservation(text=text_value, confidence=confidence, polygon=polygon))
    return observations


def incoming_text_corroboration_observations(
    image: np.ndarray, rules: list[dict[str, Any]]
) -> dict[str, list[TextObservation]]:
    """Run the second OCR pass only on critical ROIs and restore global coords."""
    height, width = image.shape[:2]
    by_field: dict[str, list[TextObservation]] = {}
    for rule in rules:
        if rule.get("importance") != "critical":
            continue
        region = rule["region_normalized"]
        padding_x = max(4, int(width * 0.008))
        padding_y = max(4, int(height * 0.008))
        x1 = max(0, int(region["x"] * width) - padding_x)
        y1 = max(0, int(region["y"] * height) - padding_y)
        x2 = min(width, int((region["x"] + region["width"]) * width) + padding_x)
        y2 = min(height, int((region["y"] + region["height"]) * height) + padding_y)
        crop = image[y1:y2, x1:x2]
        if crop.size == 0:
            by_field[str(rule["field_id"])] = []
            continue
        translated = []
        for observation in incoming_text_ocr_observations(crop):
            translated.append(
                TextObservation(
                    text=observation.text,
                    confidence=observation.confidence,
                    polygon=tuple((x + x1, y + y1) for x, y in observation.polygon),
                )
            )
        by_field[str(rule["field_id"])] = translated
    return by_field


def _field_observation(
    rule: dict[str, Any], first: list[TextObservation], second: list[TextObservation], image: np.ndarray, reference_image: np.ndarray
) -> TextObservation | None:
    image_size = (image.shape[1], image.shape[0])
    first_items = observations_for_rule(rule, first, image_size)
    second_items = observations_for_rule(rule, second, image_size)
    first_text = " ".join(item.text for item in first_items)
    second_text = " ".join(item.text for item in second_items)
    if not first_items and not second_items:
        region = rule["region_normalized"]
        x1, y1 = int(region["x"] * image.shape[1]), int(region["y"] * image.shape[0])
        x2 = int((region["x"] + region["width"]) * image.shape[1])
        y2 = int((region["y"] + region["height"]) * image.shape[0])
        roi = image[y1:y2, x1:x2]
        reference_roi = reference_image[y1:y2, x1:x2]
        similarity = local_visual_similarity(reference_image, image, region)
        roi_sharpness = float(cv2.Laplacian(cv2.cvtColor(roi, cv2.COLOR_BGR2GRAY), cv2.CV_64F).var()) if roi.size else 0.0
        reference_sharpness = float(cv2.Laplacian(cv2.cvtColor(reference_roi, cv2.COLOR_BGR2GRAY), cv2.CV_64F).var()) if reference_roi.size else 0.0
        # Absence is automatic only with two successful empty OCR passes plus
        # clear, aligned ROI evidence on both the approved artwork and capture.
        if roi.size and reference_roi.size and roi_sharpness >= 85 and reference_sharpness >= 85 and similarity is not None and similarity < 0.42:
            return TextObservation(text="", confidence=1.0, corroborated=True)
        return None
    confidence = min(
        sum(item.confidence for item in first_items) / max(len(first_items), 1),
        sum(item.confidence for item in second_items) / max(len(second_items), 1),
    )
    polygon = tuple(point for item in first_items for point in item.polygon)
    return TextObservation(
        text=first_text,
        confidence=confidence,
        polygon=polygon,
        corroborated=bool(
            first_items
            and second_items
            and comparison_text(first_text, rule) == comparison_text(second_text, rule)
        ),
    )


def _duplicate_incoming_capture(owner_user_id: str, task_id: str, capture_id: str) -> dict[str, Any] | None:
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        row = repository.fetch_one_by_columns(
            "incoming_text_inspections",
            {"owner_user_id": owner_user_id, "task_id": task_id, "capture_id": capture_id},
        )
        values = row_raw_json_list([row]) if row else []
        return values[0] if values else None
    return next(
        (
            item
            for item in load_incoming_text_inspections()
            if str(item.get("owner_user_id")) == owner_user_id
            and str(item.get("task_id")) == task_id
            and str(item.get("capture_id")) == capture_id
        ),
        None,
    )


@app.get("/api/incoming-text/tasks/{task_id}")
def get_incoming_text_task(task_id: str) -> dict[str, Any]:
    task = require_incoming_text_task(task_id)
    references = [
        incoming_text_public(item)
        for item in load_incoming_text_references()
        if str(item.get("task_id")) == task_id
    ]
    references.sort(key=lambda item: int(item.get("created_at") or 0), reverse=True)
    active_items = [item for item in references if item.get("status") == "active"]
    active = active_items[0] if len(active_items) == 1 else None
    public_task = pipeline_task_public(task, scope_config_for_user(load_config()))
    public_task["status"] = "ready" if active else "configuration_error" if active_items else "setup_required"
    public_task["active_reference_id"] = str(active.get("id") or "") if active else ""
    public_task["reference_version_label"] = str(active.get("version_label") or "") if active else ""
    return {
        "task": public_task,
        "references": references,
        "active_reference": active,
        "configuration_valid": len(active_items) <= 1,
        "automatic_decisions_verified": INCOMING_TEXT_AUTOMATIC_DECISIONS_VERIFIED,
    }


@app.get("/api/incoming-text/references/{reference_id}/asset/{asset_kind}")
def get_incoming_text_reference_asset(reference_id: str, asset_kind: str) -> FileResponse:
    reference = load_incoming_text_reference(reference_id)
    if not reference:
        raise HTTPException(status_code=404, detail="标准版本不存在")
    require_record_access(reference, current_auth_user())
    require_incoming_text_task(str(reference.get("task_id")))
    key = {"source": "source_path", "canonical": "canonical_path"}.get(asset_kind)
    path = Path(str(reference.get(key or "") or ""))
    if not key or not path.exists() or not path_is_under(path, OUTPUT_DIR):
        raise HTTPException(status_code=404, detail="标准稿文件不存在")
    return FileResponse(path)


@app.post("/api/incoming-text/tasks/{task_id}/references")
async def create_incoming_text_reference(
    task_id: str,
    file: UploadFile = File(...),
    version_label: str = Form(...),
) -> dict[str, Any]:
    require_permission("incoming_material_config", detail="没有包材文字标准配置权限")
    task = require_incoming_text_task(task_id, write=True)
    clean_version = version_label.strip()
    if not clean_version or len(clean_version) > 40:
        raise HTTPException(status_code=400, detail="标准版本号必须为 1–40 个字符")
    contents = await file.read()
    image, suffix = decode_incoming_reference(contents, file.filename or "reference")
    owner_user_id = str(task.get("owner_user_id") or record_owner_id(task))
    reference_id = f"itref_{uuid.uuid4().hex[:12]}"
    output_dir = output_write_dir_for_owner(f"incoming_text/references/{task_id}", owner_user_id)
    source_path = output_dir / f"{reference_id}{suffix}"
    canonical_path = output_dir / f"{reference_id}_canonical.png"
    source_path.write_bytes(contents)
    if not cv2.imwrite(str(canonical_path), image):
        source_path.unlink(missing_ok=True)
        raise HTTPException(status_code=500, detail="标准稿规范化图片保存失败")
    now = int(time.time())
    reference = {
        "id": reference_id,
        "task_id": task_id,
        "version_label": clean_version,
        "material_code": str(task.get("material_code") or ""),
        "material_name": str(task.get("material_name") or ""),
        "status": "draft",
        "source_filename": Path(file.filename or "reference").name,
        "source_path": str(source_path),
        "canonical_path": str(canonical_path),
        "source_sha256": hashlib.sha256(contents).hexdigest(),
        "canonical_sha256": hashlib.sha256(canonical_path.read_bytes()).hexdigest(),
        "width": int(image.shape[1]),
        "height": int(image.shape[0]),
        "rules": [],
        "created_at": now,
        "activated_at": 0,
        "created_by_user_id": str(current_auth_user().get("id") or ""),
        "owner_user_id": owner_user_id,
        "owner_username": str(task.get("owner_username") or ""),
        "shared_with_user_ids": list(task.get("shared_with_user_ids") or []),
    }
    if not save_incoming_text_reference(reference, insert_only=True):
        source_path.unlink(missing_ok=True)
        canonical_path.unlink(missing_ok=True)
        raise HTTPException(status_code=409, detail="该标准版本号已存在")
    return incoming_text_public(reference)


@app.put("/api/incoming-text/references/{reference_id}/rules")
def update_incoming_text_reference_rules(reference_id: str, request: IncomingTextRulesRequest) -> dict[str, Any]:
    require_permission("incoming_material_config", detail="没有包材文字标准配置权限")
    reference = load_incoming_text_reference(reference_id)
    if not reference:
        raise HTTPException(status_code=404, detail="标准版本不存在")
    require_record_access(reference, current_auth_user(), write=True)
    require_incoming_text_task(str(reference.get("task_id")), write=True)
    if reference.get("status") != "draft":
        raise HTTPException(status_code=409, detail="已启用的标准不可修改，请新建版本")
    try:
        rules = normalize_field_rules(request.rules)
    except IncomingTextValidationError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from None
    reference["rules"] = rules
    reference["updated_at"] = int(time.time())
    if request.activate:
        reference["status"] = "active"
        reference["activated_at"] = int(time.time())
        reference["activated_by_user_id"] = str(current_auth_user().get("id") or "")
        repository = runtime_postgres_repository_or_none()
        if repository is not None:
            draft = dict(reference)
            draft["status"] = "draft"
            save_incoming_text_reference(draft)
            repository.activate_incoming_text_reference(
                reference_id,
                str(reference.get("owner_user_id")),
                str(reference.get("task_id")),
                reference,
            )
        else:
            with _incoming_text_store_lock:
                values = _incoming_text_json_list(INCOMING_TEXT_REFERENCES_PATH)
                for item in values:
                    if (
                        str(item.get("owner_user_id")) == str(reference.get("owner_user_id"))
                        and str(item.get("task_id")) == str(reference.get("task_id"))
                        and item.get("status") == "active"
                    ):
                        item["status"] = "archived"
                values = [reference if str(item.get("id")) == reference_id else item for item in values]
                _save_incoming_text_json_list(INCOMING_TEXT_REFERENCES_PATH, values)
        task = require_incoming_text_task(str(reference.get("task_id")), write=True)
        task.update(
            {
                "status": "ready",
                "active_reference_id": reference_id,
                "reference_version_label": reference["version_label"],
                "updated_at": int(time.time()),
            }
        )
        save_pipeline_task(task)
    else:
        save_incoming_text_reference(reference)
    return incoming_text_public(reference)


@app.post("/api/incoming-text/references/{reference_id}/clone")
def clone_incoming_text_reference(reference_id: str, version_label: str = Form(...)) -> dict[str, Any]:
    require_permission("incoming_material_config", detail="没有包材文字标准配置权限")
    source = load_incoming_text_reference(reference_id)
    if not source:
        raise HTTPException(status_code=404, detail="标准版本不存在")
    require_record_access(source, current_auth_user(), write=True)
    require_incoming_text_task(str(source.get("task_id") or ""), write=True)
    clean_version = version_label.strip()
    if not clean_version or len(clean_version) > 40:
        raise HTTPException(status_code=400, detail="标准版本号必须为 1–40 个字符")
    clone = copy.deepcopy(source)
    clone.update(
        {
            "id": f"itref_{uuid.uuid4().hex[:12]}",
            "version_label": clean_version,
            "status": "draft",
            "created_at": int(time.time()),
            "activated_at": 0,
            "created_by_user_id": str(current_auth_user().get("id") or ""),
        }
    )
    if not save_incoming_text_reference(clone, insert_only=True):
        raise HTTPException(status_code=409, detail="该标准版本号已存在")
    return incoming_text_public(clone)


def require_incoming_text_storage_capacity(upload_bytes: int) -> None:
    reserve = INCOMING_TEXT_MIN_FREE_BYTES + max(0, int(upload_bytes)) * 3
    try:
        free_bytes = shutil.disk_usage(DATA_DIR).free
    except OSError as exc:
        raise HTTPException(status_code=507, detail="无法确认服务器存储空间，已停止本次检验") from exc
    if free_bytes < reserve:
        raise HTTPException(status_code=507, detail="服务器存储空间不足，已停止本次检验，请联系管理员清理空间")


@app.post("/api/incoming-text/tasks/{task_id}/inspect")
async def inspect_incoming_text(
    task_id: str,
    file: UploadFile = File(...),
    capture_id: str = Form(...),
) -> dict[str, Any]:
    require_permission("inspection", detail="没有来料检验权限")
    task = require_incoming_text_task(task_id)
    capture_id = capture_id.strip()
    if not re.fullmatch(r"[A-Za-z0-9_.-]{8,128}", capture_id):
        raise HTTPException(status_code=400, detail="capture_id 格式错误")
    owner_user_id = str(task.get("owner_user_id") or record_owner_id(task))
    contents = await file.read()
    if not contents or len(contents) > 20 * 1024 * 1024:
        raise HTTPException(status_code=400, detail="拍照图片必须在 20MB 以内")
    source_hash = hashlib.sha256(contents).hexdigest()
    duplicate = _duplicate_incoming_capture(owner_user_id, task_id, capture_id)
    if duplicate:
        if duplicate.get("source_sha256") != source_hash:
            raise HTTPException(status_code=409, detail="同一 capture_id 对应了不同图片")
        return incoming_text_public(duplicate)
    require_incoming_text_storage_capacity(len(contents))
    active_references = [
        item
        for item in load_incoming_text_references()
        if str(item.get("task_id")) == task_id and item.get("status") == "active" and str(item.get("owner_user_id")) == owner_user_id
    ]
    if not active_references:
        raise HTTPException(status_code=409, detail="任务还没有已启用的标准版本")
    if len(active_references) != 1:
        raise HTTPException(status_code=409, detail="任务标准状态异常，请管理员处理后再检验")
    reference = active_references[0]
    image = cv2.imdecode(np.frombuffer(contents, dtype=np.uint8), cv2.IMREAD_COLOR)
    if image is None:
        raise HTTPException(status_code=400, detail="拍照图片解码失败")
    image_height, image_width = image.shape[:2]
    if image_width * image_height > 40_000_000 or min(image_width, image_height) < 300:
        raise HTTPException(status_code=400, detail="拍照图片尺寸不符合要求")
    inspection_id = f"itinsp_{uuid.uuid4().hex[:14]}"
    output_dir = output_write_dir_for_owner(f"incoming_text/inspections/{task_id}", owner_user_id)
    source_suffix = ".png" if contents[:8] == b"\x89PNG\r\n\x1a\n" else ".jpg"
    source_path = output_dir / f"{inspection_id}_source{source_suffix}"
    source_path.write_bytes(contents)
    now = int(time.time())
    inspection = {
        "id": inspection_id,
        "capture_id": capture_id,
        "task_id": task_id,
        "reference_id": str(reference["id"]),
        "reference_version_label": str(reference.get("version_label") or ""),
        "reference_sha256": str(reference.get("source_sha256") or ""),
        "material_code": str(task.get("material_code") or ""),
        "material_name": str(task.get("material_name") or ""),
        "status": "processing",
        "auto_decision": "",
        "final_decision": "",
        "source_path": str(source_path),
        "source_sha256": source_hash,
        "created_at": now,
        "updated_at": now,
        "operator_user_id": str(current_auth_user().get("id") or ""),
        "owner_user_id": owner_user_id,
        "owner_username": str(task.get("owner_username") or ""),
        "shared_with_user_ids": list(task.get("shared_with_user_ids") or []),
    }
    if not save_incoming_text_inspection(inspection, insert_only=True):
        source_path.unlink(missing_ok=True)
        duplicate = _duplicate_incoming_capture(owner_user_id, task_id, capture_id)
        if duplicate and duplicate.get("source_sha256") == source_hash:
            return incoming_text_public(duplicate)
        raise HTTPException(status_code=409, detail="capture_id 已被其他请求占用")
    quality = assess_image_quality(image)
    try:
        reference_image = cv2.imread(str(reference.get("canonical_path") or ""), cv2.IMREAD_COLOR)
        if reference_image is None:
            raise RuntimeError("reference_image_missing")
        corrected, alignment = rectify_label(image, (reference_image.shape[1], reference_image.shape[0]))
        can_run_ocr = bool(quality.get("accepted") and alignment.get("accepted"))
        rules = normalize_field_rules(reference.get("rules"))
        first = incoming_text_ocr_observations(corrected) if can_run_ocr else []
        gray = cv2.cvtColor(corrected, cv2.COLOR_BGR2GRAY)
        enhanced = cv2.cvtColor(cv2.createCLAHE(clipLimit=1.8, tileGridSize=(8, 8)).apply(gray), cv2.COLOR_GRAY2BGR)
        second_by_field = incoming_text_corroboration_observations(enhanced, rules) if can_run_ocr else {}
        observations = {
            rule["field_id"]: _field_observation(
                rule, first, second_by_field.get(str(rule["field_id"]), []), corrected, reference_image
            )
            for rule in rules
        }
        similarities = {
            rule["field_id"]: score
            for rule in rules
            for score in [local_visual_similarity(reference_image, corrected, rule["region_normalized"])]
            if score is not None
        }
        result = decide_inspection(rules, observations, quality=quality, alignment=alignment, visual_similarities=similarities)
        result = apply_commissioning_gate(
            result, automatic_decisions_verified=INCOMING_TEXT_AUTOMATIC_DECISIONS_VERIFIED
        )
        annotated = annotate_inspection(corrected, result["fields"])
        corrected_path = output_dir / f"{inspection_id}_corrected.jpg"
        annotated_path = output_dir / f"{inspection_id}_annotated.jpg"
        if not cv2.imwrite(str(corrected_path), corrected) or not cv2.imwrite(str(annotated_path), annotated):
            raise RuntimeError("evidence_save_failed")
        inspection.update(
            {
                "status": "completed",
                "auto_decision": result["decision"],
                "final_decision": result["decision"] if result["decision"] in {INCOMING_TEXT_PASS, INCOMING_TEXT_FAIL} else "",
                "quality": quality,
                "alignment": alignment,
                "fields": result["fields"],
                "reasons": result["reasons"],
                "candidate_decision": result.get("candidate_decision", ""),
                "corrected_path": str(corrected_path),
                "annotated_path": str(annotated_path),
                "ocr_engine": "PaddleOCR-3.7.0/PP-OCRv6-medium/two-pass",
                "updated_at": int(time.time()),
            }
        )
    except Exception as exc:  # fail closed: engine/files/rules can never yield PASS
        inspection.update(
            {
                "status": "completed_with_error",
                "auto_decision": INCOMING_TEXT_REVIEW_REQUIRED,
                "final_decision": "",
                "quality": quality,
                "reasons": ["inspection_engine_error"],
                "error_code": type(exc).__name__,
                "updated_at": int(time.time()),
            }
        )
    save_incoming_text_inspection(inspection)
    return incoming_text_public(inspection)


@app.get("/api/incoming-text/inspections/{inspection_id}/evidence/{asset_kind}")
def get_incoming_text_inspection_evidence(inspection_id: str, asset_kind: str) -> FileResponse:
    inspection = load_incoming_text_inspection(inspection_id)
    if not inspection:
        raise HTTPException(status_code=404, detail="检验记录不存在")
    # The task owner is authoritative. Legacy shared assignments do not grant
    # access after the self-owned task model was introduced.
    require_incoming_text_task(str(inspection.get("task_id")))
    key = {"source": "source_path", "corrected": "corrected_path", "annotated": "annotated_path"}.get(asset_kind)
    path = Path(str(inspection.get(key or "") or ""))
    if not key or not path.exists() or not path_is_under(path, OUTPUT_DIR):
        raise HTTPException(status_code=404, detail="检验证据文件不存在")
    return FileResponse(path)


@app.post("/api/incoming-text/inspections/{inspection_id}/review")
def review_incoming_text_inspection(inspection_id: str, request: IncomingTextReviewRequest) -> dict[str, Any]:
    require_permission("inspection", detail="没有来料检验权限")
    inspection = load_incoming_text_inspection(inspection_id)
    if not inspection:
        raise HTTPException(status_code=404, detail="检验记录不存在")
    # Only the task owner (or a platform administrator) may disposition records.
    require_incoming_text_task(str(inspection.get("task_id") or ""))
    if inspection.get("auto_decision") != INCOMING_TEXT_REVIEW_REQUIRED:
        raise HTTPException(status_code=409, detail="只有需复核记录可以人工处理")
    decision = request.decision.strip().upper()
    if decision not in {"RELEASED", "REJECTED"}:
        raise HTTPException(status_code=400, detail="人工结论只能是 RELEASED 或 REJECTED")
    reason = request.reason.strip()
    if not reason or len(reason) > 500:
        raise HTTPException(status_code=400, detail="请填写 1–500 字复核原因")
    existing = str(inspection.get("final_decision") or "")
    if existing:
        if existing == decision:
            return incoming_text_public(inspection)
        raise HTTPException(status_code=409, detail="该记录已经作出不同的人工结论")
    reviewed_at = int(time.time())
    actor_user_id = str(current_auth_user().get("id") or "")
    repository = runtime_postgres_repository_or_none()
    if repository is not None:
        try:
            inspection = repository.review_incoming_text_inspection(
                inspection_id,
                decision=decision,
                reason=reason,
                actor_user_id=actor_user_id,
                reviewed_at=reviewed_at,
            )
        except Exception as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from None
    else:
        with _incoming_text_store_lock:
            inspections = _incoming_text_json_list(INCOMING_TEXT_INSPECTIONS_PATH)
            stored = next((item for item in inspections if str(item.get("id")) == inspection_id), None)
            if not stored:
                raise HTTPException(status_code=404, detail="检验记录不存在")
            stored_decision = str(stored.get("final_decision") or "")
            if stored_decision and stored_decision != decision:
                raise HTTPException(status_code=409, detail="该记录已经作出不同的人工结论")
            stored.update(
                {
                    "final_decision": decision,
                    "review_reason": reason,
                    "reviewed_at": reviewed_at,
                    "reviewed_by_user_id": actor_user_id,
                    "updated_at": reviewed_at,
                }
            )
            audit_event = {
                "id": f"incoming_review_{inspection_id}",
                "event_type": "incoming_text.reviewed",
                "created_at": reviewed_at,
                "actor_user_id": actor_user_id,
                "payload": {"inspection_id": inspection_id, "task_id": stored.get("task_id"), "decision": decision, "reason": reason},
            }
            audits = _incoming_text_json_list(INCOMING_TEXT_AUDIT_PATH)
            if not any(str(item.get("id")) == audit_event["id"] for item in audits):
                audits.insert(0, audit_event)
            _save_incoming_text_json_list(INCOMING_TEXT_INSPECTIONS_PATH, inspections)
            _save_incoming_text_json_list(INCOMING_TEXT_AUDIT_PATH, audits)
            inspection = stored
    return incoming_text_public(inspection)


@app.get("/api/incoming-text/inspections")
def list_incoming_text_inspections(
    task_id: str | None = None,
    material_code: str | None = None,
    decision: str | None = None,
    limit: int = 100,
) -> dict[str, Any]:
    require_permission("inspection", detail="没有来料检验权限")
    user = current_auth_user()
    normalized_decision = str(decision or "").strip().upper()
    visible_task_ids = {
        str(task.get("id"))
        for task in load_pipeline_tasks()
        if str(task.get("task_kind") or "") == "incoming_material_text" and incoming_text_task_access_allowed(task, user)
    }
    repository = runtime_postgres_repository_or_none()
    bounded = max(1, min(500, limit))
    if repository is not None:
        result = repository.list_incoming_text_inspections(
            task_ids=sorted(visible_task_ids),
            task_id=str(task_id or ""),
            material_code=str(material_code or ""),
            decision=normalized_decision,
            limit=bounded,
        )
        return {
            "items": [incoming_text_public(item) for item in row_raw_json_list(result.get("items") or [])],
            "total": int(result.get("total") or 0),
            "summary": result.get("summary") or {},
        }
    items = [item for item in load_incoming_text_inspections() if str(item.get("task_id")) in visible_task_ids]
    if task_id:
        items = [item for item in items if str(item.get("task_id")) == task_id]
    if material_code:
        items = [item for item in items if str(item.get("material_code")) == material_code]
    if normalized_decision:
        items = [item for item in items if normalized_decision in {str(item.get("auto_decision")), str(item.get("final_decision"))}]
    items.sort(key=lambda item: int(item.get("created_at") or 0), reverse=True)
    counts = Counter(str(item.get("final_decision") or item.get("auto_decision") or "UNKNOWN") for item in items)
    return {"items": [incoming_text_public(item) for item in items[:bounded]], "total": len(items), "summary": dict(counts)}


def purge_expired_incoming_text_evidence() -> dict[str, int]:
    """Delete only image evidence after the configured retention period."""
    retention_days = max(1, int(os.environ.get("VANTALINE_INCOMING_TEXT_IMAGE_RETENTION_DAYS", "90")))
    cutoff = int(time.time()) - retention_days * 86400
    repository = runtime_postgres_repository_or_none()
    candidates = (
        repository.incoming_text_retention_candidates(before_created_at=cutoff)
        if repository is not None
        else [item for item in load_incoming_text_inspections() if int(item.get("created_at") or 0) < cutoff and not item.get("evidence_purged_at")]
    )
    deleted_files = 0
    updated_records = 0
    for inspection in candidates:
        all_removed = True
        for key in ("source_path", "corrected_path", "annotated_path"):
            path = Path(str(inspection.get(key) or ""))
            if path.exists() and path_is_under(path, OUTPUT_DIR):
                try:
                    path.unlink()
                    deleted_files += 1
                except OSError:
                    all_removed = False
        if not all_removed:
            continue
        purged_at = int(time.time())
        if repository is not None:
            changed = repository.mark_incoming_text_evidence_purged(
                str(inspection.get("id") or ""), purged_at=purged_at, retention_days=retention_days
            )
        else:
            changed = False
            with _incoming_text_store_lock:
                values = _incoming_text_json_list(INCOMING_TEXT_INSPECTIONS_PATH)
                stored = next((item for item in values if str(item.get("id")) == str(inspection.get("id"))), None)
                if stored and not stored.get("evidence_purged_at"):
                    stored["evidence_purged_at"] = purged_at
                    stored["evidence_retention_days"] = retention_days
                    _save_incoming_text_json_list(INCOMING_TEXT_INSPECTIONS_PATH, values)
                    changed = True
        updated_records += int(changed)
    if updated_records:
        append_incoming_text_audit(
            {
                "id": f"incoming_retention_{cutoff // 86400}",
                "event_type": "incoming_text.evidence_retention_purge",
                "created_at": int(time.time()),
                "actor_user_id": SYSTEM_OWNER_ID,
                "payload": {"records": updated_records, "files": deleted_files, "retention_days": retention_days},
            }
        )
    return {"records": updated_records, "files": deleted_files}


DASHBOARD_AI_TASK_NAME = "Dashboard 快捷 AI 检测"


def upsert_dashboard_ai_task(accessory_id: str, config: dict[str, Any]) -> dict[str, Any]:
    accessories_by_id = accessory_lookup_by_id(config)
    tasks = load_ai_detection_tasks()
    # load_ai_detection_tasks 会把 source 归一化成 workbench,所以用固定名称识别看板任务。
    task = next((item for item in tasks if item.get("name") == DASHBOARD_AI_TASK_NAME), None)
    selected_ids = list(dict.fromkeys((task.get("selected_accessory_ids") if task else []) + [accessory_id]))
    selected_ids = [item_id for item_id in selected_ids if item_id in accessories_by_id]
    counts = {item_id: int((task or {}).get("required_accessory_counts", {}).get(item_id, 1) or 1) for item_id in selected_ids}
    labels = {item_id: str(accessories_by_id[item_id].get("name") or item_id) for item_id in selected_ids}
    payload = {
        "name": DASHBOARD_AI_TASK_NAME,
        "selected_accessory_ids": selected_ids,
        "required_accessory_counts": counts,
        "accessory_labels": labels,
        "source": PIPELINE_DASHBOARD_AI_TASK_SOURCE,
    }
    now = time.time()
    if task:
        task.update({**payload, "updated_at": now})
    else:
        task = {"id": f"aitask_{uuid.uuid4().hex[:10]}", "created_at": now, "updated_at": now, **current_owner_fields(), **payload}
        tasks.insert(0, task)
    save_ai_detection_task(task)
    return serialize_ai_detection_task(task, config)


@app.post("/api/accessories/{accessory_id}/route")
def set_accessory_route(accessory_id: str, request: AccessoryRouteRequest) -> dict[str, Any]:
    user = current_auth_user()
    route = str(request.route or "").strip()
    if route == "locate":
        removed_phase1_feature("LocateAnything accessory route")
    if route not in ACCESSORY_DETECTION_ROUTES:
        raise HTTPException(status_code=400, detail=f"未知的检测路线:{route}")
    config = load_config()
    item = next((entry for entry in config.get("accessories", []) if accessory_uid(entry) == accessory_id), None)
    if not item:
        raise HTTPException(status_code=404, detail="配件不存在")
    require_record_access(item, user, write=True)
    item["detection_route"] = route
    result: dict[str, Any] = {"accessory_id": accessory_id, "route": route}
    if route == "ai" and request.apply:
        try:
            ensure_accessory_ai_profile(item)
            result["profile_status"] = "ready"
        except Exception as exc:  # noqa: BLE001 - 画像生成失败不应阻塞路线切换
            result["profile_status"] = "failed"
            result["profile_error"] = str(exc)[:200]
        save_accessory_item(item, config)
        result["ai_task"] = upsert_dashboard_ai_task(accessory_id, config)
    else:
        save_accessory_item(item, config)
    result["accessory"] = serialize_accessory(item)
    return result


REACT_PRODUCTION_ROUTE_SEGMENTS = {
    "login",
    "status",
    "inspect",
    "ai-inspect",
    "accessories",
    "training-library",
    "tasks",
    "pipeline",
    "rules",
    "users",
    "data-analysis",
}
REACT_PRODUCTION_BLOCKED_PREFIXES = (
    "/api/",
    "/static/",
    "/outputs/",
    "/react-preview",
    "/legacy",
    "/favicon",
    "/apple-touch-icon",
    "/site.webmanifest",
)


def react_production_spa_enabled() -> bool:
    return True


@app.get("/{react_path:path}")
def react_production_spa(react_path: str) -> FileResponse:
    if not react_production_spa_enabled():
        raise HTTPException(status_code=404, detail="Not found")
    normalized = f"/{react_path.strip('/')}" if react_path else "/"
    if normalized == "/" or normalized.startswith(REACT_PRODUCTION_BLOCKED_PREFIXES):
        raise HTTPException(status_code=404, detail="Not found")
    first_segment = normalized.strip("/").split("/", 1)[0]
    if first_segment not in REACT_PRODUCTION_ROUTE_SEGMENTS:
        raise HTTPException(status_code=404, detail="Not found")
    index_path = REACT_PRODUCTION_DIST_DIR / "index.html"
    if not index_path.exists():
        raise HTTPException(status_code=404, detail="Production React build is not available")
    return FileResponse(
        index_path,
        headers={
            "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
            "Pragma": "no-cache",
        },
    )


@app.on_event("startup")
def resume_image_worker_queue() -> None:
    list_codex_image_jobs()
    if os.environ.get("LOCAL_INSPECTION_AUTO_RESUME_WORKER") == "1":
        start_image_worker()


@app.on_event("startup")
def enforce_incoming_text_image_retention() -> None:
    try:
        purge_expired_incoming_text_evidence()
    except Exception as exc:  # retention failure must not make inspection data unavailable
        print(f"[incoming-text.retention] skipped: {type(exc).__name__}", flush=True)


